INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18098462319', 'Par Farol Corsa Classic 2011 2012 2013 2014 2015 2016', 'PAR FAROL CORSA CLASSIC 2011 2012 2013 2014 2015 2016 DESCRIÇÃO DO PRODUTO Os faróis, sejam de luz baixa ou alta, tem como função iluminar o caminho de um veículo. Nesse sentido, é importante que os condutores saibam como fazer a regulagem correta dos faróis, pois um farol desregulado não ilumina adequadamente a rodovia ou ainda pode causar ofuscamento, perda de visão momentânea, no condutor do veículo que transita em sentido contrário. ESPECIFICAÇÕES DO PRODUTO: - Lente Lisa em Acrílico - Carcaça de Plástico - Mascara Cromada - Encaixe de lâmpada H4 (Não acompanha lâmpadas) Compatível com: - Corsa 2011 - Corsa 2012 - Corsa 2013 - Corsa 2014 - Corsa 2015 - Corsa 2016 - Classic 2011 - Classic 2012 - Classic 2013 - Classic 2014 - Classic 2015 - Classic 2016 Especificação Técnica: • Suporta Lâmpadas até 55W • Regulagem de Foco Manual • Foco Simples O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: •02 Faróis Principais FINALIZAÇÃO As imagens representam o real estado de conservação dos produtos. Mais detalhes e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra. Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 739.8, 739.8, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7qvfs-lg2fzdn6s01v7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F18098462319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23120987282', 'Garrafa Harry Potter que Muda de Cor Lumos 720ml Aço Inox Original Imaginarium', 'A Garrafa Muda de Cor Harry Potter Lumos da Imaginarium é perfeita para quem busca estilo e praticidade no dia a dia. Seu design anatômico garante conforto ao segurar, enquanto o acabamento em aço inoxidável traz resistência e durabilidade. Com capacidade de 720ml, é ideal para acompanhar você em casa, no trabalho, na academia ou em passeios ao ar livre, sempre com um toque de magia inspirado no universo Harry Potter. Principais benefícios: - Garrafa termossensível que muda de cor ao contato com líquidos gelados, revelando o feitiço Lumos Maxima. - Produzida em aço inoxidável e plástico de alta qualidade, garantindo resistência e longa vida útil. - Capacidade de 720ml, ideal para manter sua hidratação durante todo o dia. - Design ergonômico que oferece praticidade e conforto ao segurar. - Produto exclusivo para fãs de Harry Potter, unindo funcionalidade e estilo mágico em um só item.', 214.0, 214.0, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-23020-syca896ktzmv5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F789092088%2F23120987282', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40954052146', 'Z&D Lingerie Kit 2 Blusa Termica feminina Segunda Pele Térmica Manga Longa com Proteção tamanho único listrada lmny03', 'Bem-vindos a 【Z&D Lingerie】,Insistimos no menor preço para vender os melhores itens de qualidade!! ### Blusa Térmica Feminina Segunda Pele Térmica **Conforto e Estilo em Qualquer Ocasião** Apresentamos a Blusa Térmica Feminina Segunda Pele Térmica Manga Longa com Proteção, um item essencial para quem busca conforto e estilo. Com um design listrado moderno, esta blusa é perfeita para compor looks versáteis, seja para o dia a dia ou para atividades ao ar livre. **Proteção e Aquecimento** Desenvolvida com tecnologia de isolamento térmico, a blusa oferece proteção contra o frio, mantendo sua temperatura corporal estável. Ideal para os dias mais frios, ela proporciona uma sensação agradável e aconchegante, permitindo que você aproveite cada momento sem se preocupar com o clima. **Tamanho Único e Ajuste Perfeito** A Blusa Térmica é confeccionada em tamanho único, garantindo um ajuste confortável para diferentes tipos de corpo. Sua modelagem foi pensada para proporcionar liberdade de movimento, tornando-a uma escolha prática e funcional para qualquer ocasião. **Versatilidade e Praticidade** Com mangas longas e um design que combina com diversas peças do seu guarda-roupa, esta blusa é uma adição versátil que pode ser usada sozinha ou como uma camada adicional sob outras roupas. Seja para um passeio no parque ou uma atividade esportiva, ela se adapta perfeitamente ao seu estilo de vida. Experimente a Blusa Térmica Feminina Segunda Pele Térmica Manga Longa com Proteção e descubra o equilíbrio perfeito entre conforto, proteção e estilo!', 200.0, 59.99, NULL, 'Women Clothes > Lingerie & Underwear > Thermal Innerwear', 'https://cf.shopee.com.br/file/br-11134207-7r98o-maubkl44hqm184', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1189432015%2F40954052146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
