INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200763399', 'Jogo de Cama Casal Altenburg Haus Mia Rosa', 'Bordados delicados e elegância são detalhes inegáveis quando se fala sobre o Jogo de Cama Mia. Confeccionado 100% em algodão 300 fios, este jogo de cama proporciona o conforto ideal para as suas melhores noites de sono! Juntamente com o jogo de cama, temos sua embalagem, produzida com o mesmo material e com acabamentos exatamente iguais ao jogo de cama. Seu fechamento é com botões de Madrepérola - uma substância rica em calcário que é extraída da parte interna das conchas da praia. Este material é 100% natural e possui aspecto perolizado, tornando a embalagem ainda mais nobre.', 1600.0, 800.0, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-821fr-mh0wk680u8sr13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674300605%2F58200763399', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
