INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999499092', 'New Millen Isolate Protein Pote 900g Proteína da Carne', 'COMPOSIÇÃO DO ANÚCIO: 01 Isolate Protein Pote 900g - New Millen PROTEÍNA ISOLADA E HIDROLISADA O Isolate Protein é importante para a recuperação e/ou manutenção da massa muscular. Tem rápida absorção pelo organismo e fornece um alto teor de aminoácidos na porção. É totalmente inovador, possui ótimas vantagens principalmente por ser isento de gorduras, lactose e açúcares. Contribui com o ganho e a manutenção da massa muscular. Recomendado para dietas que necessitam de altas concentrações proteicas. INGREDIENTES: Proteína de origem bovina, aminoácidos: (Acetato de L-lisina, L-leucina, L- isoleucina, L-valina, L-fenilalanina, L-treonina, L-histidina, L-metionina e L-triptofano), aroma idêntico ao natural, espessante goma xantana, edulcorante sucralose e antiumectante dióxido de silício. ALÉRGICOS: PODE CONTER OVO, SOJA E AMENDOIM. NÃO CONTÉM GLÚTEN SUGESTÃO DE CONSUMO: Diluir 30g (1 copo dosador) em 200ml de água. Ingerir uma vez ao dia ou conforme orientação profissional. IMAGEM MERAMENTE ILUSTRATIVA TABELA PODE VARIAR CONFORME SABOR', 209.9, 169.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma1b3ysufxvdb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F418949963%2F19999499092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
