INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393745496', 'Pneu Traseiro Cg Fan Titan Start 150 160 Desenho De Bros', 'Pneu Traseiro Cg Fan Titan Start 150 160 Parrudo Desenho De Bros PRODUTO (**Remodelados**) 1 PNEU 90/90-18 TRASEIRO ECOLÓGICO TRASEIRO Medidas: 90-90/18 Carga: 250 Kg Aro: 18 Tipo: ECOLÓGICO Montagem: Usa câmara (não acompanha câmara) Aplicação em Motos: Honda Cg (todas) YBR (todas) MAX (todas) YES (todas) Dentre outras com roda aro 18. Os pneus ecológicos são uma opção econômica e sustentável para veículos, incluindo motos. Eles passam por um processo de renovação, no qual a banda de rodagem desgastada é removida e substituída por uma nova camada de borracha. Têm como objetivo prolongar a vida útil dos pneus, reduzindo o desperdício e o impacto ambiental associado à fabricação de pneus novos. Aqui estão algumas características e benefícios dos pneus ecológicos: Reutilização de materiais: A estrutura interna do pneu é mantida, incluindo a carcaça. Apenas a banda de rodagem é substituída. Isso permite a reutilização de uma grande parte do pneu original, reduzindo a necessidade de recursos naturais para a produção de pneus novos. Sustentabilidade: Ao escolher pneus ecológicos, você está contribuindo para a redução do desperdício de pneus descartados no meio ambiente. Ao optar por pneus ecológicos para sua moto, você estará escolhendo uma alternativa mais econômica e sustentável, contribuindo para a redução do desperdício e o cuidado com o meio ambiente. Garantia de 3 Meses Contra Defeito de Fabricação', 119.9, 119.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6rnls85cabrf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F695489389%2F22393745496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
