INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899543403', 'Tênis Reserva Rover V Preto - Masculino', 'Versatilidade e elegância que acompanham você do trabalho ao evento! Tênis Reserva Rover V Preto - Masculino Ficha Técnica: Marca: Reserva Cor: Preto com detalhes em marrom Gênero: Masculino Indicado: Uso casual, trabalho e eventos formais Cabedal: Couro macio Palmilha: Confortável e moldada - removível Lingueta: Acolchoada Forro: Dry fit com toque macio e respirável Solado: Borracha bicolor, com excelente aderência Fechamento: Atacador elástico canelado Altura do cano: Baixo Detalhes: Visual moderno com praticidade no calce, logo da Reserva na lingueta e na lateral Com design urbano e acabamento premium, o Tênis Reserva Rover V oferece o toque de estilo ideal para compor looks elegantes sem perder a funcionalidade. Porque investir: O cabedal em couro garante um visual sofisticado, perfeito para ambientes de trabalho ou ocasiões mais refinadas. O fechamento com atacador elástico facilita o calce e economiza tempo, enquanto o forro dry fit proporciona conforto e respirabilidade. A sola bicolor de borracha completa o conjunto com durabilidade e tração para todos os momentos. Conteúdo da embalagem: 1 par de Tênis Reserva Rover V Preto – Masculino', 699.99, 393.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82599-mqcf7rpuou0w0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1614877278%2F23899543403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
