INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492619183', 'Puzzle 60 peças T-Rex', 'Agora você pode ter um lindo quebra-cabeça com 60 peças, para você encaixar uma a uma até formar a imagem do T-Rex. Mais que um passatempo divertido, os quebra-cabeças desenvolvem o raciocínio, relaxam e se transformam num autêntico hobby. Quebra-cabeça de 60 peças Tamanho da imagem 30,8 x 22,4 cm A partir de 4 anos', 29.99, 29.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rbl3-lnstv64w09sc1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F23492619183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
