INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794074193', 'Top Feminino Mormaii Nadador Beach Sports C/ Bojo Estampado', 'TOP FEMININO MORMAII PRODUTO ORIGINAL A PRONTA ENTREGA Top Feminino Mormaii Playa Nadador com proteção UV50+ tem bojo e costas nadador com alça fina, decorte v, boa sustentação, confortável e perfeito para atividades de alto impacto e movimento. Ideal para a prática de exercícios físicos ou compor um look descontraído no dia a dia ou para pratica de esportes ao ar livre como Beach Tennis, FuteVolei entre outros esportes. Feito em tecido leve de secagem rápida, ideal para a prática esportiva. CARACTERÍSTICAS DO PRODUTO Composição:82% Poliéster e 18% Elastano Proteção Solar 50+ Com bojo removivél. MORMAII: A história da Mormaii começa nas belas praias da região sul do litoral brasileiro no início dos anos 70, fundada pelo então médico e surfista Morongo. Surge, assim, uma marca com raízes no surfe, mas com um objetivo maior: a busca pela qualidade de vida. Atualmente, a marca é reconhecida por mais de uma centena de produtos que atendem as categorias Surf, Mergulho, Skate, Fitness, Moda Praia, Bicicletas, além de produtos como óculos, relógios e chinelos, entre outros, tornando a Mormaii a maior e mais querida marca de esportes livres do Brasil.', 139.9, 139.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sports Bras', 'https://cf.shopee.com.br/file/br-11134207-7r98o-man1doe8607je9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F312703265%2F22794074193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
