INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698155247', 'Mesa Multiuso Casal Retrátil ME4170 c/ 2 Nichos Amêndoa - Tecno Mobili', 'Mesa Multiuso Escritório Retrátil ME4170 c/ 2 Nichos Amêndoa - Tecno Mobili Marca: Tecno Mobili Dimensões(Cm): Comprimento(Profundidade): 54cm x Largura: 136cm x Altura: 76,9cm Material de Estrutura - Estrutura 100% MDP Vantagens Extra dos Móveis de Escritório - Rodízios Tipo de puxador - Puxador em ABS / PVC Quantidade de Portas - 1 Porta de Abrir Quantidade de Gavetas - 1 Gaveta Quantidade de nichos - 2 Nichos Quantidade de Prateleiras - 1 Prateleira Garantia - Garantia de 90 dias Montagem do Produto - Desmontável Certificação de Qualidade - Qualidade Aprovada Imagens Meramente Ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Todas as informações divulgadas são de responsabilidade exclusiva do fabricante/fornecedor. -Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades - Confira as dimensões do produto e analise se irão passar normalmente por elevadores, portas, escadas e corredores, pois não nos responsabilizamos caso o produto necessite durante a entrega de: Desmontagem, subir escadas ou ser transportado por guincho, cordas para apartamentos. A entrega limita-se ao descarregamento em local que tenha e ofereça total facilidade de acesso normal; - Só fazemos entregas por transportes rodoviários. Não realizamos entregas por transportes fluviais, aéreos e outros diferente de rodoviário. Não realizamos entregas na região norte: Amapá, Amazonas, Pará, Roraima e Acre; - Temos áreas com restrição e dificuldades que os transportadores rodoviários não atendem. Área de difícil acesso, área de risco, área rural, áreas fluviais, estradas não pavimentadas; - Sendo assim, caso seu endereço esteja em área restrita de entrega, a retirada de sua compra deverá ser realizada no CD do transportador ou indicar no momento da compra um endereço entrega fora da área restrita; - Caso realize pedido com entregas em locais de difícil acesso ou áreas com restrição e dificuldades que os transportadores e proprio correios não atendem, a compra sera cancelada pela Costa Rica Colchões, com a devida comunicação e estorno do pagamento ao cliente.', 436.91, 415.07, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8262e-mldn8buhg26dcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235923910%2F18698155247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194952093', 'Cerveja Eisenbahn Pilsen Lata 350ml', 'A Eisenbahn Pilsen Lata 350ml é uma cerveja puro malte leve e com amargor na medida certa, ideal para ser apreciada bem gelada. De baixa fermentação e com teor alcoólico de 4,84%, a Eisenbahn Pilsen é o rótulo mais vendido da marca no Brasil. A cerveja possui cor dourada, aromas de malte e lúpulo e oferece um equilíbrio excelente entre o amargor e o doce. Harmonize a sua Eisenbahn Pilsen com frutos do mar, peixes e queijos. Fundada em Blumenau, a Eisenbahn é uma cerveja brasileira que tem alma alemã. Todas as cervejas produzidas pela fábrica seguem à risca a Lei Alemã da Pureza.', 4.79, 3.69, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-825af-mqnekq7607ibb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555175%2F23194952093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
