INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392890633', 'Kit Acabamento Quadrado Rose Gold 100% Metal 1/2 e 3/4 + Conversor Docol', 'A Softinox trabalha com uma ampla variedade de metais como torneiras, ralos, engates e muito mais. Buscamos sempre oferecer preços e produtos imbatíveis, sem abrir mão da qualidade de cada produto que você recebe em sua casa. Selecionamos a dedo os melhores produtos para que sua experiência de compra conosco seja inesquecível e duradoura. Descrição: O Kit Inclui Um conversor de acabamento Deca para Registros Docol, Possibilitando assim a instalação desse peoduto em bases de padrão Docol. O Acabamento Quadrado para Registro Volante em Metal, é uma solução elegante e funcional para melhorar a estética do seu ambiente e destaca-se por seu design quadrado moderno, acabamento em metal durável e compatibilidade perfeita com os padrões da marca. Com fácil instalação, versatilidade de uso em banheiros, cozinhas e áreas com registros volantes, esse acabamento não apenas proporciona funcionalidade, mas também aprimora esteticamente o visual do espaço, conferindo-lhe um toque refinado Informações Técnicas: -Acabamento P/ Registro Quadrado 3/4 Com Adaptador Docol; -Serve em Bases: 1/2 E 3/4 E 1 Polegada; -Registros de Pressão e Gaveta; -Fixação: Parede; -Uso: Geral; -Material: Liga de Cobre (Metal); -Acabamento: Rose Gold; -Acionamento: Convencional ou 1/4 de Volta. Marcas de registros compatíveis com este acabamento, serve em: SERVE APENAS PARA BASE DE REGISTRO DOCOL- ACABAMENTO MAIS ADAPTADOR Itens Inclusos: -1 Acabamento Completo (Canopla e Manopla); -1 Regulador de Canopla; -1 Chave Allen e Parafuso. + 1 Conversor de Acabamento Deca para Registros Docol TAGS: Acabamento, Quadrado, Registro, Volante, Metal, Padrão Docol, Rose, Design Moderno, Alta Qualidade, Durável, Praticidade, Banheiro, Registro de Água, Estilo Contemporâneo, Fácil Instalação, Conforto, Ambiente Organizado, Toque de Classe, Decoração, Uso Doméstico, Acabamento Rose Gold, Ambiente Residencial, Estilo Quadrado, Elegância, Modernidade, Padrão Deca.', 133.9, 56.9, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1ij6q7wd1gq3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F350194951%2F22392890633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210131037', 'Atum Ralado em Óleo Gomes da Costa', 'O Atum Ralado Gomes da Costa é a escolha perfeita para quem busca praticidade e sabor na cozinha. Já vem ralado, pronto para ser utilizado em diversas receitas, como patês, sanduíches, saladas e omeletes. Rico em ômega 3 e fonte de proteínas, o Atum Ralado Gomes da Costa é uma opção saudável e versátil para o seu dia a dia. Após aberto, retire o produto da lata e conserve em embalagem fechada, sob refrigeração.', 10.79, 10.79, NULL, 'Food & Beverages > Food Staples > Canned Food', 'https://cf.shopee.com.br/file/sg-11134201-825b1-mqnel4hut4we92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676552986%2F58210131037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
