INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398487003', 'Suporte Veicular Ugreen Smartphone Carro Ajustável Preto', 'Suporte Veicular Ugreen para Smartphone Carro Ajustável Preto Fixação Segura Visão Otimizada Acessório Essencial Direção Confortável Design Elegante Universal 1. Ajuste Flexível: O Suporte Veicular Ugreen oferece múltiplos ajustes de ângulo, garantindo que você possa posicionar seu smartphone na visão mais confortável e segura enquanto dirige. 2. Instalação Fácil e Rápida: Projetado para uma montagem simples e rápida, este suporte permite que você fixe seu smartphone com segurança e sem complicações, otimizando seu tempo. 3. Fixação Segura: Com um sistema de fixação robusto, o suporte mantém o smartphone estável durante a condução, evitando quedas e deslizamentos mesmo em estradas irregulares. 4. Design Elegante e Compacto: Além de funcional, o suporte veicular da Ugreen tem um design elegante e discreto, complementando o interior do seu carro sem ocupar muito espaço. 5. Compatibilidade Universal: Adequado para uma ampla gama de tamanhos de smartphones, este suporte é uma escolha versátil para qualquer motorista. Garantia de 90 dias.', 110.94, 110.94, NULL, 'Mobile & Gadgets > Accessories > Phone Grips', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9ogfyyplzcp5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F22398487003', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
