INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22110409185', 'Capacete Viseira Cristal Para Moto Aberto X Speed Masculino Vermelho Resistente Leve Tamanho 56 Fw3', '#Auto Equip# Descrição Capacete Aberto X OPEN SPEED Vermelho e Preto - FW3: Com design esportivo e diferenciado, o capacete FW3 é perfeito para todo motociclista. Leve, estiloso e confortável, este moderno capacete vem com entrada e saída de ar, é fabricado em ABS super resistente e possui certificado de segurança. O melhor para você motociclista andar por aí com muita segurança, conforto e estilo! Características: - Modelo: X OPEN SPEED - Cor: Vermelho e Preto - Tamanho: 56 - Casco em ABS Resistente - Abertura em 5 Estágios - Viseira Transparente em Policarbonato 2.0 mm - Forro Removível - Com Entrada e Saída de Ar - Peso: 1,180 kg - Produto Certificado pelo INMETRO Conteúdo da Embalagem: - 01 Capacete IMPORTANTE: Garantia de 3 meses Produto original e certificado Enviamos em até 24h úteis Utilize o campo de “Perguntas e respostas” e esclareça suas dúvidas com nosso suporte técnico.', 309.9, 309.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-22120-y0mb96j4wzkv2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402093902%2F22110409185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898355374', 'Pincel para quadro branco Dashlight Azul BRW', 'O Pincel para Quadro Branco Dashlight Azul BRW foi desenvolvido para oferecer alta performance, praticidade e longa durabilidade. Ideal para ambientes corporativos, salas de aula, conferências e qualquer espaço que exija comunicação visual clara e eficiente. Detalhes: - Ponta redonda - Não é recarregável - Secagem rápida: Permite escrever e apagar sem interrupções. - Perfeito para uso em ambientes profissionais e educacionais. - Facilita a escrita e limpeza, promovendo maior produtividade e organização. - Traço de 3mm: Ideal para escrever de forma legível em quadros brancos de qualquer tamanho. - Composição: Fabricado com resina termoplástica, tinta à base de água, corantes, aditivos e ponta de poliéster, garantindo maior resistência e qualidade.', 13.24, 13.24, NULL, 'Stationery > Writing & Correction > Markers', 'https://cf.shopee.com.br/file/sg-11134201-82626-ml51ikengn4fdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F22898355374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22005073197', 'Par Disco Freio S10 Trailblazer Dianteiro Ventilado Sem Cubo', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação Aplicação: Chevrolet S10 4X2 4x4 2017 a 2019 Trailblazer 2017 a 2022 Conteúdo Da Embalagem 2 Discos de freio Altura Total 61,50 mm Observação NIOBIUM STEEEL Tipo de Veículo para SUV''s e Caminhonetes Marca Líder no mercado em fornecimento de discos e tambores de freio, a Hipper Freio exporta seus produtos para mais de 20 países e para todo o território nacional. Detentora de um dos mais modernos parques de fundição e usinagem do Brasil, a empresa tem capacidade produtiva para mais de 8 milhões de peças/ano, divididos em mais de mil referências para as mais diversas aplicações nacionais importadas – através de suas linhas de produtos e sistemas de freios automotivos (Disco, Tambor e Cubo) Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia - 3 meses Imagem meramente ilustrativa Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 Valor referente ao par. Antes de realizar a compra, verifique se o diâmetro e quantidade de furos do disco em seu veículo é conforme a medida do anúncio. EAN 7898500319202 Código do Fabricante HF21G Posição Dianteiro Tipo de Disco Ventilado Cubo Sem Quantidade de Furos 6', 418.45, 418.45, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7rbk3-llte5qmhprveed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F22005073197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3193935357', 'Tinta cremosa facial com 10 cores 0503 Colormake', 'Tinta cremosa facial com 10 cores - 0503 - Colormake A tinta cremosa Colormake é a base de vaselina, o que a torna um item de maquiagem de alta performance pois não escorre com suor. É de fácil aplicação e para maior fixação e secagem utilize pó compacto translúcido Colormake ou sombras Colormake da mesma cor da tinta. Detalhes: - Com 10 cores sortidas. - 4 gramas cada pote.', 31.8, 31.8, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/sg-11134201-822wp-mo9q0tz0oydl46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F3193935357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
