INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23205965239', 'Kit 2 Creme Dental Colgate Natural Extracts Citrus e Eucalipto 90g', 'O Kit contém: 2 Cremes Dentais Colgate Natural Extracts Citrus e Eucalipto com 90g cada. Cuide naturalmente de sua boca com o creme dental Colgate® Natural Extracts Citrus e Eucalipto, com ação de defesa reforçada*. Pasta de dente com flúor, com uma embalagem 100% reciclável e um produto 100% vegano, não testado em animais. Descubra uma experiência incrível na escovação dos dentes graças ao sabor Citrus e Eucalipto, que revitaliza o seu sorriso e também deixa os dentes mais saudáveis. Colgate Natural Extracts é perfeito para manter os dentes limpos! Sua fórmula com ingredientes naturais permite que você desfrute de um sorriso saudável a todo o momento. *Fórmula com defesa reforçada Benefícios: O creme dental Colgate Natural Extracts Citrus e Eucalipto, com flúor, é uma explosão de sabores surpreendentes para o cuidado do seu sorriso com refrescância. Possui em sua fórmula extratos naturais de coco e gengibre, uma combinação inspirada na natureza que ajuda a deixar os dentes mais saudáveis, através de uma defesa reforçada, removendo as impurezas, com escovação regular. Possui uma fórmula 100% vegana, não testada em animais. Possui uma embalagem reciclável, a primeira da Colgate no Brasil. Experimente nossa linha completa, que conta, também, com outros sabores, além de fio dental e enxaguante, sabor Carvão Ativado e Menta.', 39.59, 39.59, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd4s-lvnca8uhjt8t36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F23205965239', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23296064384', 'Fralda Geriátrica Tena Slip Noturna G Leve 24 Pague 22', 'Fralda Geriátrica Descartável TENA Noturna é uma fralda unissex para usuários com pouca ou nenhuma mobilidade (acamados), indicada para incontinência severa. Proporciona máxima proteção durante toda a noite. • Possui um sistema de fechamento Multifix – que permitem ajustar o produto quantas vezes forem necessárias sem danificá-lo, garantindo uma adaptação segura e confortável ao corpo. • Possui controlador de odor e um núcleo de rápida absorção e elásticos nas costas – posicionados para dar segurança na posição deitada, além de barreiras protetores e uma camada de polpa dupla que mantem a urina longe da pele, mantendo-a seca, reduzindo significativamente o risco de irritações ou infecções cutâneas. • Zero % vazamento, eficácia comprovada por testes em laboratório e com usuários do produto – até 12h de proteção. • Cobertura Externa - Similar ao tecido, que proporciona suavidade e menos ruído, com melhor circulação de ar e sensação de frescor; com aloe vera.', 149.29, 149.29, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7qve0-li7n05rrk9c906', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F23296064384', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
