INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492376378', 'Skate Skateboard Mormaii Iniciante Semi Profissional Abec 5', 'SKATE SEMI PROFISSIONAL MORMAII PRODUTO ORIGINAL A PRONTA ENTREGA Skate semi profissional marca Mormaii, prensado com resina Epoxi e lâmina tingida, montado com peças de alta qualidade. Shapes produzido com 7 lâminas de madeiras selecionadas sendo 1 tingida, prensado com resina Epoxi , truck em liga de alumínio de alta resistência e eixo em aço. Rodas em TPU tamanho 53mm dureza 92A. CARACTERÍSTICAS DO PRODUTO: -Shape com 7 lâminas de madeiras selecionadas. -Truck de 129 mm em liga de alumínio e eixo em aço. -Roda 53 mm em tpu dureza da roda 92a -Lixa antiderrapante 80ab -Rolamento abec-5 -Dimensões (c x l): 80 cm x 19,5 cm suporta até 100 kg. MORMAII: A história da Mormaii começa nas belas praias da região sul do litoral brasileiro no início dos anos 70, fundada pelo então médico e surfista Morongo. Surge, assim, uma marca com raízes no surfe, mas com um objetivo maior: a busca pela qualidade de vida. Atualmente, a marca é reconhecida por mais de uma centena de produtos que atendem as categorias Surf, Mergulho, Skate, Fitness, Moda Praia, Bicicletas, além de produtos como óculos, relógios e chinelos, entre outros, tornando a Mormaii a maior e mais querida marca de esportes livres do Brasil.', 399.9, 399.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Boardsports', 'https://cf.shopee.com.br/file/br-11134207-7r98r-llm9xh3j2kerc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F312703265%2F23492376378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
