INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13346323056', 'Shampoo Palmolive Naturals Kids Cabelo Cacheado 350ml', 'Cabelo cacheado é lindo, mas requer mais cuidado para ficar macio e definido. Para conseguir esse resultado foi desenvolvida a linha de shampoo e condicionador Palmolive® Naturals Kids para Cabelo Cacheado que proporciona um banho divertido e sem lágrimas para crianças a partir de 4 anos. Dermatologicamente testado Hidrata e perfuma os cachinhos, deixando-os extra macios, sem nós Limpa suavemente os cabelos deixando- os mais fáceis de pentear Embalagem divertida com jogos e passatempos para a hora do banho', 25.79, 17.01, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/2adf76ad1315facc97badff048e9c118', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F13346323056', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397613872', 'Bancada Retrô com Painel para TV de até 50 Polegadas Notável Off White / Freijó Trend', 'Sua sala de estar ficará muito mais bonita e aconchegante com o Conjunto Notável! Proporcionando beleza, modernidade e bom gosto ao ambiente. Ideal para TVs de até 50". Além de ser um produto fácil de montar, é um item completo, que não só comporta sua TV, mas conta com uma prateleira para acomodar seus aparelhos eletrônicos, e objetos decorativos. A bancada retrô possui duas portas deslizantes, garantindo flexibilidade a você. Com o conjunto Notável, sua única tarefa será se aconchegar no sofá para assistir sua série favorita. MEDIDAS: Medidas do Combo (Painel + Rack): [ A ] = 162,5 cm [ L ] = 135,6 cm [ P ] = 35,8 cm MEDIDAS PAINEL: [ A ] = 105,8 cm x [ L ] = 135,3 cm x [ P ] = 20,3 cm MEDIDAS RACK: [ A ] = 56,7 cm x [ L ] = 135,6 cm x [ P ] = 35,8 cm SUPORTA TV ATÉ: 50 Polegadas PESO TOTAL DO PRODUTO: 75 kg MODELO: Rack com Painel para TV de até 50 Polegadas MARCA: Notável COR: Off White / Freijó Trend ACABAMENTO: Fosco PINTURA: UV PORTAS: 2 TIPO DE PORTA: Deslizante NICHO: 2 PÉS: 4 ESPAÇO PARA EQUIPAMENTOS ELETRÔNICOS: Sim ESPELHOS: Não VIDROS: Não PASSA CABOS: Sim ITENS INCLUSOS: 1 Painel e 1 Rack GARANTIA: 3 meses A Esplanada Móveis se responsabiliza pela entrega dos produtos adquiridos até a porta de entrada ou portaria do endereço indicado, se a portaria do condomínio permitir, as entregas são efetuadas no piso térreo e é de responsabilidade do cliente a locomoção da mercadoria até seu apartamento ou casa.', 499.0, 499.0, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-8257w-mgcb5ufvaww861', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097902002%2F19397613872', NULL, NULL, '2026-07-28