INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698669739', 'Cadeira de Praia Alta Relax Comfort em Alumínio - Bel', 'Cadeira de Praia Alta Relax Comfort em Alumínio - Bel Conforto, estilo e funcionalidade se unem na Cadeira Alta Relax Comfort da Bel. Ideal para momentos de descanso à beira-mar, no camping ou até mesmo no quintal, ela foi desenvolvida com foco na ergonomia e praticidade, proporcionando bem-estar em qualquer ambiente. Com encosto alto e assento mais largo, essa cadeira oferece maior suporte à coluna e mais espaço para o usuário, garantindo máximo conforto durante o uso. O apoio de braço em tom cinza adiciona um toque de modernidade ao design, enquanto a estrutura em alumínio com tubos reforçados garante durabilidade e resistência, mesmo com uso constante ao ar livre. A tela da cadeira é produzida em poliéster 100% com revestimento em PVC, oferecendo fácil limpeza e excelente resistência aos elementos naturais. Além disso, seu assento está posicionado a 41 cm do chão, altura ideal para facilitar o sentar e levantar. Dobrável e leve, é prática para transportar e guardar, tornando-se a companheira perfeita para aproveitar os momentos de lazer com conforto e segurança. Especificações Marca: Bel Modelo: Alta Relax Comfort Material: 100% Poliéster com revestimento em PVC, Alumínio Medidas: A 90 cm x L 58 cm x C 57 cm Altura do assento: 41 cm Peso suportado: 120 kg Dobrável: Sim', 219.9, 139.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbduo41tjiq782', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F23698669739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
