INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21474700049', 'Quebra Cabeça Mickey Mouse Números - Toyster 8020', 'Se você está procurando um brinquedo que seja divertido e, além disso, traga benefícios para o seu pequeno ou pequena, então esse é o brinquedo que você está procurando. O quebra cabeça irá desenvolver a coordenação motora da criança, noção de espaço, brincadeira em grupo, paciência, atenção e muito mais. Junte a família e se divirta montando esse lindo quebra cabeça. Com o quebra cabeça do Mickey Montando os números de 1 a 20 o seu filho(a) irá aprender os números brincando, cada peça possui um número e uma imagem representando a quantidade desse número, como dizemos por aqui: “brincar é aprender a viver”. Imagens meramente ilustrativas. • Idade: +4 anos • Quantidade de peças: 20', 24.19, 24.19, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134201-23030-78niqaupj4nv81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F21474700049', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797139655', 'O Coração Missionário de Jonathan Edwards | Rennan Dias', 'Jonathan Edwards (1703-1758) é conhecido no Brasil e no mundo principalmente por ser o teólogo do avivamento. Todavia, Edwards não recebe o devido crédito como missionário. Embora tenha trabalhado por sete anos no campo missionário no oeste de Massachussets entre índios, há muitos estudiosos que não exploram suas contribuições nessa área… Por que um pastor e teólogo tão inteligente e já respeitado escolheria o campo missionário ao invés de aceitar um convite para pastorear no continente europeu, por exemplo? Essa é a história que Rennan Dias conta neste livro. Rennan é um pastor com habilidades que fazem deste livro um deleite para a leitura. Primeiramente, ele gosta de escrever e tem se mostrado um hábil escritor que facilita a digestão do leitor através de uma escrita agradável e fluida. Em segundo lugar, ele fez uma boa pesquisa explorando tanto a literatura sobre Edwards quanto alguns de seus escritos com um insight para uma “teologia missionária”. Em terceiro, como pastor que é, Rennan gosta de aplicar quando ensina. Neste livro temos não só um relato histórico, mas uma aplicação que nos encoraja a um maior envolvimento com missões. Prepare-se para essa viagem no tempo e que o nosso Deus desperte ao menos alguns leitores a almejarem alcançar os que estão distantes! 14x21cm 141 Páginas', 33.9, 33.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbmj-lnz5p5wdjc3p43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22797139655', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13451370379', 'O Que Aconteceu Com A Raça Humana? - Francis Schaeffer', '“Se uma mulher pode matar os próprios filhos, então o que ocorrerá depois?”, uma vez perguntou madre Teresa. De fato, o que pode? com a depreciação do valor da vida humana, como nos casos roe versus wade e baby doe, ninguém está a salvo. Com a substituição do valor absoluto da própria vida humana pela “qualidade de vida”, todos corremos perigo. 252 Páginas 14x21cm', 40.9, 40.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/77c0187bc1f7c2295b94f9e0e2a92838', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F13451370379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
