INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793412543', 'Caneca Pop Gremlins - Warner', 'Vai sair para viver aventuras incríveis, você não encontrou uma caneca que te acompanhe no seu cafézinho? A gente te ajuda! Com 350ml de capacidade, e feita em porcelana, essa caneca é a parceira ideal para todas as suas aventuras! Obs: Não molhar e não expor a luz após a 00h a caneca pode sofrer com transformações. O produto é produzido em território nacional, possui detalhes incríveis que vão fazer você se apaixonar! Feita em porcelana, com estampa em alta qualidade e 350ml é a companhia perfeita para deixar a hora do seu café muito mais divertida! Não importa se você é uma pessoa hidratada ou não, essa caneca vai te ajudar a salvar o dia! Especificações: Altura: 9,5cm| Largura: 8cm| Comprimento: 8cm| Material: Porcelana| Capacidade: 350ml Cuidados e recomendações de uso: Lavar com água, esponja macia e detergente neutro. Não vai ao micro-ondas, nem a lava-louças. Não utilizar químicos e abrasivos. Choques ou quedas podem trincar ou quebrar o produto, pois trata-se de um produto de Porcelana', 54.9, 54.9, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-822z7-moelirm3f9cb01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23793412543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
