INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43358635524', 'Bungo stray dogs vol. 19 - Panini', 'Quem salvou Sigma da queda do Cassino do Firmamento foi o mágico Gogol, que todos acreditavam estar morto. Para matar seu grande amigo, Dostoiévski, Gogol pede a ajuda de Sigma. Kunikida e os outros vão desaparecendo um a um com o plano de assassinato de Kamui, da Queda do Anjo. Mas enquanto "aquele homem" estiver na agência, qualquer situação difícil será superada. Não há noite que não termine... O sinal de fumaça indicando a volta da agência começou a subir para os céus.', 44.67, 44.67, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rdvh-mc8eqo3rqtuh74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F43358635524', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
