INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092810685', 'Camisa Básica Masculina Polo Gola Esporte Em Meia Malha', 'Camisa Polo Básica Malwee confeccionada em meia malha. Modelo possui modelagem tradicional, que acompanha as linhas do corpo com muito conforto, mangas curtas, gola esporte e fechamento por peitilho com 2 botões. As camisas polo Malwee são atemporais e indispensáveis no guarda-roupa masculino por serem versáteis, confortáveis e feitas para durar, já que possuem a melhor durabilidade do mercado. A meia malha é um tecido leve, com muito frescor e molda-se perfeitamente ao corpo com bom caimento. Modelagem: TradicionalGola: Esporte', 89.9, 80.91, NULL, 'Men Clothes > Tops > Polo Shirts', 'https://cf.shopee.com.br/file/sg-11134201-7rbmr-lql10aay3n8g29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F22092810685', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
