INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893724644', 'TAPETE CARPETE ASSOALHO HONDA HRV 2015/2021 PRETO FOSCO', 'VANTAGENS DO PRODUTO - Impermeabilização total do carpete do veículo; - Antialérgico; - Facilita a limpeza; - Não tendo nenhum objeto cortante, o tapete pode durar anos; - Praticidade para consumidores que residem em regiões rurais, urbanas, litorâneas e demais; - Praticidade para consumidores que tem crianças, principalmente pequenas; - Praticidade em épocas chuvosas e secas. DICAS DE INSTALAÇÃO - Retire os bancos do assoalho do veículo; - Desconecte os fios debaixo dos bancos; - Retire os parafusos ou presilhas que fixam o console central, de mode que fique solto, as vezes não sendo necessário a retirada de dentro do veículo; - Retire as soleiras das portas; Para veículos que o banco traseiro levanta, não é preciso fazer a retirada do banco; - Coloque o tapete sobre o assoalho e aperte os cantos juntamente com os encaixando e grudando no carpete; - Passe os fios que conectam aos bancos por cima do tapete; Ajustando, faça um pequeno furo permitindo que seja parafusado ao banco; - Coloque as soleiras do veículo; - Coloque os bancos dentro do veículo e aperte os parafusos dos bancos; - Para veículos que possuem travado tapete ao lado do motorista, faça um corte menor por cima da trava embutindo o material por baixo da trava; - Aperte os parafusos ou presilhas do console central; A instalação deve ser realizada por um profissional especializado, não nos responsabilizamos pelo uso incorreto ou instalação inadequada.', 385.0, 385.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/sg-11134201-7rce3-m6io897g2nmx15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1410324431%2F22893724644', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999252475', 'Licor Stock Gold de Marula 720ml', 'Características Principais do Produto: Marca: Stock Sabor: Marula Volume: 720ml Graduação Alcoólica: 15% Vol Informações Adicionais do Produto: É um licor exótico feito da fruta Marula, que é originária da África. Esta fruta tem alto teor de vitamina C, e rica em sais minerais e vitaminas. A utilização do Licor Stock Gold de Marula em coquetéis e na culinária, imprime um toque de diferenciação e exotismo. Dimensões do Produto: Altura: 28,73 cm Largura: 8,91 cm Comprimento/Profundidade: 6,91 cm Fornecedor: Distillerie Stock do Brasil', 89.25, 69.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-824jl-mpibos8sizggc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F18999252475', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
