INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18151652712', 'Fertilizante Forth Orquideas Floração 500ml - Envio imediato', '- Fertilizante balanceado que contém tudo que sua planta precisa para crescer forte e saudável; - Sua fórmula completa favorece o crescimento, floração e frutificação; - Disponível em embalagem com 500ml. Detalhes Se sua orquídea começou a soltar haste floral ou botões de flores, utilize esse adubo, vai ajudar a dar mais flor e por mais tempo. Então não dorme no ponto, porque ela vai precisar de bastante energia, afinal pra manter tanta flor não é fácil. Dicas Especiais Utilização: Aplicação via foliar: pronto pra uso a cada semana, Pulverizar as folhas nas horas mais frescas do dia. Composição Nitrogênio total (N) = 2% Fósforo (P2O5) = 14% Potássio (K2O) = 8% Cálcio (Ca)= 1% Magnésio (Mg) = 0,5% Boro (B) = 0,25% Ferro (Fe) = 0,1% Molibdênio (Mo) = 0,05% Cobre (Cu) = 0,1% Manganês (Mn) = 0,25% Zinco (Zn) = 0,5% Elementos derivados de nitratos, fosfatos, sulfatos e micro elementos.', 49.46, 21.66, NULL, 'Home & Living > Gardening > Fertilizer', 'https://cf.shopee.com.br/file/br-11134201-23020-juj1khz711mvac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F18151652712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
