INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12109034757', 'Condicionador TRESemmé TRESplex Regeneração 400 ML', '•Condicionador TRESemmé Regeneração TRESplex com ação intra-capilar, que repara a camada mais profunda dos fios para fibras intensamente regeneradas e até 100x mais fortes* •Este Condicionador foi desenvolvido com queratina líquida e gluconolactona, que reparam a camada mais profunda dos fios, fortalecendo e protegendo os cabelos extremamente danificados •Condicionador que resgata cabelos com danos extremos, com proteção anti-danos •Recupera os cabelos contra danos extremos causados por química e ferramentas térmicas •A linha TRESemmé Regeneração Tresplex restaura os danos intra-capilares dos cabelos extremamente danificados •O Condicionador TRESemmé Regeneração Tresplex é aprovado por 9 em cada 10 cabeleireiros Cabelos 100x mais fortes com TRESemmé Regeneração TRESplex. Conheça a fórmula do Condicionador TRESemmé Regeneração Tresplex que regenera e condiciona os fios, recuperando as fibras capilares e devolvendo sua elasticidade e suavidade. Utilizado por muitos cabeleireiros, a linha promove um tratamento de salão em casa!', 38.59, 30.0, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/1aea7b0a3cdee3e67ee49aa2001c05fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F12109034757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24534749668', 'SUNGBOON EDITOR Creme Ativo De Cápsula De Astaxantina Marinha /150g), (50g', 'Creme de cápsula de astaxantina marinha ativa SUNGBOON EDITOR (50g / 150g) Descrição do produto Um creme facial rico em vitaminas que ajuda a corrigir o tom da pele irregular e restaurar uma tez jovem. Formulado com astaxantina que melhora a aparência da pele sem brilho e áspera. Ajuda a revelar uma tez translúcida. Teste de irritação da pele concluído. Como usar Aplique uma quantidade moderada do creme e deixe absorver suavemente. Aplique uma quantidade moderada do creme e deixe absorver suavemente. Ingredientes Extrato de frutas de rinoides hipofato, glicerina, glicerina, glicerina-26, niacinamida, caprílico/cáprico/triglicerídeo sucínico, água purificada, butilenoglicol, 1,2-hexanodiol, polígeno hidrogenado (C6-14 olefina), poligliceril-4 caprato, astaxantina (110ppm), óleo de Haematococcus Pluvialis (62,5ppm), Gluconolactona, Gliceril Glucoside, Xilitylglucoside, Anidroxilitol, Carhamus Tinctorius (girassol) Óleo de sementes, Adenosina, Xilitol, Bisabolol, Ácido Tranexâmico, Glutationa, Óleo de Frutas de Rhamnoides Hipofae, Óleo de Semente de Moringa Oleifera, Glicose, Tocoferol, Extrato de Folha de Biota Orientalis, Zanthoxilum Extrato de fruta de Piperitum Piperitum, Ubiquinone, Extrato de Eclipta Prostrata, Extrato de folha de Melia Azadirachta, Extrato de raiz de Polygonum Cuspidatum, Olivato de Cetearil, Olivato de Sorbitan, Acriloildimetiltaurato de amônio/Copolímero VP, Carbômero, Arginina, Caprilil Glicol, Etilhexilglicerina, Agar, EDTA Dissódico', 84.71, 84.71, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134207-7rdyv-lyxgvuf5lxxj12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F245347496