INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797178555', 'Aparelho Depilatório Prestobarba 3 Feminino com 2un', 'O Aparelho para Depilação Prestobarba 3 Feminino contém molas que são independentes em suas lâminas, desenvolvidas para o corpo feminino, a lubrificação é feita da extração de óleos botânicos. O aparelho conta com 3 lâminas montadas sobre molas independentes, cabeça móvel, fita lubrificante com 3 vezes mais lubrificação e ainda com um toque de óleos botânicos para que as lâminas deslizem mais facilmente. O Prestobarba 3 foi desenvolvido pensando exclusivamente no corpo da mulher, por isso você tem uma depilação mais rente e suave. Modo de uso: Antes de fazer a depilação, lave a pele com água morna para abrir os poros e remover a oleosidade. Aplique o sabonete ou creme, fazendo movimentos circulares para cobrir todas as partes que serão depiladas. Passe o aparelho de depilar de maneira suave no sentido do pelo. Em seguida, lave a pele com água fria para fechar os poros. #html-body [data-pb-style="646BA64E81C2B"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64E81C3F"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 31.2, 31.2, NULL, 'Beauty > Beauty Tools > Hair Removal Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbl8-lp5bafxsrua05f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23797178555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
