INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597590833', 'Kit 10 Lâmpada 1 Polo Halogena 1141 12V 21W BA15S Laranja', 'O Kit de 10 Lâmpadas 1 Polo Halógena oferece uma solução econômica e confiável para suas necessidades de iluminação automotiva. Com sua tecnologia halógena avançada, estas lâmpadas proporcionam uma luz âmbar brilhante e nítida, ideal para sinalização e indicadores do seu veículo. Especificações Técnicas: Tensão de Operação: 12V Potência: 21W Modelo: 1141 BA15S Cor da Luz: Âmbar Tipo: Halógena Conteúdo da Embalagem: 10 Kit 10 Lâmpada 1 Polo Halogena 1141 12V 21W BA15S Laranja 10NTV195', 24.9, 24.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rd65-lwfv42djhpn090', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F22597590833', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55856141823', 'CONSOLE CENTRAL UNIVERSAL AUTOMOTIVO 2 PORTA COPOS TIPO STANLEY COM PORTA OBJETOS GRANDE PARA CARRO', 'CONSOLE CENTRAL 2 COPOS COM PORTA OBJETOS UNIVERSAL Organize e modernize o interior do seu veículo com mais praticidade e funcionalidade. Este console central universal foi desenvolvido para oferecer versatilidade, podendo ser instalado em diversos veículos, desde que o local de instalação seja compatível com as medidas informadas no anúncio. Produzido em material resistente, o console conta com dois porta-copos ampliados, compatíveis com copos tipo Stanley, além de um porta-objetos funcional, ideal para armazenar pequenos itens do dia a dia como celular, chaves, moedas ou carteira. Um acessório que une organização, tecnologia e acabamento profissional, valorizando o interior do carro e trazendo mais conforto no uso diário. ESPECIFICAÇÕES DO CONSOLE: Aplicação: Universal (verificar medidas antes da instalação) Material: Plástico ABS Acabamento: Texturizado Cor: Preto Fixação: 2 parafusos Manutenção: Limpeza simples com pano úmido CAPACIDADE: 2 porta-copos ampliados (compatível com copos tipo Stanley) 1 compartimento porta-objetos MEDIDAS APROXIMADAS: Comprimento total: 21,7 cm Largura total: 9,8 cm Largura do porta-copos: 8 cm Altura total: 6 cm Altura do porta-copos: 5,7 cm Altura do porta-objetos: 5,7 cm Comprimento do porta-objetos: 9,2 cm Observação: Antes da compra, verifique as medidas do local de instalação e compare com as dimensões informadas no anúncio. CONTEÚDO DA EMBALAGEM: 1 Console central universal com 2 porta-copos e porta-objetos 2 Parafusos para fixação Imagens meramente ilustrativas NTV1820', 89.9, 89.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Cup Holder & Organizers', 'https://cf.shopee.com.b