INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209913569', 'Batedeira Arno Mini Chef HM11 220v', 'Com a Mini Chef o momento de cozinhar a se torna ainda mais completo. Além de possuir 200W e 4 velocidades incluindo a função pulsar, acompanha 2 tigelas de 4L que podem ser levadas no freezer e microondas. Possui 1 par de batedores multi funcionais para um preparo de massas, recheios e coberturas. Além disso, pode ser usada sem o pedestal, para maior controle e preciso para o preparo de merengues e chantilys. Características: Marca: Arno Modelo: HM11 Potência (Watts): 200W Consumo (kW/h/ms): 2,4 kW/h/ms Número de Velocidades: 4 Velocidades + Pulsar Tipo de Material: Plástico Comp. Cabo (cm): 120cm Volume: 4 Litros Tipo de Embalagem Individual: Caixa Conteúdo da Embalagem: 01 Mini Chef 02 Tigelas 01 Par de Batedores 01 Certificado de Garantia Dimensões: Altura: 48,6 cm Largura: 35,6 cm Profundidade: 22 cm Peso: 0,87 Kg Garantia do Fabricante: 12 Meses', 232.9, 209.61, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/br-11134207-820md-mpcnbfqtpw5d38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F745165277%2F58209913569', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
