INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42450209270', 'Bota Infantil Menina Kidy Baby Soft Moda Boho Marrom Cano Médio Delicada Antiderrapante Confortável', 'Delicada, charmosa e pensada com todo o cuidado que seu bebê merece, a Bota Infantil Kidy Baby Soft Boho é ideal para os primeiros passos com segurança e muito estilo! O tom caramelo combina com tudo, enquanto o acabamento suave e os detalhes em alto relevo trazem um toque especial ao visual. Esse modelo conta com a exclusiva tecnologia do Equilíbrio, que ajuda no desenvolvimento correto da pisada, oferecendo mais estabilidade e conforto aos pezinhos em fase de crescimento. O fechamento por zíper facilita o calce e garante praticidade para os pais na hora de vestir. O solado em TR antiderrapante proporciona firmeza ao caminhar, evitando escorregões e deixando os passos mais seguros. Um calçado valioso para acompanhar sua pequena com estilo e proteção em cada descoberta!', 179.99, 179.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Boots', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9itznzxklkp5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F42450209270', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
