INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12031289462', 'Kit Whey Protein 500g + Power Creatina 100g + Power Glutamina 100g + BCAA 100g - Bodybuilders', '➡️WHEY PROTEIN: ➡️SUGESTÃO DE CONSUMO: ⚡Adicionar 50g (5 colheres de sopa) em 300mL (1 ½ copo) de água gelada e agite por 20 segundos. Consumir imediatamente após o preparo! ➡️POWER CREATINA: (🍊SABOR TANGERINA🍊) ➡️Sugestão de uso: ⚡Adicionar 6g (2 colheres de café rasas) em 100mL (½ copo) de água. Consumir imediatamente após o preparo! ➡️POWER GLUTAMINA: ➡️SUGESTÃO DE CONSUMO: ⚡Adicionar 5g (1 colher de chá rasa) em 100ml de água. Consumir imediatamente após o preparo! ➡️BCAA 4,5: (🍊SABOR TANGERINA🍊) ➡️Sugestão de uso: ⚡Misturar 5g (1 colher de chá) em 200 ml (1 copo de água). Consumir imediatamente após o preparo! -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- ➡️NOTA: ⚡Antes de iniciar o uso de qualquer suplemento, é aconselhável consultar um profissional de saúde ou nutricionista para determinar se ele é apropriado para suas necessidades e objetivos individuais. Além disso, é fundamental seguir as instruções de dosagem e não exceder as recomendações do fabricante.⚡', 79.9, 71.91, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81z1k-miegt8ja9k3n9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F555509944%2F12031289462', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
