INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397616704', 'Aparador de Pelos 10 em 1 Mondial Super Groom BG03 - Bivolt', 'A Super Groom BG03 é uma máquina aparadora de pelos 10 em 1 da Mondial. Em suas funções, você encontra aparador de cabelo, aparador de barba e bigode, aparador de precisão, micro barbeador, aparador de nariz e orelha, 4 pentes de corte e 1 pente com regulagem de altura com 16 comprimentos. A máquina conta com lâminas de aço Inox, o que proporciona maior durabilidade. E falando em durabilidade, você pode usar a máquina aparadora por até 90 minutos sem interrupções. Com seu design moderno, possui uso sem fio e luz indicadora de carregamento. Aproveite a oportunidade e compre a sua hoje! Beleza no Dia a Dia Tenha um verdadeiro combo de cuidados para uma aparência sempre jovial. Com o aparador da Mondial você terá muita praticidade e rapidez e você mesmo vai poder cuidar do corte do seu cabelo, aparar a sua barba e remover aqueles pelos incômodos do nariz e ouvido. Aposte no Aparador de Pelos 10 Em 1 Mondial Super Groom BG03 para deixar esse passo a passo mais simples!', 169.9, 139.9, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-825ai-mr1pvn09wkch10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F20397616704', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
