INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397938144', 'Vela Iridium + Cachimbo Pcx 150 2013-2018 Original Ngk', 'Kit Vela Iridium + Cachimbo de Vela NGK Conteúdo da Embalagem: 01 Vela de Ignição Iridium NGK 01 Cachimbo de Vela NGK Compatível com: HONDA PCX 150 2013 PCX 150 2014 PCX 150 2015 PCX 150 2016 PCX 150 2017 PCX 150 2018 Garanta uma ignição perfeita, sem falhas ou fugas de corrente. O resistor é feito com materiais que proporciona valor de resistência constante no decorrer do uso. Ótimo isolamento elétrico, resistência a altas temperaturas, ótima supressão de interferência, boa vedação a umidade. As velas de ignição da NGK atendem os mais rígidos requisitos e testes das montadoras tanto em desempenho, tecnologia e durabilidade. Disponibilizando ao mercado a mais moderna tecnologia desenvolvida para velas de ignição. Os eletrodos fabricados com uma liga especial de níquel garantem uma alta durabilidade. Características Vela: - Ótimo isolamento elétrico - Resistência a altas temperaturas - Ótima supressão de interferência - Boa vedação a umidade - Melhor ignição e resposta na aceleração - Economia de combustível - Alta resistência à corrosão, calor e desgaste elétrico - Vedação com junta tripla que evita fuga de corrente - Projetada para quem procura o melhor desempenho Características Cachimbo de Vela: - Ótimo isolamento elétrico;- Resistência a altas temperaturas;- Ótima supressão de interferência;- Boa vedação a umidade; Importante: Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 169.9, 144.42, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rdxx-m0x381hldu1330', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F18397938144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
