INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209451850', 'Leite Pó Instantâneo Integral Ninho Lata', 'O Leite em Pó Integral Instantâneo Ninho é perfeito para você. É feito a partir de leite de vaca integral, que é desidratado para transformá-lo em pó. Além disso, ele é rico em Cálcio e Fonte de Ferro, Zinco e Vitaminas A, C, D e E. *Utilize somente água previamente fervida ou filtrada.* Para preparar 1 copo de 200ml: Em um copo com água morna ou fria (180ml), coloque 2 colheres de sopa (25g) de Ninho leite integral instantâneo e misture bem. Rendimento: 15 copos.', 27.79, 27.79, NULL, 'Food & Beverages > Dairy & Eggs > Milk', 'https://cf.shopee.com.br/file/sg-11134201-8258u-mqnel1aaiakg05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554909%2F58209451850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
