INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799355478', 'Lego Minecraft Aventura em Taiga do Steve - 21583', 'Leve a experiência de jogo de Minecraft para o próximo nível com a Aventura na Taiga do Steve (21583), um conjunto de construção colecionável para meninos e meninas a partir de 6 anos. Este pequeno conjunto LEGO está repleto de ação de batalha, caça ao tesouro e diversão explosiva para as crianças explorarem com uma minifigura do Steve, além de figuras LEGO de um Creeper, uma raposa e um coelhinho. • Entre na ação de batalha do Minecraft, na caça ao tesouro e na diversão explosiva com este conjunto LEGO (21583) para meninos, meninas e crianças a partir de 6 anos que adoram brinquedos relacionados a jogos. •Construa aventuras ambientadas no bioma da taiga com uma minifigura do Steve, além de um Creeper e 2 figuras de animais do Minecraft: uma raposa e um coelhinho. •Este conjunto de 79 peças mede mais de 8 cm de altura, 8 cm de largura e 6 cm de profundidade. Marca: Lego Código Fabricante: 21583 Número de Peças: 79 Idade mínima recomendada: 6 anos Dimensões da Embalagem (AxLxC): 12 x 14 x 4cm Garantia do Fabricante: 90 dias contra defeitos de fabricação. Garantia do Vendedor: 7 dias Produto possui certificação de segurança compulsória, certificado pela INNAC, organismo acreditado pela CGCRE do Inmetro. Produto Novo, Original, Lacrado e Acompanhado de Nota Fiscal.', 139.99, 119.99, NULL, 'Mom & Baby > Toys > Block Toys', 'https://cf.shopee.com.br/file/br-11134207-81zu2-ml5e2gj4w2di93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F23799355478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
