INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53956362507', 'Cadeira Dobrável Alta JOYFOX Preta Reforçada Até 250kg em Aço Carbono 600D Oxford para Praia Camping Jardim e Varanda', '🪑 Cadeira Dobrável JOYFOX Disponível em 2 Tamanhos – Escolha o Ideal Para Você Conforto, resistência e praticidade para praia, camping, pesca ou varanda. 💪 Estrutura Reforçada em Aço Carbono ✔ Tubos estruturais espessos ✔ Base estável ✔ Alta durabilidade ✔ Suporta até 110kg (carga estática) Segurança e firmeza mesmo em uso frequente. 🧵 Tecido 600D Oxford Resistente Material grosso e durável Resistente ao desgaste Fácil de limpar Boa sustentação sem deformar facilmente 🌳 Apoios de Braço em Madeira Faia Madeira natural resistente Acabamento elegante Toque confortável Estrutura metálica + madeira = resistência com estilo. Ideal para uso outdoor. 📏 Escolha o Seu Tamanho 🔹 Tamanho Grande Altura do assento: 33cm Comprimento: 46cm Largura: 52cm Altura do encosto: 67cm Tubos base: 2x2cm Modelo mais alto e encosto mais amplo Mais confortável para uso prolongado 🔹 Tamanho Pequeno Altura do assento: 30cm Comprimento: 44cm Largura: 52cm Altura do encosto: 59cm Tubos base: 1.5x2cm Mais compacto e leve Ideal para transporte fácil 🎒 Dobrável e Fácil de Transportar ✔ Montagem simples ✔ Estrutura desmontável ✔ Acompanha bolsa de transporte ✔ Manual em português incluso Leve para qualquer lugar. 📦 Conteúdo da Embalagem ✔ Estrutura principal x1 ✔ Barras curvas x2 ✔ Barra reta x1 ✔ Bolsa de transporte x1 ✔ Manual em português x1 🌄 Ideal Para: Praia Camping Pesca Trilhas Jardim Varanda', 699.0, 169.0, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-81zuh-ml33ie78bev76b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063922972%2F53956362507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194104713', 'Fita de Manta Asfáltica 10cm x 10m Drykofita', 'DRYKOFITA ALUMÍNIO Fita asfáltica autoadesiva multiuso Fita autoadesiva multiuso à base de asfalto com poliméricos protegida com filme de alumínio que permite sua exposição a intempéries e aos raios solares para solucionar problemas de gotejamento e vedações. Onde aplicar • Telhados; • Rufos e chapas metálicas; • Dutos de ventilação e ar-condicionado; • Sheds e cúpulas, • Vedações de domos e claraboia; • Reparos rápidos em baús, toldos e similares; • Sistema de reflexão térmica; Vantagens • Alta adesividade em diversas superfícies; • Alta reflexão dos raios UV; • Fácil aplicação; • Produto atóxico; • Alta durabilidade; Apliação? Aplicação do primer Aplique uma demão de DRYKOPRIMER ACQUA ou DRYKOPRIMER ECO e aguarde a secagem por no mínimo 6 horas antes da colagem. Aplicação Remova o filme plástico expondo o asfalto adesivo, aplique este lado na superfície imprimada pressionando para melhor aderência e removendo possíveis bolhas de ar. A DRYKOFITA CINZA deve estar totalmente apoiada na superfície de aplicação. Em superfícies irregulares como telhados deve aplicar a DRYKOFITA CINZA acompanhando as ondulações, removendo o filme plástico conforme faz a aderência na superfície. Em áreas muito frias promover o pré-aquecimento da DRYKOFITA CINZA com ar quente ou através do calor do sol e o pré – aquecimento do substrato com maçarico.', 44.02, 28.62, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mats7xuiq8b304', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F22194104713', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259696877', 'Doriana Cremosa com Sal Margarina', 'A Margarina Doriana Cremosa com Sal é perfeita para suas receitas e lanches do dia a dia. Com sua textura cremosa e sabor equilibrado, é ideal para passar no pão, torradas e biscoitos. A Doriana é feita com óleos vegetais, leite desnatado reconstituído e um complexo de vitaminas B6 e B12, além de vitaminas A e D. Contém ômega 3, 6 e 9, e não contém glúten.', 5.99, 5.38, NULL, 'Food & Beverages > Dairy & Eggs > Butter & Margarine', 'https://cf.shopee.com.br/file/sg-11134201-8257s-mqnelgkaascu42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555087%2F58259696877', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
