INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8280999905', 'Mini Teclado Usb Led Touchpad Smart Tv Pc Ps3 frete grátis', 'Mini Teclado Touchpad Sem Fio O mini teclado toutchpad fornecerá praticidade para seu dia-a-dia, possui design ergonômico e compacto, sendo possível leva-lo para qualquer lugar, seja para seu trabalho ou para momentos de diversão e o melhor de tudo, ele é confortável, se adaptando perfeitamente em suas mãos. O teclado conta com 92 teclas, incluindo comandos multimídias e teclas de controle para jogos no computador. Você pode conecta-lo no computador, tv, notebook, celular ou até mesmo em seu vídeo game. Adquira já o seu!', 45.0, 22.25, NULL, 'Computers & Accessories > Keyboards & Mice > Keyboards', 'https://cf.shopee.com.br/file/sg-11134201-7renb-m83bsmrrhe0mb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F8280999905', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22195574463', 'Ração Úmida Sachê Golden Gourmet Gatos Adultos Atum 70g', 'GoldeN Gourmet Gatos Adultos Sabor Atum, Abóbora e Arroz Integral é um alimento Premium Especial que faz parte da linha GoldeN Gourmet. Este produto é um alimento úmido completo indicado para gatos adultos saudáveis, pois é enriquecido com vitaminas e minerais possibilitando um suporte às defesas naturais. Feito com ingredientes 100% naturais, possui um sabor excepcional e é naturalmente saudável, pois não contém corantes e aromatizantes, proporcionando uma refeição deliciosa. Além disso, GoldeN Gourmet Gatos Adultos Sabor Atum, Abóbora e Arroz Integral auxilia na manutenção do sistema urinário saudável, pois contribui para ingestão diária de água. Composição Água, carne de atum, carne de frango, carne mecanicamente separada de frango, fígado de frango, pescoço de frango sem pele, plasma sanguíneo desidratado de suíno, proteína isolada de soja, farelo de arroz desengordurado, óleo refinado de peixe, abóbora, arroz integral, ácido cítrico, carbonato de cálcio, cloreto de amônio, cloreto de potássio, cloreto de sódio, DL-metionina, fosfato bicálcico, goma guar, hexametafosfato de sódio, sulfato de amônio, taurina, acetato de DL-alfa tocoferol, acetato de retinol, ácido ascórbico monofosfato, ácido fólico, ácido pantotênico, biotina, bissulfito de menadiona nicotinamida, cianocobalamina, cloreto de colina, colecalciferol, niacina (ácido nicotínico), piridoxina, riboflavina, tiamina, cobre aminoácido quelato, iodeto de cálcio, selenometionina hidroxi análoga, zinco aminoácido quelato.amina, cloreto de colina, colecalciferol, niacina (ácido nicotínico), piridoxina, riboflavina, tiamina, cobre aminoácido quelato, iodeto de cálcio, selenometionina hidroxi análoga, zinco aminoácido quelato.', 6.25, 3.75, NULL, 