INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298564397', 'Scarpin Usaflex Salto Bloco Couro Tressê Monograma Marrom Caramelo - Feminino', 'Estilo refinado com tecnologia de cuidado intensivo para os seus pés! Scarpin Usaflex Salto Bloco Couro Tressê Monograma Marrom Caramelo - Feminino Ficha Técnica: Marca: Usaflex Cor: Marrom caramelo Cabedal: Couro com acabamento tressê e monograma da marca Gênero: Feminino Palmilha: Anatômica com tecnologia de cuidado intensivo, ideal para aliviar desconfortos como fascite plantar Sola: Borracha flexível com aderência Fechamento: Calce fácil Amortecimento: Alto, com reforço na região da sola dos pés Estabilidade: Elevada, com salto bloco médio revestido de 4,5 cm Bico: Quadrado Tecnologias: Couro adaptável ao formato dos pés, indicado para quem possui joanetes; palmilha que reduz impacto e alivia inflamações como fascite plantar; forro com tecnologia antibacteriana que combate odores e evita alergias Indicação: Uso diário, ambiente de trabalho e eventos sociais Detalhes: Design tressê com monograma Usaflex Sofisticado na aparência e surpreendente no conforto, o Scarpin Usaflex é a escolha perfeita para quem exige mais de um calçado. Porque investir: Com design elegante em couro tressê, ele traz palmilha com suporte anatômico e tecnologias que aliviam desconfortos como joanetes e fascite plantar. O salto bloco de 4,5 cm proporciona estabilidade e o forro antibacteriano garante segurança e higiene o dia todo. Conteúdo da embalagem: 1 par de Scarpin Usaflex Salto Bloco Couro Tressê Monograma Marrom Caramelo - Feminino Na Center Sport, sua loja de artigos esportivos, só trabalhamos com produtos 100% originais para garantir sua qualidade e performance. Compre agora e experimente o verdadeiro conforto!', 399.99, 249.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134