INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998827584', 'Mesa Cabeceira 1 Gaveta 60,7cm x 50cm Empório Marrom Walnut', 'Adicione charme e funcionalidade ao seu quarto com a Mesa de Cabeceira Retrô, um móvel prático e elegante que combina com diversos estilos de decoração. Com design vintage e pés inclinados, ela é ideal para quem busca um toque retrô sem abrir mão da modernidade. Fabricada em madeira de qualidade e com acabamento em tom castanho, essa mesa de cabeceira oferece resistência e durabilidade. Possui 1 gaveta com puxador metálico e 1 nicho aberto, perfeitos para organizar livros, acessórios ou itens de uso diário. Estilo: Moderno Peso (kg): 7.6 Garantia: 03 Meses Altura (cm): 60.7 Acabamento: Verniz Largura (cm): 50 Possui Pés: Sim Pet Friendly: Não Possui Vidro: Não Possui Nichos: 1 Possui Portas: Não Altura dos Pés: 31.11 Pés Reguláveis: Não Possui Gavetas: Sim Possui Rodízio: Não Suporta Até (kg): 20 Profundidade (cm): 35.5 Escala de Brilho: Semi-Brilho Gaveta com Chave: Não Material dos Pés: Madeira Maciça Origem do Produto: Nacional Acabamento dos Pés: Verniz Ambiente Principal: Quarto Material da Gaveta: Madeira Maciça Material Principal: Madeira Maciça Necessita Montagem: Sim Possui Prateleiras: Não Sapatas Niveladoras: Não Acabamento da Gaveta: Verniz Peso Máximo por Gaveta: 2 Quantidade de Espelhos: Não Tipo de Madeira Maciça: Pinus Complexidade da Montagem: Baixa: pode ser montado por uma pessoa sozinha Tipo de Puxador da Gaveta: Externo Escala de Brilho da Gaveta: Fosco Tipo de Corrediça da Gaveta: Madeira Material do Puxador da Gaveta: Metal Marca: Empório Paraíso Cor Interna: Walnut Cor: Walnut Cor do Produto: Walnut Itens Inclusos: 1 Mesa de Cabeceira e Kit Ferragens Cor Predominante: Marrom Linha ou Coleção: Empório Quantidade de Gavetas: 01 Gaveta', 497.21, 497.21, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8258n-mqrf35oqwlqlab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F23998827584', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55910087450', 'TREASURE - 4th Mini Album [NEW WAV]_RAW ver.', '◈ TREASURE DE 4o Álbum [NOVO WAV] ◈ 💿 TREASURE - 4o Mini Álbum [NOVO WAV]_RAW ver. 📅 Lançamento em 1 de junho de 2026', 172.0, 138.0, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134207-822yy-mof3iy1mfcpb9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F431836255%2F55910087450', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697034123', 'Filtro Ar Vw Santana 1998 a 2006 - 141454 - FAP4049', 'Filtro Ar Vw Santana 1998 a 2006 141454 FAP4049 (MI/Comfortiline) - Motor 1.8 8v EFI /(MI/Evidence/Exclusive/Comfortiline) - Motor 2.0 8v EFI - (Mecânico) Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 25.53, 25.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbks-lmsvppxmo6px83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23697034123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22396862355', 'Kit 3 Encordoamento Viola Caipira Giannini Cobra GESVP Cobre Prateado Pesada', 'Kit 3 EEncordoamento Viola Caipira Giannini Cobra GESVP Cobre Prateado Pesada A série Cobra apresenta toda a versalidade dos encordoamentos Giannini. O encordoamento para viola Giannini Cobra GESVP é feito com Cobre prateado e é indicado para músicos que gostam de cordas com uma pegada mais pesada. O encordoamento Giannini Cobra GESVP é ideal para afinação Rio Abaixo, Chitariana, Realego e Guitarra, tensão pesada. Especificações: Fabricação: Brasil Alma: Aço Revestimento: Cobre Prateado Acabamento: Bolinha Comprimento de escala: 584 mm / 23″Inch A: 0.011; 0.012; 0.009; 0.012; 0.015Inch B: 0.011; 0.012; 0.020; 0.025; 0.036 *Imagens Ilustrativas**Garantia: 3 Meses*', 136.72, 123.05, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rbnf-lljor5tjsotod8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F22396862355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798244077', 'Capa Correia ASTRA 1999/2012 - 68915 - 106125', 'Capa Correia ASTRA 1999/2012 1.8/2.0 8v - Manual - ExternaO próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 37.24, 37.24, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6c-m6uhjsuupvo2c9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22798244077', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492977492', 'Válvula Termostática Vw Voyage 2008 a 2022 - 840727 - AVTS01003T80', 'Válvula Termostática Vw Voyage 2008 a 2022 840727 AVTS01003T80 1.0/1.6 8v - 80º A válvula termostática é uma peça importantíssima do sistema de arrefecimento dos carros. Ela controla a temperatura do motor. Quando o motor está frio, ela fica fechada, fazendo com que o líquido de arrefecimento (água e aditivo) volte para o bloco do motor. A partir de uma determinada temperatura, cerca de 90 graus, ela se abre, permitindo a passagem do líquido para o radiador para que ele seja refrigerado e volte para o bloco. A manutenção preventiva a cada 30 mil km ou menos.', 36.29, 36.29, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6u-lugwlnpjzlx01f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22492977492', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799003934', 'Mangueira Radiador Gm Astra 1999 a 2011 - 150251 - 904716', 'Mangueira Radiador Gm Astra 1999 a 2011 150251 904716 Superior Radiador motor 1.8/2.0 16v S/AR CONDICIONADO O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 25.27, 25.27, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-825ab-mr21mogudxc65f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20799003934', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
