INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192528574', 'Capa Proteção Correia Dentada Gm Meriva 2003 a 2012 - 170353 - 6042/3783', 'Capa Proteção Correia Dentada Gm Meriva 2003 a 2012 170353 6042/3783 1.8 8V (EXTERNA - SUPERIOR) O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 23.45, 23.45, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbli-lmqi7h03txsp66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22192528574', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
