INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893143858', 'Gancho de Aço Com Olhal e Trava 2000kg 7/16'''' (5,0004) - Nord', 'O Gancho de Aço Com Olhal e Trava 2000kg 7/16'''' (5,0004) - Nord, é um componente amplamente utilizado em várias indústrias e setores, devido à sua versatilidade e capacidade de suportar cargas pesadas. Uma das principais características do gancho olhal é a sua resistência. Ele foi projetado para suportar cargas substanciais, garantindo a segurança durante o manuseio de materiais pesados. Além disso, sua estrutura robusta permite uma longa vida útil, mesmo em ambientes de trabalho exigentes. - Especificações Técnicas: • Medida (pol): 7/16''''. • Carga Máxima (KG): 2000. • Material: Aço Forjado. Referência: 5,0004 Marca: Nord', 48.62, 48.62, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-lxo4ivlsg6a227', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22893143858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
