INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19632416849', 'Kit Short Ciclismo Feminino Forro em Gel Bermuda Bike Ciclista com Bolsos Roupa Preta Pedal Mtb', 'BERMUDAFEMININA FORRO EM GEL Principais Características: • Forro em Gel densidade 100, Modelagem anatômica que reduz impactos e aumenta o conforto durante pedais curtos e médios. • Tecido Tecnológico: Composição de 90% Poliéster e 10% Elastano, garantindo ajuste perfeito ao corpo e alta respirabilidade. • Proteção UV: Segurança extra contra os raios solares. • Secagem Rápida: Mantém o corpo seco e confortável mesmo nos dias mais quentes. • Costuras Reforçadas: Maior durabilidade, ideal para treinos e competições intensas. • Dois bolsos laterais: Praticidade para carregar pequenos objetos como chaves, suplementos ou smartphone. • Origem: Nacional. • Garantia: Contra defeitos de fabricação. Benefícios do Forro em Gel: • Maior Conforto: Reduz dores e desconfortos na região da pelve. • Indicado para pedais curtos, médios e longos: Suporte adequado para diferentes tipos de ciclismo. • Facilita o movimento: Melhora o desempenho e evita atritos indesejados. Confira a tabela de medidas disponível nas imagens para uma escolha assertiva. Way Bike: • Especialistas em artigos para ciclismo. • Produtos de qualidade e pronta entrega. • Atendimento de segunda a quinta, das 8h às 18h e as sextas das 8h às 17h. WAY BIKE – O que faltava para o seu pedal está aqui!', 70.9, 69.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzj3c5iv2ddtcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F19632416849', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
