INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48709470614', 'Balões São Roque Bexigas Rosa Shock C/50 Unidades', 'Deixe sua decoração mais vibrante, moderna e cheia de personalidade com os Balões Rosa Shock. A escolha perfeita para quem quer um ambiente marcante, alegre e cheio de energia em qualquer ocasião. Ideais para festas de aniversário, eventos temáticos, decoração feminina, festas neon, baladas, chá revelação e composições com preto, branco ou outras cores intensas. O rosa shock cria um visual impactante e cheio de atitude que transforma qualquer cenário em destaque absoluto. 💗✨ Fabricados em látex de alta qualidade, esses balões oferecem excelente resistência, ótimo acabamento e um visual impecável. Perfeitos para montagem de arcos, painéis, mesas decoradas e cenários instagramáveis. • Quantidade: 50 unidades • Material: Látex de alta qualidade • Cor: Rosa Shock 💗 📏 Escolha o tamanho desejado na variação do anúncio Tamanhos disponíveis: • Nº 5 • Nº 7 • Nº 8 • Nº 9 ⚠️ Atenção: Escolha o tamanho ideal na variação do anúncio antes de finalizar a compra. Caso deseje mais de um tamanho, basta adicionar ao carrinho cada opção separadamente e depois finalizar o pedido tudo junto. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces, com lojas físicas no estado de São Paulo desde 2002.', 21.99, 21.99, NULL, 'Home & Living > Party Supplies > Balloons', 'https://cf.shopee.com.br/file/br-11134207-820li-mng4x8jjl9tw49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F48709470614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
