INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210285273', 'Kit 16 Pilhas Alcalinas Elgin 8 AA e 8 AAA 1,5V Uso Geral Longa Duração', 'Tenha energia sempre à disposição com o Kit de Pilhas Alcalinas Elgin, composto por 8 pilhas AA e 8 pilhas AAA, totalizando 16 unidades. Ideal para abastecer diversos aparelhos eletrônicos do dia a dia, oferece excelente desempenho, longa duração e a qualidade reconhecida da Elgin. Perfeitas para controles remotos, brinquedos, mouses, teclados sem fio, lanternas, relógios, câmeras e muitos outros dispositivos, as pilhas alcalinas Elgin fornecem energia estável e confiável. Além disso, possuem até 7 anos de retenção de carga, garantindo que estejam prontas para uso mesmo após longos períodos de armazenamento. Diferenciais: ✅ Kit com 16 pilhas (8 AA + 8 AAA) ✅ Tecnologia alcalina de longa duração ✅ Energia estável e confiável ✅ Até 7 anos de retenção de carga ✅ Ideal para aparelhos de uso diário ✅ Excelente custo-benefício Aplicações: ✔ Controles remotos ✔ Brinquedos ✔ Lanternas ✔ Mouses e teclados sem fio ✔ Relógios ✔ Câmeras ✔ Calculadoras ✔ Rádios ✔ Outros dispositivos compatíveis com pilhas AA e AAA Especificações Técnicas Marca: Elgin Tipo: Pilhas Alcalinas Voltagem: 1,5V Quantidade: 16 unidades Conteúdo: 8 pilhas AA + 8 pilhas AAA Capacidade: 800 mAh Composição: Zinco alcalino Formato: AA e AAA Retenção de carga: Até 7 anos Conteúdo da Embalagem - 8 Pilhas Alcalinas AA Elgin 1,5V - 8 Pilhas Alcalinas AAA Elgin 1,5V (Total: 16 unidades)', 41.0, 29.9, NULL, 'Home Appliances > Batteries', 'https://cf.shopee.com.br/file/br-11134207-820l6-mnyl3yewz6kife', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F58210285273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
