INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297153453', 'Agua Fresca de Rosas Adolfo Dominguez Edt - Feminino 120ml', 'Agua Fresca de Rosas é um perfume Adolfo Dominguez feminino floral fresco. É uma fragrância repleta de notas florais frescas e atemporais, perfeitas para serem usadas diariamente em qualquer época do ano. O aroma Agua Fresca de Rosas de Adolfo Dominguez une a simplicidade e o luxo com notas frescas de toranja, bergamota e tangerina fusionadas com um bouquet floral de lírio-do-vale, lilás e jasmim, adornam de maneira sutil a elegância da rosa da Bulgária. Ao fundo, sândalo, musgo de azinheira e âmbar combinam com a sedução aveludada do almíscar.', 379.0, 360.05, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rbm6-lohal9ioyicc4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F456811696%2F23297153453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
