INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51156739353', 'Tênis Infantil Menina Escolar Antiderrapante Macio Feminino Fechamento Fácil Original Camin Promoção', 'Tênis Infantil Camin Confortável com Velcro – Leve, Seguro e Ideal para o Dia a Dia O Tênis Infantil Camin foi desenvolvido para proporcionar conforto, segurança e praticidade para as crianças em todas as atividades do dia a dia. Com design moderno e materiais resistentes, é perfeito para brincar, passear ou ir à escola com muito mais estilo e proteção. Seu fechamento em velcro facilita o calce, permitindo que a criança coloque e retire o calçado com mais autonomia e rapidez. Além disso, o modelo possui solado antiderrapante, oferecendo maior estabilidade e segurança ao caminhar. O interior é macio e confortável, garantindo bem-estar mesmo após horas de uso. Um tênis pensado para acompanhar a energia das crianças com qualidade e durabilidade. ✨ Diferenciais do Produto ✔ Fechamento em velcro prático e seguro ✔ Solado antiderrapante para mais estabilidade ✔ Interior macio e confortável ✔ Design moderno fácil de combinar ✔ Ideal para uso diário, escola e passeios 📦 Informações Importantes 🚚 Envio em até 24h após a confirmação do pedido 🔒 Entrega segura com rastreamento 🏅 Produto com selo de qualidade 📏Tabela de medidas N° 20 -----> 13,3cm N° 21 -----> 13,9cm N° 22 -----> 14,6cm N° 23 -----> 15,3cm N° 24 -----> 15,9cm N° 25 -----> 16,6cm N° 26 -----> 17,3cm N° 27 -----> 17,9cm N° 28 ----->19,0cm N° 29 -----> 19,8cm N° 30 -----> 20,3cm N° 31 -----> 21,2cm N° 32 -----> 21,8cm N° 33 -----> 22,6cm N° 34 -----> 22,8cm N° 35 -----> 24,0cm N° 36 -----> 24,2cm', 119.9, 79.87, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820l8-mlf9erwccc1z6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F