INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3084524652', 'NIVEA Hidratante Desodorante Soft Milk 200ml', 'O que é? NIVEA Hidratante Desodorante Soft Milk é um hidratante formulado com Manteiga de Karité, desenvolvido especificamente para peles secas. Para que serve? Este hidratante serve como um aliado essencial para proporcionar hidratação duradoura à pele por até 48 horas, ajudando a prevenir o ressecamento. Além disso, sua fórmula desodoriza a pele, deixando-a com uma sensação suave e refrescante. A textura leve deste hidratante é especialmente projetada para evitar a oleosidade, tornando-o adequado para uso diário. Além disso, a fórmula é livre de corantes, álcool etílico e ingredientes de origem animal, garantindo uma experiência suave e livre de irritações. Ao incorporar o NIVEA Hidratante Desodorante Soft Milk em sua rotina de cuidados diários, você pode manter sua pele macia, revitalizada e protegida contra o ressecamento, garantindo uma aparência saudável e radiante. Benefícios e diferenciais: - Fórmula de rápida absorção - Possui ação desodorante - 48 horas de hidratação - 0% corantes, álcool etílico e ingredientes de origem animal - Contém manteiga de Karité', 20.9, 15.0, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mea3l4ikd7nl6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F3084524652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
