INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698569351', 'ENGATE NISSAN MARCH 2014 A 2020 FIXO 700KG NI1016 BRUCKE', '**ESTE ENGATE NÃO SERVE PARA TRANSBIKE, ELE É FEITO SOMENTE PARA CARRETINHAS!!** HOMOLOGADO PELO INMETRO Produto analisado, testado e aprovado em todas as etapas da avaliação garantindo total segurança para você e sua família. Engate para reboque fabricado em aço carbono de excelente qualidade e resistência. Engate de alta resistência no tracionamento de carretas, trailers, moto aquática, lanchas, etc. Não é necessário fazer furos na maioria dos veículos para a fixação do produto. Caso queira saber se o seu veículo precisa furar basta utilizar o campo de perguntas que iremos responder. Nosso engate é completo, acompanha kit com pino bola, tomada de engate e acabamento cromado. BRUCKE é o melhor custo benefício do mercado nacional quando falamos em engates. Especificações Técnicas: - Tração máxima de 700 kg - Sem solda na cabeça do engate - Fabricado em aço carbono - Pintura eletrostática (anticorrosiva) - Bola de engate cromada - Acabamento cromado (chapa) - Tomada de engate cromada - Regularizado de acordo com resolução n°197 do Contran - Homologado pelo INMETRO', 461.17, 424.28, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-7rato-malsovx91tn539', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F23698569351', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205217744', 'Camisa do Palmeiras Masculina 2026 Torcedor Lançamento Original Camiseta Puma Palmeiras Oficial', 'Sinta a vibração do Allianz Parque em cada detalhe da nova Camisa Palmeiras I 26/27 s/n Torcedor Puma Masculina. Desenvolvida para o torcedor que não abre mão de conforto e tradição, este modelo traz o verde icônico do Verdão em um design moderno e elegante. O tecido conta com a tecnologia dryCELL, que afasta o suor e mantém sua pele seca durante os jogos ou no dia a dia. Com o escudo bordado no peito, você exibe o orgulho alviverde com durabilidade e estilo impecável. É a peça essencial para empurrar o time rumo a mais vitórias com máxima performance. Garanta já a sua e vista o manto da Academia de Futebol!', 644.85, 644.85, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-81zu0-mknzkr5cnabk08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1716040168%2F58205217744', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257493724', 'SABONETE DOVE BARRA COM 6X90GR CUIDADO ANTIBAC ESPECIAL', 'Dove Antibacteriano Cuida & Protege é um sabonete corporal em barra desenvolvido especialmente para usar diariamente durante o banho. Sua fórmula combina cuidado com proteção antibacteriana, oferecendo uma limpeza suave, sem agredir a sua pele, além de possuir o pH neutro e 1/4 de creme hidratante em sua composição. Com a junção da tecnologia Antibacteriana e a exclusiva Nutrium Moisture, Dove Cuida & Protege elimina até 99.9% das bactérias, enquanto suaviza a secura da pele e proporciona uma pele protegida a cada lavagem. Para uso diário.', 26.81, 26.81, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-8262h-mm7iyjr800sgc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1765202114%2F58257493724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299409263', 'Tanquinho de Lavar Semiautomática 10 kg com Superesfregador MLT10C Mueller', 'Com o Tanquinho de Lavar Semiautomática Mueller 10 kg com Superesfregador - MLT10C, você tem as suas roupas lavadas com facilidade. O produto possui abertura superior e tampa transparente. Seu dispenser foi feito para sabão e amaciante e o eletro conta com esfregador para roupas. O produto é feito em polipropileno e o cesto é de plástico especial. Você pode lavar até edredom de Casal Soft na máquina sem se preocupar. O aparelho possui 4 programas de lavagem e NÃO centrifuga. O filtro para fiapos se localiza no gabinete e ajuda a remover os fiapos das suas roupas. Não perca essa oportunidade e garanta já o seu! Característica: Modelo: MLT10C Marca: Mueller Capacidade de lavagem: 10 kg Programas de lavagem: 4 Sistema de lavagem: Turbilhonamento Lava edredons: Sim, Casal Soft Centrifugação: Não rpm Abertura: Superior Tampa: Transparente Gabinete: Em plástico especial Filtro pega-fiapos: Sim Trava de segurança: Não Pés: Base dos pés desmontável Saída de água: Manual Mangueira de entrada de água: Sim Potência: 330 W Classificação Energética: A Consumo de energia: 0,13 kW/h Peso: 11,80 kg Motor: Motor com protetor térmico Grade protetora: Não Peneira: Sim Esfregador: Sim Desmontável: Sim Dispenser para sabão líquido: Sim Entrada de água: Manual Matéria-prima: Polipropileno Dispenser para amaciante: Sim Conteúdo da Embalagem: Tanquinho de Lavar Semiautomática 10 kg com Superesfregador MLT10C Mueller Dimensões: Largura: 54,00 cm Altura: 90,00 cm Profundidade: 66,00 cm Garantia: 1 ano.', 699.26, 699.26, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/sg-11134201-82629-mlw8gyxrm68821', 'https://shope.ee/an_redir?origin_link=https%