INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55454355831', 'Tênis Klin Original Capri Menino Juvenil Estiloso Conforto Premium', 'O Tênis que é a cara da moda Streetwear para o seu pequeno! 😎 Quer um tênis que aguente a rotina e ainda deixe o look incrível? O Klin Capri é a escolha certa! Com visual de couro e detalhes em cores tendência Branco e detalhes em cinza e preto, ele combina com tudo: do jeans à bermuda. ✅ Principais Benefícios: Muito fácil de limpar (passou um paninho, tá novo!). Super leve e confortável para a escola ou passeios. Estilo Juvenil que os meninos adoram. 🚚 Envio Rápido! Garanta já o Klin original para o seu filho. ✅Diferenciais de Qualidade e Conforto: - Aparência Premium: Confeccionado em material sintético de alta tecnologia que imita o couro, proporcionando elegância e resistência. - Conforto Anatômico: Como todo Klin, possui solado macio com o logotipo da marca em relevo, garantindo estabilidade e o desenvolvimento saudável dos pés. - Detalhes Exclusivos: Nome "Klin" em destaque na língua e na lateral do solado, reforçando a autenticidade e qualidade do produto. - Versatilidade de Ajuste: Fechamento em cadarço em elástico que permite um ajuste firme e personalizado para o dia a dia. - Cores Estratégicas: Base em Branco com sobreposições em tom Cinza e detalhe em Preto, facilitando a combinação com calças jeans, sarja ou bermudas. ✅Ficha Técnica: - Marca: Klin. - Linha: Capri. - Material: Sintético Premium (Visual Couro). - Solado: Borracha/TR Antiderrapante. - Estilo: Casual / Juvenil.', 254.9, 171.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82601-mj8h9ftqji0we9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404144117%2F55454355831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
