INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18597692125', 'Descascador Para legumes e Frutas Inox Tramontina Verano - 3 Funções', 'Descascador Tramontina Verano com Lâmina em Aço Inox e Cabo de Polipropileno Vermelho Desperte o chef que há em você com o Descascador Tramontina Verano. Equipado com uma lâmina de aço inox de fio liso, este descascador é perfeito para a preparação rápida e eficiente de uma variedade de alimentos, desde batatas até cenouras e gengibre. O cabo de polipropileno ergonômico oferece conforto e segurança, enquanto o furo passante permite pendurá-lo, facilitando o armazenamento e adicionando um toque de estilo à sua cozinha. Características: Lâmina de aço inox durável com fio liso para descascar com precisão. Cabo de polipropileno com furo para fácil armazenamento. Estrutura de ABS, robusta e fácil de limpar. Seguro para uso em máquina de lavar louças.', 56.0, 43.99, NULL, 'Home & Living > Kitchenware > Graters, Peelers & Cutters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvkb3a8dejexad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333246733%2F18597692125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
