INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792263809', 'Fralda Pampers Pants Ajuste Total Jumbo XXG 60 Unidades', 'Experimente a nova Pampers Pants ajuste total! Com cintura elástica 360 é fácil de pôr mesmo quando eles estão em movimento, para um ajuste perfeito e até 12 horas* sequinho. • O jeito fácil de trocar • Fácil de pôr • Cintura elástica 360° que se adapta ao corpinho do seu bebê e agora com sistema de Ajuste Inteligente • Fácil de tirar rasgue suas laterais e retire-a normalmente • Canais de ar que evitam que a fralda fique caída • Até 12 horas* de proteção para noites inteiras de sono sequinho • *Pode variar de acordo com os hábitos e características do bebê *Compre produtos Pampers', 171.09, 149.48, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-23030-ip26gnfi3lovbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1062557396%2F22792263809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
