INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594271620', 'Espumante Ponto Nero Celebration Brut 750ml', 'Segura do crescimento do setor de vinhos e espumantes no Brasil, o grupo Famiglia Valduga co-investe em novo projeto e abre uma nova empresa, a Domno Importadora. Tal projeto caracteriza-se por duas frentes de negócios: a importação de vinhos e a elaboração e exportação de espumantes. A sede da nova empresa fica as margens da BR 470 Km 224 - Garibaldi, terra dos espumantes, em uma área de mais de 60mil m2, cujas atividades comerciais iniciaram em agosto de 2008. Espumantes de elegante perlage e intenso aroma frutado. São leves e refrescantes, ideais para serem apreciados no happy hour com os amigos, no aquece para a balada, em um jantar mais romântico e até mesmo na harmonização de pratos. Escolha o que melhor combina com o seu momento! Visão: Coloração amarelo palha, translúcido, perlage fino e persistente. Olfato: Aroma elegante com notas de frutas como maçã e pêssego. Nuances cítricos aportam um estilo leve e delicado ao seu perfil aromático. Paladar: Excelente equilíbrio, destaca-se pela leveza e frescor em boca. Harmonização: Mix de folhas verdes, Pescados e Petiscos Teor Alcoólico: 11% vol. Temperatura de consumo: 04 - 06 °C Região: Vale dos Vinhedos Produtor: Famiglia Valduga - Domno Variedade: Chardonnay 30%, Pinot Noir 20%, Riesling Itálico 30% e Prosecco 20%', 75.04, 75.04, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7rdwv-mcth5rb26pd2e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1308521377%2F23594271620', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260478947', 'Kit com 3 Unidades da Bala de Gelatina Mogul 360 Cubo Surpresa Morango 26g', 'Kit com 3 Unidades da Bala de gelatina Mogul 360 Cubo Surpresa 26gBala de gelatina no sabor Morango. Abra o cubo de gelatina para ver qual bichinho, também de gelatina, vem dentro. BALAS DE GOMA SABOR ARTIFICIAL DE MORANGO. INGREDIENTES: XAROPE DE MALTOSE, AÇÚCAR, SUCO DE MORANGO CONCENTRADO, TREALOSE, GELIFICANTE GELATINA, UMECTANTE XAROPE DE SORBITOL, REGULADORES DE ACIDEZ: ÁCIDO CITRICO, CITRATO TRISSÓDIO E ÁCIDO MÁLICO (DL-), ESPESSANTES: ÁGAR, CARRAGENA, PECTINA E CARBOXIMETILCELULOSE SÓDICA, AROMATIZANTES, GLACEANTE CERA DE CARNAÚBA E CORANTE VERMELHO ALLURA AC (INS 129/ E129). NÃO CONTÉM GLÚTEN. INDUSTRIA CHINESA.', 14.99, 11.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-825bd-mqrqyne217uq91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1075279447%2F58260478947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
