INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22099174589', 'Kit Jujuba Laranja Creme de Pentear e Gelatina Dabelle Hair', 'O Kit Jujuba Laranja DaBelle Hair traz uma explosão de energia, brilho e hidratação para seus fios. Com o poder revitalizante da laranja e da jujuba, essa dupla proporciona nutrição leve, definição e maciez, deixando os cabelos soltos, radiantes e cheios de vida. Ideal para quem busca fios definidos, hidratados e com perfume cítrico e refrescante. Brilho, leveza e definição em uma finalização vibrante e cheia de energia. O que o Kit Contém 1 Creme de Pentear Jujuba Laranja 1kg 1 Gelatina Jujuba Laranja 500G Benefícios Hidratação e nutrição sem pesar Cachos definidos e com movimento natural Brilho intenso e toque sedoso Redução do frizz e alinhamento dos fios Perfume cítrico e refrescante de laranja Fios revitalizados e cheios de energia Finalização leve, duradoura e com balanço natural Modo de Uso Nos fios úmidos, aplique o Creme de Pentear mecha a mecha, desembarace com um pente de dentes largos e amasse de baixo para cima. Para definição extra, misture a Gelatina Jujuba Laranja à quantidade desejada de creme e aplique nos fios úmidos. Finalize como preferir — com difusor ou deixando secar naturalmente.', 69.9, 59.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-821ft-mgxz1j5jiu4s6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939411398%2F22099174589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
