INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898833675', 'Lanterna De Cabeça Tática Potente 3 Leds 2135° e 2 Modos Iluminção', 'Lanterna de Cabeça C & Cia Import: Clareza e Segurança em Suas Mãos A Lanterna de Cabeça é a sua parceira ideal para qualquer atividade noturna. Desenvolvida para ser robusta e prática, ela garante que você tenha a iluminação necessária, seja para acampar, pedalar, pescar ou fazer trilhas. Com 22 lúmens de potência, ela oferece uma luz intensa e ampla que alcança de 20 a 30 metros em áreas abertas. Você pode escolher entre dois modos de iluminação: um fixo, para iluminar o caminho, e um sinalizador, para garantir que você seja visto. O ajuste de 135° permite direcionar a luz exatamente para onde precisa. Leve e compacta, a lanterna pesa pouco e tem dimensões de 5,4 x 2,6 x 3,3 cm. Funciona com 2 baterias CR2032 (já inclusas), oferecendo praticidade imediata. Feita de ABS, um material durável, ela é construída para resistir às mais diversas condições de uso. Detalhes do Produto: Cor: Preto Medidas: 5,4 x 2,6 x 3,3 cm Alimentação: 2 Baterias CR2032 (inclusas) Material: ABS Cor da Luz: Branca Modos: 2 (Fixo e Sinalizador)', 39.9, 26.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdvu2ni06dxe5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415129379%2F22898833675', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
