INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23719186265', 'Chuteira Society Penalty Se7e Kids XXI', 'Ideal para seus treinos e jogos com os amigos, a Chuteira Society Penalty Se7e Kids XXI é o produto ideal para você marcar um golaço. O calçado apresenta leveza, conforto e durabilidade, permitindo proporcionar as melhores experiências dentro das quatro linhas. Seu solado possuicanaletas posicionadas estrategicamente para auxiliar na flexão e movimentação dos pés durante as arrancadas e mudanças de posição. Benefícios: Auxilia na prevenção de lesões. Solado antiderrapante. Mini cravos permitindo deslocamento rápido. Alguns diferenciais técnicos: Seu solado em borracha conta com tecnologia Rotate, pontosde giro que auxiliam na movimentação ajudando na prevenção de lesões durante as partidas. Além disso, Chuteira Society Penalty Se7e Kids XXI conta com a tecnologia Hiperflex, são canaletas posicionadas estrategicamente para auxiliar na flexão e movimentação dos pés durante as arrancadas e mudanças de direção.', 153.9, 153.9, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/sg-11134201-7qvea-lg455l0j0owe45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F23719186265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29838362756', 'LAVA ROUPAS LIQ BIOPOWER CONFORTO PLUSH 5L', 'Se você busca limpeza profunda, perfume duradouro e cuidado com os tecidos, o Lava Roupas Líquido Biopower Conforto Plush 5L é a escolha ideal. Com fórmula concentrada e dermatologicamente testada, ele remove manchas difíceis, preserva as fibras dos tecidos e mantém as cores vivas, garantindo roupas limpas, macias e perfumadas por muito mais tempo. Indicado para todos os tipos de roupas, brancas ou coloridas, é hipoalergênico e seguro para peles sensíveis. Sua textura líquida facilita a diluição, evita resíduos e proporciona uma lavagem uniforme e eficiente. Além disso, sua fragrância exclusiva de conforto transforma a rotina de lavanderia em uma experiência mais agradável. Destaques do Produto• Limpeza profunda com remoção de manchas difíceis• Fragrância suave e duradoura• Preserva as fibras e evita o desgaste dos tecidos• Hipoalergênico e dermatologicamente testado• Rende até 50 lavagens com 5 litros Modo de Uso• Agite antes de usar• Use 100ml para até 8kg de roupas ou 150ml para 9kg ou mais• Aplique diretamente na máquina ou dilua para lavagem manual• Enxágue bem após a lavagem Informações TécnicasMarca: Plush SanolProduto: Lava Roupas LíquidoLinha: Biopower ConfortoFragrância: SuaveVolume: 5 litrosAplicação: Lavagem manual e em máquina Garanta roupas limpas, perfumadas e bem cuidadas! Experimente o Lava Roupas Líquido Biopower Conforto Plush 5L e transforme sua rotina de cuidados com as roupas.', 55.7, 55.7, NULL, 'Pets > Litter & Toilet > Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-mbskfm17i0yt0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683952730%2F29838362756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51760312737', 'Tampa Copo Térmico Gocase compativel com copo Vibe de 470ml', 'Tampa para Copo Térmico Gocase 470ml desenvolvida para reposição e uso com o Copo Térmico Cerveja 470ml. Compatível com: Copo Térmico Gocase Cerveja 470ml. A Tampa para Copo Térmico é ideal para quem precisa substituir a tampa original ou ter uma peça extra para o dia a dia. Prática e funcional, ajuda a proteger a bebida durante o uso, oferecendo mais conforto em diferentes ocasiões, como churrascos, trabalho, passeios e momentos de lazer. • Compatibilidade: Desenvolvida para Copo Térmico Gocase Cerveja 470ml. • Peça de Reposição: Ideal para substituir a tampa original do copo térmico. • Uso Prático: Ajuda a proteger a bebida durante o consumo e o transporte. • Encaixe Funcional: Desenvolvida para oferecer encaixe adequado ao copo compatível. • Ideal para o Dia a Dia: Uma opção prática para manter seu copo térmico sempre completo e pronto para uso. Cuidados com o Produto: Lavar antes do primeiro uso. Lavar à mão com sabão neutro e esponja macia. Não utilizar produtos abrasivos. Evitar contato com acetona, álcool e líquidos à base de cloro. Não levar ao micro-ondas, lava-louças, geladeira ou congelador.', 49.99, 49.99, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-820la-mo41zwxqnkzpd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442913304%2F51760312737', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
