INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794532907', 'A METAMORFOSE DIE VERWANDLUNG - Franz Kafka', 'A METAMORFOSE DIE VERWANDLUNG O caixeiro viajante Gregor acorda metamorfoseado em um enorme inseto e percebe que tudo mudou e não só em sua vida, mas no mundo. Ele, então, acompanha as reações de sua família ao perceberem o estranho ser em que ele se tornou. E, enquanto luta para se manter vivo, reflete sobre o comportamento de seus pais, de sua irmã e sobre a sua nova vida. Informações Adicionais Autor: KAFKA, FRANZ Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: A METAMORFOSE Idioma: INDEFINIDO Páginas: 96 Edição: 2 ISBN-13: 9788594318787 ISBN-10: 8594318782', 22.83, 16.32, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-lplbepmnd7055c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23794532907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
