INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21960798784', 'Jogo 10 Lâmpadas Led Branca 6500K Modelo Pera E27 9W Branca Bivolt Normatizada Casa Comércio - AVANT', 'COMERCIAL VIPASA DISTRIBUIDORA. Jogo 10 Lâmpadas Led Branca 6500K Modelo Pera E27 9W Branca Bivolt Normatizada Casa Comércio LAMPADA LED PERA 9W A linha de lâmpadas Pera LED Avant é indicada para ambientes internos e por ser mais econômica e eficiente é a solução ideal para substituir as lâmpadas incandescentes ou fluorescentes. Ilumine seu ambiente residencial, comercial ou corporativo com as lâmpadas Pera LED Avant. Características/Vantagens: - Uso interno - Luz LED - Formato: Bulbo Pera - Corpo em policarbonato branco - Difusor em policarbonato leitoso - Base E27 - Não permite dimerização - Índice de proteção: IP20 - 1 ano de garantia - Bivolt E27 Inmetro Acabamento da Lâmpada: Branco Leitoso Formato: Bulbo Cor da Luz: Branco frio (6.500k) ou Branco Quente (3000k) Tempo de Acendimento: Imediato Tipo de Embalagem: Caixa Conteúdo da Embalagem: 1 Lâmpada Marca: Avant Conservação e Manutenção do Produto: Realize a limpeza com o produto desligado da rede elétrica, utilize: espanador de pó ou pano úmido com água. Nunca utilize soluções abrasivas. Aviso: Ao instalar o produto, certifique-se que a rede elétrica esteja desligada para sua segurança. Recomenda-se não utilizar esta lâmpada em minuterias. A instalação não está inclusa na venda ou preço do produto, e é de inteira responsabilidade do cliente. Dica: Antes de comprar o seu produto verifique as medidas, o local onde pretende instalar e se necessário o serviço de um profissional qualificado. Na utilização do produto em locais úmidos e não cobertos, utilize em luminárias com vedação para maior durabilidade da lâmpada. COMERCIAL VIPASA DISTRIBUIDORA.', 65.41, 49.99, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-22110-xpzb0l3icmjv80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F21960798784', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
