INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497619342', 'Whey Protein 100% HD 900g (Refil) - Isolado, Concentrado e Hidrolisdo - Caveira Preta Black Skull', 'COMPOSIÇÃO DO ANÚNCIO 1x WHEY 100% HD REFIL - 900G - BLACK SKULL / CAVEIRA PRETA DESCRIÇÃO DO PRODUTO "Whey 100% HD é mais um mega suplemento da linha caveira preta! Composto por três tipos de whey protein (concentrado, isolado e hidrolisado), ele é uma ótima opção para auxiliar no ganho de massa muscular! Além disso, sua composição conta também com a adição de BCAA, aminoácidos de cadeia ramificada que contribuem para uma melhor recuperação pós-treino. Benefícios: - 3W (isolado, concentrado e hidrolisado) - Auxilia no ganho de massa muscular; - 4,5G de BCAA''S por dose; - Sem glúten; - Alto valor biológico; - SRO - um processo de refinação que remove os contaminantes usando pressão da água para forçar as moléculas através de uma membrana semipermeável; Ingredientes: Proteína concentrada do soro do leite, proteína isolada do soro de leite, proteína hidrolisada do soro do leite, l-leucina, l-isoleucina, l-valina, aromatizante, espessante goma xantana, corante vermelho beterraba, acidulante ácido cítrico, edulcorantes sucralose e acessulfame de potássio. ALÉRGICOS: CONTÉM DERIVADOS DO LEITE. PODE CONTER AMENDOIM E DERIVADOS DE SOJA, OVO E TRIGO. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN. Sugestão de uso: Misture 3 colheres de sopa (aprox. 30g) de Whey 100% HD em 150 ml de água, ou de acordo com a consistência desejada, e consuma uma vez ao dia ou de acordo com a orientação de um profissional especializado. Recomendação para adultos acima de 19 anos de idade."', 109.9, 109.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqvt8aqn0dno0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1160496125%2F20497619342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52810131335', 'Pré Treino Shook Rafael Brandão 300g - Max Titanium', 'COMPOSIÇÃO DO ANÚNCIO 1x SHOOK PRE-WORKOUT RAFAEL BRANDAO - 300G - MAX TITANIUM DESCRIÇÃO DO PRODUTO "Lançamento Shook Pré-Workout Max Titanium Energia Explosiva e Foco para Treinos de Alta Performance! Prepare-se para treinos intensos e resultados surpreendentes com o Shook Pré-Workout, o mais novo lançamento da Max Titanium! Desenvolvido com uma fórmula avançada, este pré-treino oferece: Energia explosiva Resistência prolongada Foco preciso Performance superior Ingredientes Sabores irresistíveis para todos os gostos: Manga e Pêssego: Uma explosão tropical de sabor para refrescar seus treinos. Uva: Um sabor clássico e delicioso para te dar um gás extra. Fórmula poderosa: Com 2.000mg de Beta Alanina, 1.000mg de Arginina, 1.200mg de Taurina, 4mg de L-citrulinilarginina e 200mg de cafeína. Ideal para quem busca: Aumento de força e potência muscular Melhora do desempenho físico Redução da fadiga muscular Ganho de massa muscular Diluir 8g (1 dosador cheio*) em 300mL de água gelada. *A quantidade da porção no dosador pode variar em função da densidade e outras características do produto"', 119.9, 119.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-820lz-mnyp0c6acttu8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1160496125%2F52810131335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
