INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49107147919', 'Galão de Abastecimento Para Transferência de Combustível Gasolina 10L (2088W) - Lupus', 'O Galão de Abastecimento Manual Para Transferência de Combustível 10L (2088W) - Lupus, é fabricado em HDPE de alta resistência com parede de 2 mm, garantindo durabilidade e segurança mesmo em condições severas de uso. Projetado para aplicações off-road, é ideal para transferências rápidas e eficientes de combustível em veículos, motos, quadriciclos e equipamentos diversos. Certificado pelos padrões CE, ONU, ROHS, REACH e BSCI, o galão atende às normas internacionais de qualidade e segurança. É compatível com diversos fluidos, como água, gasolina, diesel e querosene, operando com eficiência em temperaturas que variam de -20°C a 80°C. Seu design compacto (471 x 345 x 104 mm) e peso reduzido de apenas 1,77 kg facilitam o transporte e manuseio. O sistema de acoplamento integrado permite fixação segura em automóveis, proporcionando estabilidade durante deslocamentos e praticidade em aventuras off-road. Características e Diferenciais: • Construção robusta em HDPE 2 mm, resistente a impactos. • Capacidade de 10 litros, ideal para transporte seguro de combustível. • Compatível com água, gasolina, diesel e querosene. • Certificações internacionais que garantem segurança e confiabilidade. • Suporta amplo intervalo térmico: -20°C a 80°C. • Sistema de acoplamento para fixação em veículos. • Compacto, leve e fácil de manusear. Descrição do Produto: • Material do Corpo: HDPE (polietileno de alta densidade). • Espessura da Parede: 2mm. • Capacidade: 10L. • Certificações: CE, ONU, ROHS, REACH e BSCI. • Fluído: Água, gasolina, diesel e querosene. • Temperatura: -20°C a 80°C. • Vantagens: Sistema para acoplar em automóveis. • Dimensões: (A) 471 mm x (L) 345 mm x (C) 104 mm. • Peso: 1,77kg. Referência: 2088W. Cód. de Fábrica: 2088W. Marca: Lupus.', 449.9, 410.7, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-82632-mlqt91gp2epw8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F49107147919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798707885', 'Gancho Parede Adesivo 3M Cabide Banheiro Cozinha Porta Toalha Multifuncional Preto Fosco', 'SOBRE O PRODUTO Acessório para banheiro com fixação através de adesivo. Acabamento liso e fosco. A pintura a pó aplicada na peça garante uma excelente cobertura protetiva contra corrosão e alta resistência ao impacto. Itens inclusos: 1 Gancho com Adesivo RECOMENDAÇÕES Superfícies recomendadas: Cerâmica, porcelanato, mármore, granito, metal liso, vidro, concreto liso, madeira. Não recomendado (pode ser utilizado com parafuso): Paredes pintadas ou com papel de parede (pode danificar a superfície caso necessária a remoção do adesivo). Superfícies irregulares, ásperas, brutas ou com textura grossa. MEDIDAS - Profundidade: 4,5cm - Lagura: 6,5cm - Altura: 10,5cm - Peso: 0,045kg ESPECIFICAÇÕES - Máteria Prima: Aço Carbono / Plástico - Cor/Acabamento: Preto Fosco - Capacidade: 0,9kg', 49.9, 34.99, NULL, 'Home & Living > Home Organizers > Hooks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcupsda1cvn64d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455103761%2F21798707885', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
