INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256600769', 'Payot Retinol Vegetal - Sérum Multirenovador Facial 30ml', 'Sérum multirenovador facial. Payot Retinol Vegetal proporciona luminosidade, maciez e firmeza instantânea para a pele. O Sérum Multirenovador Facial Payot Retinol Vegetal é a solução idealpara atenuar linhas finas de expressão, possuifórmula multirrenovadora, que confere uma experiência única de revitalização para sua pele. O Payot Retinol Vegetal possui uma sinergia perfeita entre seus ativos, proporcionando uma pele mais jovem, hidratada e com um efeito lifting imediato. Sua formulação forma um filme elástico, resistente e contínuo sobre a pele, capaz de minimizar o número e a profundidade das rugas, revelando um rosto mais suave e radiante. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 87.9, 87.9, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mlmhjh82uo7480', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58256600769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
