INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694304005', 'Óculos de Sol Unissex Chilli Beans Aviador Polarizado Marrom', 'Coleção: Linha Clássicos Óculos de Sol Unissex Chilli Beans Aviador Polarizado Marrom oferecem conforto, proteção e muito estilo. Óculos de Sol Unissex Chilli Beans Clássicos Aviador Polarizado Marrom, feito em material leve e resistente. Lentes com proteção 100% contra raios UVA e UVB, protegendo seus olhos nocivos do sol reduzindo o risco de desenvolvimento das doenças oculares. Além dessa proteção as lentes são polarizadas, que impede que a luz do sol que é refletida em superfícies planas afete a sua visão. A Linha Clássicos Chilli Beans, é um best-seller desenvolvida para agradar todos os gostos. Os Clássicos são ideais para quem preza por praticidade e peças únicas, com design clássico e atemporal, porém com aquele toque apimentado para você está sempre na moda. Na paleta de cores da Linha Clássicos, incluímos tons neutros, versáteis e cores da estação, tudo para dar um match com as peças do seu guarda-roupa. Ref.: OC.MT.4004.0202', 399.98, 399.98, NULL, 'Fashion Accessories > Eyewear > Sunglasses', 'https://cf.shopee.com.br/file/sg-11134201-8260c-mjtzn4p98xdv17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356106526%2F22694304005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293204690', 'Colchão de Espuma D45 Pillow Top Ortopédico Strong Solteiro 88cm', 'Busca um colchão que equilibre conforto e suporte? Nosso modelo com espuma D45 e acabamento em tecido Jacquard é a escolha perfeita. Com suporte para até 150 kg por pessoa, oferece uma superfície de descanso ideal para diversas preferências. O pillow top adiciona uma camada extra de maciez, transformando cada noite em uma experiência de sono restauradora. A combinação de materiais de alta qualidade e a construção cuidadosa garantem durabilidade e conforto contínuo. O colchão conta com a tecnologia do EPS é leve, resistente, oferece excelente estabilidade estrutural e altamente durável, proporcionando uma melhor sustentação para a camada superior em espuma, potencializando o conforto ortopédico e oferecendo noites de descanso mais tranquilas e saudáveis. Especificações Técnicas do Colchão: - Matéria prima: Espuma D45/Tecido; - Acabamento: Tecido Jacquard e Poliéster; - Pillow Top: Possui (Camada extra de conforto); - Sistema One Face: Tecnologia No Turn(permite girar o colchão); - EPS Poliestireno Expansí­vel: Possui; - Tipo de conforto: Médio (Ortopédico); - Peso máximo recomendado: até 150kg (por pessoa); - Garantia: 12 meses; - Dimensões do produto (larg. x comp. x alt.) 88x188x24cm Importante, as cores podem variar conforme a tela; Não oferecemos montagem; recomendamos profissionais qualificados. Confira as dimensões para transporte em elevadores e passagens. Não transportamos por meios especiais. Por se tratar de um produto de uso íntimo e pessoal, só aceitaremos devoluções por arrependimento apenas se a embalagem do produto não for violada.', 847.9, 786.7, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rdvr-lz0p3fq7367g72', 'https:/