INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994549103', 'Tênis Masculino Buster Ravett R0400', ',O Tênis Masculino Buster Ravett R0400 é a escolha perfeita para quem busca conforto e estilo em um só produto. Com design moderno e materiais de alta qualidade, ele é perfeito para completar seu look com um toque de personalidade e atitude. Ideal para o dia a dia ou para praticar atividades físicas, o Buster Ravett R0400 possui solado de borracha que proporciona maior aderência e durabilidade, garantindo segurança e conforto a cada passo. Seja para combinar com um visual casual ou esportivo, este tênis é a opção certa para os homens que não abrem mão de qualidade e versatilidade em seus calçados.. MODELO: 1780400 REFERENCIA: R0400 MARCA: Box 200 MATERIAL DA PALMILHA: EVA MATERIAL DA SOLA: Borracha MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado GÊNERO: Male GRUPO DE IDADE: Adult MATERIAL DO SAPATO: Sintético/Tela ESTILO DO TÊNIS: Urbano', 143.99, 143.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-825am-mg3pas3yn571e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F22994549103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
