INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194416682', 'Kit 3 und Gargabem pastilha 3mg c 08 sabor Mel e limão', 'OGargabem Pastilha 3mg Mel Limão – 8 unidadesé indicado para auxiliar noalívio da dor, irritação e desconforto da garganta, proporcionando uma ação refrescante e calmante. Combinando o efeito suave domele o frescor dolimão, estas pastilhas são ideais para quem busca alívio rápido e prático para os sintomas de garganta irritada, mantendo o bem-estar no dia a dia. Benefícios do Gargabem Pastilha Mel Limão: Ajuda no alívio da dor e irritação na garganta; Proporciona frescor e sensação de alívio imediato; Sabor agradável de mel e limão; Embalagem prática com 8 pastilhas; Uso conveniente em qualquer momento. Modo de uso:Utilizar conforme recomendação da bula ou orientação médica. ⚠️Atenção:Este é um medicamento. Seu uso pode trazer riscos. Procure orientação médica ou farmacêutica. Leia a bula antes de consumir.', 33.89, 29.99, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-824i8-meiscsf95mvbe9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22194416682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
