INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994053272', 'Vitaminas Neo B12 60 Cpr', 'Vitaminas Neo B 12 60capsVit B12 Neo Química é um suplemento alimentar em comprimidos mastigáveis, desenvolvido para auxiliar no bom funcionamento do sistema nervoso, na formação das células do sangue e no metabolismo energético. Com sabor agradável e prática apresentação em comprimidos mastigáveis, é ideal para quem busca reforçar a ingestão diária de vitamina B12 de forma fácil e eficaz. A vitamina B12 é essencial para a produção de glóbulos vermelhos, manutenção da saúde neurológica e suporte à disposição e bem-estar geral. Benefícios: Contribui para o bom funcionamento do sistema nervoso Auxilia na formação dos glóbulos vermelhos Melhora os níveis de energia e disposição Comprimidos mastigáveis com sabor agradável Prático e fácil de consumir', 31.99, 31.99, NULL, 'Health > Food Supplement > Weight Management', 'https://cf.shopee.com.br/file/sg-11134201-7ratq-mabl1vw6lu1z4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22994053272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597272463', 'Luminária Spot Led Quadrado Direcionável 7W Embutir Gesso Teto Preto | Branco Frio 6500K (Luz Branca) | Branco Quente 3000K (Luz Amarela) Bivolt Spot Super LED Pronta Entrega', '🌟 Iluminação LED Personalizada para Todos os Ambientes! 🌟 Este spot downlight é uma solução de iluminação versátil, disponível em três opções de potência: 3W, 5W e 7W. Com uma faixa de tensão de AC85-265V, oferece uma iluminação eficiente, com lumens que variam de 210 a 480 LM e um ângulo de abertura de 120°. Seu fator de potência é superior a 0,6, garantindo eficiência energética. Você pode escolher entre duas opções de cor de luz: Branco Frio (6500K) para uma luz branca nítida ou Branco Quente (3000K) para uma luz amarela aconchegante. Com uma longa vida útil de 30.000 horas, classificação IP20 e peso de 120 gramas, este spot downlight é confiável e fácil de instalar. Ele vem com uma garantia de 1 ano e possui um acabamento em branco, que se integra perfeitamente a diversos ambientes. Ideal para iluminação residencial e comercial. Descubra as incríveis características deste produto: 💡 POTÊNCIA: 7W 🔌 TENSÃO: AC85-265V: Compatível com uma ampla faixa de tensão, tornando-o versátil para diversas aplicações. 💡 LUMENS: 480 LM 🌈 ÂNGULO DE ABERTURA: 120°: Proporciona uma distribuição de luz ampla e uniforme. 🔌 FATOR DE POTÊNCIA: >0,6: Eficiência energética para economia de energia. 🌞 COR: Branco Frio 6500K (Luz Branca) | Branco Quente 3000K (Luz Amarela): Escolha entre as opções de cores para criar a atmosfera desejada. 💡 VIDA ÚTIL: 30.000 Horas: Com uma vida útil prolongada, você desfrutará de iluminação confiável por muitos anos. 🔒 IP: IP20: Adequado para uso em ambientes internos. 🔒 GARANTIA: 1 Ano: Compre com confiança, sabendo que seu investimento está protegido. 🏋️ PESO: 120 Gramas: Leve e fácil de instalar. ⚪ COR DO MATERIAL: BRANCO: Design discreto que combina com qualquer ambiente. Transforme qualquer espaço com essa iluminação LED versátil e eficiente, criando a atmosfera perfeita para cada ocasião. 🌈💫🏡 📜 NOTA FISCAL & ENTREGA 🚛 Comprando o nosso Spot Downlight, garantimos que você receberá uma nota fiscal para garantir transparência e conformidade fiscal. Além disso, oferecemos entrega super rápida para que você desfrute rapidamente da iluminação de alta qualidade. Sua satisfação é nossa prioridade!', 35.9, 16.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqnjkfngbmsn74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F23597272463', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
