INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794631314', 'Serra Tico-Tico 450w com Lâmina 220v', 'A Serra Tico-Tico Elétrica Nagano 450 W (Modelo NST4501) é a parceira certa para quem precisa de versatilidade, precisão e segurança em cortes retos e curvos. Compacta e fácil de manusear, trabalha com madeira, MDF, compensado, plástico, alumínio e chapas finas de metal — ideal para marceneiros, montadores de móveis, artesãos e times de manutenção. Com motor de 450 W, velocidade variável (até 3.000 rpm) e base inclinável até 45°, adapta-se ao material e à espessura para entregar cortes limpos e bem acabados. O sistema de troca rápida de lâmina, sem ferramentas, acelera o setup e mantém a produtividade em alta. Por que escolher a NST4501? Versátil: atende diferentes materiais com velocidade variável. Precisa: base ajustável até 45° para cortes em ângulo. Rápida de ajustar: troca de lâmina sem ferramentas. Confortável e segura: empunhadura ergonômica, guarda de proteção e excelente controle. Principais aplicações Cortes retos e curvos em madeira, MDF e compensado Corte de chapas finas de metal e alumínio Recortes decorativos e encaixes para marcenaria e artesa', 100.8, 100.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259j-mgdtj41mx349df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F22794631314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
