INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794015661', 'Poliuretano Spray Multiuso Tytan 500ml 40279', 'Poliuretano Spray Multiuso Tytan 500ml 40279 A Espuma de Poliuretano Spray Multiuso Tytan 500ml 40279 é a solução ideal para selagens, preenchimentos e isolamentos em diversas aplicações, combinando eficiência e praticidade em um único formato. Com sua fórmula avançada, essa espuma oferece excelente aderência em superfícies variadas, como concreto, madeira, metal e PVC, proporcionando um acabamento durável e de alta qualidade. Sua aplicação em spray garante maior controle durante o uso, permitindo resultados precisos e uniformes, mesmo em áreas de difícil acesso ou em trabalhos que exigem maior detalhamento. Com alta resistência a variações climáticas, a Espuma de Poliuretano Tytan 40279 é perfeita para vedar janelas, portas e outras estruturas, garantindo isolamento térmico e acústico superior. Além disso, ela possui excelente expansão controlada, o que facilita o preenchimento de cavidades sem desperdício, tornando-a uma opção econômica e eficiente. Após a cura, a espuma apresenta uma estrutura densa e resistente, que pode ser cortada, lixada ou pintada para atender às necessidades específicas de cada aplicação, oferecendo versatilidade em diversos tipos de projetos. Ideal para reparos, instalações e construções em geral, a Espuma de Poliuretano Spray Multiuso Tytan 500ml 40279 se destaca pela praticidade e pelo desempenho confiável. Seu formato compacto e de fácil manuseio permite que o trabalho seja realizado de forma ágil e precisa, seja em ambientes internos ou externos. A qualidade de sua formulação assegura resultados duradouros, promovendo vedação segura e acabamentos profissionais em cada uso. Escolha a espuma que combina tecnologia e desempenho para suas necessidades.', 31.9, 31.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rata-ma1c3mq9luu43b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23794015661', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493709592', 'Palheta Limpador Toyota Corolla 2020 2021 2022 2023 2024 Bosch', 'Descrição JOGO DE PALHETA DIANTEIRA AEROFIT ORIGINAL BOSCH 01 - Palheta Bosch lado motorista 26" / 65 CM 01 - Palheta Bosch lado passageiro 14" / 35 CM APLICAÇÃO: - TOYOTA COROLLA 2020 - TOYOTA COROLLA 2021 - TOYOTA COROLLA 2022 - TOYOTA COROLLA 2023 - TOYOTA COROLLA 2024 ENCAIXE : GANCHO Garanta máxima eficiência e segurança em todas as condições de estrada com as palhetas Bosch Aerofit. Produto original Bosch com nota fiscal inclusa. Características: Encaixe Gancho para instalação fácil e segura. Maior durabilidade e eficiência comprovadas. Nova embalagem moderna. Tratamento de grafite para limpeza suave. Estrutura robusta para estabilidade em todas as situações. Recursos Destacados: Tecnologia de ponta e inovação para uso com conexões especiais. Borracha aprimorada com Power Protection Plus, garantindo uma limpeza suave e silenciosa. Lâmina de aço Evodium pré-tensionada, oferecendo uma adaptação perfeita ao para-brisa. Produto novo, com aplicação compatível com peças originais. Construção robusta projetada para um desempenho duradouro, independentemente das condições climáticas. Processo de instalação simples e rápido para sua conveniência. Substituição Recomendada: Observe sinais de problemas no para-brisa e nas palhetas. Dicas de manutenção incluídas para prolongar a vida útil das palhetas. Importante: Substitua as palhetas pelo menos uma vez por ano. Em caso de dúvidas sobre a compatibilidade do seu veículo, pergunte no campo de perguntas do anúncio. Garanta uma visão clara e eficiente em qualquer condição com as Palhetas Bosch Aerofit. Compre já!', 76.77, 75.24, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/s