INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197423360', 'Body Um Ombro Só Bicolor Moda Verão 2024', 'Esse é um produto da marca Livre do Brasil. Uma marca brasileira, humanizada e com entrega ultra rápida. Produto: Body e um umbro só em Lycra de excelente qualidade. Fizemos naquele tecido texturizado que está super em alta. Esse modelo tem um ombro só. Não tem bojo. Tem um fecho super confortável na parte de baixo. Acompanhando a tendência da moda, fizemos ele bicolor. O desenho dos recortes está super em alta. Temos as versões: Body preto e branco Body branco e preto Body nude e preto Tem um fecho na parte de baixo. Tamanho e medidas da peça sem esticar: O tamanho é único, correspondente ao M. O tecido tem ótima elasticidade . Serve bem bustos do 36 ao 44. Comprimento: Aproximadamente 60 cm sem esticar Largura: Aproximadamente 30 cm sem esticar Postagem e envio: A Livre do Brasil é uma empresa brasileira. Temos todos os produtos em estoque. Assim que você faz o seu pedido, ele é conferido e embalado rapidamente, no prazo estipulado pela plataforma. O transporte é feito pela transportadora da plataforma que coleta os pedidos diretamente na nossa operação. O seu pedido é encaminhado ao centro de distribuição e segue de forma rápida e segura até você. Porque comprar os produtos da Marca Livre do Brasil: - Marca Brasileira. - Fabricação própria. - Preço justo e ótima qualidade. - Empresa com ótima reputação e excelentes avaliações. - Atendimento humanizado com honestidade e res', 49.9, 49.89, NULL, 'Women Clothes > Tops > Bodysuits', 'https://cf.shopee.com.br/file/br-11134207-7r98s-lmm0ag8910l311', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F424871094%2F20197423360', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
