INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193684611', 'Jogo Super Soletrando', 'No Super Soletrando, uma carta é sorteada e o dado jogado para descobrir qual palavra você deve soletrar. O Jogador à sua esquerda lê a palavra em voz alta, e você entra em ação! se acertar a soletração, joga o dado novamente e avança no tabuleiro para ficar mais perto da vitória. Precisa de ajuda? Peças dicas, como uma explicação, um sinônimo ou até a primeira letra da palavra! Divirta-se, aprenda e seja o primeiro a cruzar a linha de chegada neste desafio para toda a família! A partir de 8 anos Participantes: 2 a 4 Tempo estimado de jogo : 20 minutos Com 648 palavras', 99.99, 99.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rbmn-m5j4nuicocf249', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F22193684611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22096836935', 'Tangerina verde boa mancha escura de vitamina C e toner de hiperpigmentação para névoa sensível, 100ml', '[CONTAS Escuras TARGET E HIPERPIGMENTAÇÃO DE POST-ACNE] Nossa névoa de mancha escura de vitamina C é embalada com uma poderosa mistura de extrato de tangerina verde fresca, derivados de vitamina C e ácido hialurônico. As tangerinas verdes são potentes em antioxidantes e possuem 10x mais vitamina C do que limões. A nossa fórmula melhora as manchas escuras e a hiperpigmentação pós-acne ao mesmo tempo em que é alimentada por esta fruta, a nossa fórmula melhora as manchas escuras e a hiperpigmentação pós-acne enquanto trata a formação de novos que ainda têm a superfície. [CUIDADOS Raques DE UMIDADE COM 8 TIPOS DE ÁCIDO HIALURÔNICO] Revitalize sua pele com um cuidado rico em umidade que combina vitaminas e oito tipos de ácido hialurônico para uma tez carnuda e radiante. [toner À BASE DE ÁGUA DE ABSORVAÇÃO RÁPIDA] Com uma fórmula de absorção rápida e à base de água, nosso toner fornece o primeiro passo em vitamina C e reabastecimento de hidratação para pele seca, sem qualquer viscosidade ou desconforto [TANGERINAS Orgânicas MINDFULLY HARVESTADAS] Nossas tangerinas verdes orgânicas são nutridas com soja fermentada (fertilizantes naturais) para produzir os ingredientes mais saudáveis para sua pele. São escolhidos à mão durante uma pequena janela em julho (4 semanas fora de todo o ano) quando os níveis de vitamina C são os mais altos. Névoa de água de frutas mais fresca Somente as tangerinas mais frescas são infundidas em nossa fórmula para criar a névoa de água de aumento da pele Toner DE ÁGUA DE FRUTAS DE AUMENTO [ESKIN-BOOSTING PARA PELE SENSÍVEL] Este é um toner de vitamina C seguro e suave que hidrata e nutrirá sua pele para revelar uma tez fresca e brilhante. Revitaliza visivelmente a pele, evitando irritação comumente associada à névoa de vitamina C agressiva.', 104.76, 104.76, NULL, 'Beauty > Skincare > Toner', 'https://cf.shopee.com.br/file/sg-11134207-7rbm5-llbkar0jxj3v01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F22096836935', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
