INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792951380', 'Ferro de passar Roupa A Seco Amvox 110V ou 220V 1250W Modelo AF 1907 Proteção Contra Torção Fio', '# Auto Equip # Seja bem-vindo(a)!!! --- Descrição: Ferro Passar a Seco - Amvox Apresentamos o nosso novo ferro de passar a seco Amvox, com uma potência de 1250W para um desempenho eficiente. Sua chapa de inox oferece durabilidade e deslizamento suave sobre os tecidos. Equipado com proteção contra torção de fio, garantindo maior segurança durante o uso. Além disso, o ajuste de temperatura com termostato permite adaptar-se a diferentes tipos de tecido, proporcionando resultados impecáveis. Experimente a praticidade e eficiência do nosso ferro a seco. Informações Técnicas - Fabricante: Amvox - Marca: Amvox - Modelo: AF 1907 - Potência: 1250W - Voltagem: 110V/220V - Peso: 540g - Formato: Padrão/Anatômico - Chapa: Inox (20,1 x 10,2cm) - Fio: Com Proteção Contra Torções - Temperatura: Ajuste de Temperatura com Termostato Conteúdo da Embalagem: - 01 Ferro a Seco - 01 Manual Importante - Garantia de 03 meses; - Pedidos aprovados até 12h00 de segunda a sexta será enviada no mesmo dia; - Enviamos em até 24h úteis; - Utilize o campo de "Perguntas e respostas" e esclareça suas dúvidas com nosso suporte técnico.', 89.9, 69.9, NULL, 'Home Appliances > Small Household Appliances > Irons & Steamers', 'https://cf.shopee.com.br/file/sg-11134201-7rd3k-lty4l09epju579', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F600306931%2F23792951380', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
