INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094749860', 'Condicionador Hidratante De Couro Best Touch 500ml Alcance', 'Descrição do Produto: O Best Touch é um hidratante de couro que mantém o estado natural da superfície sem excesso de brilho e obstrução dos poros por muito mais tempo. Além da hidratação e proteção contra raios UV, cria uma incrível mistura de maciez com aderência controlada, proporcionando ao motorista e passageiros maior conforto e segurança em freadas bruscas e curvas acentuadas. Características: – Hidratante de Couro de alta performance; – Traz maciez e proteção contra Raios UV; – Proporciona conforto e toque macio ao couro; – Retorna o couro ao estado mais conservado. Modo de Usar: – Após a limpeza correta da superfície em couro ou similares, pressione uma pequena quantidade do produto sobre um aplicador de espuma macio, espalhe de maneira uniforme, deixe agir por alguns instantes até secar, se houver excesso retire com uma toalha de microfibra limpa e seca. A hidratação e proteção contra raios UV perduram por até 6 meses. A aderência controlada poderá ser restabelecida a cada 3 meses dependendo da condição da superfície. – Em caso de pouca sujidade sobre o couro, Best Touch poderá ser utilizado também como limpador. Composição: – Emoliente, butox 2-propanol, umectante, hidratante, espessante, essência e veículo.', 42.9, 42.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi2ykepaw2rl6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1687591180%2F22094749860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
