INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22595071465', 'Aperitivo Aperol 750ml', 'Aperitivo Aperol. Aperol Spritz é o autêntico drink italiano. Criado em 1919 e com uma receita inalterada até hoje, o Aperol tem baixo teor alcoólico (11%). Aperol Spritz é a bebida ideal para todas as ocasiões sociais, para os momentos de convívio com amigos e colegas. Seu sabor marcante de laranja levemente adocicado, fazem com que Aperol seja o acompanhamento perfeito para um dia de sol, um happy hour ou até mesmo em uma reunião informal em casa ou onde preferir. O Aperol é um aperitivo italiano de cor laranja brilhante, possui um sabor único graças a sua receita secreta a base de infusões com ingredientes especialmente selecionados, incluindo laranjas doces e amargas, além de várias outras ervas aromáticas e raízes. Sua principal receita surgiu no verão italiano, misturou-se Aperol com o espumante Prosecco e assim foi criado o famoso Aperol Spritz! Graduação Alcoólica 11%. Contém 750ml. Aperitivo Fabricado no Brasil. Ingredientes: Cubos de gelo 150ml de prosecco 100ml de aperitivo aperol 50ml de água mineral com gás 1 rodela de laranja-baía Em uma taça grande de vinho, coloque primeiro o prosecco. Em seguida, acrescente o aperitivo aperol e depois a água com gás. Adicione as rodelas de laranja a gosto e misture bem. Acrescente gelo a gosto. É importante seguir a proporção: Três partes de prosecco, duas partes de aperol e uma parte de água com gás.', 74.36, 55.49, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-8258z-mqe82riwe9ky17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1788136363%2F22595071465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
