INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20349729773', 'SOS Serum Leave-in Hair Remedy 150ml - Cadiveu', 'SOS Serum Leave-in Hair Remedy 150ml – Cadiveu Leave-in para todos os tipos de cabelos. Cadiveu Professional Hair Remedy SOS Serum 15 em 1 finaliza com perfeição os fios conferindo 15 benefícios extra. Multifuncional, Cadiveu Professional Hair Remedy SOS Serum 15 em 1 confere diversos cuidados ao cabelo: reparação, nutrição, força, bloqueia a umidade, ação anti-frizz, proteção térmica, sela as cutículas, desembaraça, proteção solar, brilho intenso, maciez, leveza, facilita a escovação, previne o aparecimento de pontas duplas e promove o rejuvenescimento dos fios. Como usar: Aplique no comprimento e pontas dos fios molhados e finalize da maneira que desejar.', 96.86, 96.86, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lksfe2w7rcs3b8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F20349729773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
