INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209361368', 'Sofá Com USB Retrátil e Reclinável Eureka 2,00m', 'Descrição A NETSOFAS apresenta o Sofá Eureka, uma proposta inovadora que une funcionalidade, tecnologia e o máximo conforto. Com um design pensado para elevar a experiência de descanso, este modelo traz soluções práticas para o seu lar, como quatro porta-copos integrados aos braços e carregador USB duplo. Revestido em tecido Velosuede de toque macio, o Sofá Eureka é a peça que faltava para transformar sua sala em um verdadeiro centro de entretenimento e relaxamento, permitindo que você aproveite seus momentos de lazer sem precisar se levantar para carregar o celular ou apoiar sua bebida. Medidas Altura aproximada: 95 cm (fechado) e 80 cm (aberto) Largura aproximada: 200 cm Profundidade aproximada: 90 cm (fechado) e 146 cm (aberto) Peso aproximado: 66,00 kg Informações Técnicas • Marca: Netsofás • Estrutura: Madeira Maciça de Eucalipto 100% de reflorestamento (Ecológica) • Revestimento: Tecido Velosuede • Assento: Fibra de Poliéster Siliconada com Flocos de Espuma D-28 e D-33 e Percinta Elástica • Encosto: Percinta Elástica, Flocos de Espuma e Fibra de Poliéster Siliconada • Conectividade: Tomada com duas entradas USB 5V (extensão do cabo de 70cm a 90cm) • Acessórios: 4 Porta-copos fixos nos braços (aprox. 10cm x 5cm) • Capacidade: Aproximadamente 100 kg por lugar • Fixação: Grampos galvanizados antiferrugem • Montagem: Sistema de fácil montagem, não necessita de montador especializado Conteúdo da Embalagem • 01 Sofá Eureka com Porta-Copos e USB • Kit de Ferragens • Manual de Montagem', 2059.99, 1389.99, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-820o3-mndbjrllryf698', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1423420147%2F5820936136