INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397293376', 'Amplificador Go Bass Gobass Gb100 Gb 100 20w Baixo 110/220v', 'Somos a Eletromusic Loja Especializada a mais de 10 anos no Mercado. Qual e o nosso diferencial? Buscamos sempre oferecer qualidade com excelencia por isso todos os nossos produtos sao de Fornecedores Nacionais com rigoroso controle de qualidade, possuem nota fiscal eletronica e garantia de fabrica. Voce e bem vindo para fazer parte da nossa historia Go Bass, marca nacional de amplificadores dedicada exclusivamente ao contrabaixista Os amplificadores Go Bass sao pensados, desenvolvidos e fabricados com o que ha de melhor em tecnologia, buscando nao apenas o refinamento tecnico, mas acima de tudo, entregar o melhor timbre e qualidade sonora ao musico. Com uma linha de produtos que vai do iniciante ao musico de grandes palcos, a GoBass traz para o mercado brasileiro uma gama de timbres que vai levar o seu contrabaixo a outro nivel sonoro. Especificacoes GB100: - 20W RMS - Alto-falante de 6" - Chave para selecao de instrumento ativo/passivo - Saida para fone de ouvido e entrada auxiliar (P2) - Controles de ganho, grave, agudo e volume master - Revestimento na cor preta - 110/220V Marca: Go Bass Amplificadores', 889.12, 889.12, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkr1ot8vc1vb9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F20397293376', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
