INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594636270', 'Par brucutus dianteiros VW Gol Voyage G5 G6 G7 G8', '2x 5Z0955985 Par brucutus dianteiros VW Gol Voyage G5 G6 G7 G8. Concessionária Belcar Veículos ATENÇÃO: Antes de efetuar a compra, confirmar compatibilidade da peça mediante chassi do veículo. INFORMAÇÕES IMPORTANTES: *Trabalhamos apenas com produtos originais Volkswagen *Nosso maior objetivo é atendê-los com qualidade, respeito e satisfação. *Agradecemos a você, clientes online pelas visitas, perguntas, críticas e Sugestões, muito obrigado pela confiança. OBSERVAÇÃO!!! Todos nossos anúncios estão sujeitos a atualizações de valores pela Fábrica!!! Após a aprovação da compra a postagem do produto será realizada em até: 24 HORAS ÚTEIS. Antes de comprar forneça o número do chassi, Perguntem e tirem dúvidas. HORÁRIO DE ATENDIMENTO: SEG A SEX DAS 8:00 AS 18:00 Sábado 08:00 as 12:00', 30.04, 29.14, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-mbuisdsl1gth5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1610275770%2F23594636270', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
