INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998411161', 'Reboot 500ML Dub Boyz - Revitalizador Condicionador Plasticos', 'PRODUTO COM NOTA FISCAL E PRONTA ENTREGA !!! DESCRIÇÃO GERAL: Lançamento Dub Boyz !!! Apresentamos o Revitalizador de Plásticos Dubboyz 500ml, a solução definitiva para revitalizar e proteger plásticos internos e externos do seu veículo. Ideal para painéis, consoles, para-choques e outros componentes, este produto inovador utiliza uma avançada formulação com blend de silicones, fragrância exclusiva e SiO2. Essa combinação poderosa proporciona um brilho intenso, proteção duradoura e alto poder de cobertura, garantindo que as superfícies tratadas fiquem com aparência de novas. Além disso, o Revitalizador Dubboyz oferece hidrorrepelência, ajudando a manter seu veículo sempre impecável, mesmo em condições adversas. Escolha Dubboyz para um acabamento profissional e proteção superior.', 68.9, 68.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m90e44lcf51524', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F999160347%2F23998411161', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
