INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209718618', 'Pão Bisnaguinha Originais Panco', 'A bisnaguinha original da Panco é macia e saborosa, perfeita para o café da manhã ou lanche da tarde das crianças. Com a qualidade que você já conhece, é uma excelente opção para combinar com manteiga, geleias e frios. A bisnaguinha é feita com: * Farinha de trigo enriquecida com ferro e ácido fólico * Zero gorduras trans', 9.99, 8.99, NULL, 'Food & Beverages > Bakery > Breads', 'https://cf.shopee.com.br/file/sg-11134201-82590-mqnem6m4revi80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58209718618', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14242951143', 'Vinho Concha Y Toro Reservado Merlot 750ml', 'Fundada em 1883, Viña Concha y Toro se tornou o principal produtor de vinho na América Latina com uma posição de liderança entre as empresas de vinho mais importantes do mundo e uma presença em 140 países. A empresa possui cerca de 11.300 hectares de vinhedos no Chile, na Argentina e nos Estados Unidos. Seu portfólio de vinhos inclui os ícones Don Melchor e Almaviva e sua marca emblemática Casillero del Diablo, bem como os vinhos Trivento da Argentina e Fetzer da Califórnia. A Companhia possui 3.169 funcionários e sua sede está localizada em Santiago, no Chile. Os vinhos Reservado que é a linha de entrada da Concha Y Toro, são vinhos reconhecidos pela uniformidade e facilidade em harmonizações, sendo uma das linhas de vinhos mais vendidas no Brasil pela qualidade e sua facilidade de agradar todos os paladares. Um delicioso tinto chileno, elaborado no Vale Central, que traz toda a maciez da casta Merlot, combinada ao aroma de frutas vermelhas maduras com notas de pimenta e tostado. No paladar, taninos suaves e de boa persistência. Combina tanto com aquele momento “cinema em casa” como com aquele jantarzinho de confraternização com os amigos!', 39.9, 30.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/br-11134207-7qukw-li8wd8jqghbk27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F14242951143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
