INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23891309294', 'PAR CARENAGEM LATERAL FAROL BANANINHA TITAN 160 2022 PRATA', 'CARENAGEM LATERAL FAROL - SPORTIVE. CÓDIGO: 7140009. APLICAÇÃO: HONDA CG TITAN 160 ( 2022 EM DIANTE ). !!!!!!!!!!!!!!! FOTOS MERAMENTE ILUSTRATIVAS !!!!!!!!!!!!!!! Produzido com os melhores equipamentos, garantindo segurança e durabilidade. Oferecendo sempre o melhor custo benefício, unindo qualidade e eficiência na sua utilidade. - Confeccionado com a melhor matéria prima; - Ótimo acabamento, proporcionando uma instalação sem adaptações. SOBRE NOSSA EMPRESA: Somos uma organização com anos de experiência no mercado. Seja você um apaixonado por velocidade, um aventureiro de estrada ou um entusiasta da personalização, cumprimos a missão de fornecer peças e acessórios da mais alta qualidade para elevar sua experiência de pilotagem a um novo patamar. UTILIZE O CAMPO DE PERGUNTAS PARA TIRAR SUAS DÚVIDAS, e apenas confirme a compra em caso de CERTEZA de compatibilidade do produto!', 69.99, 69.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7qvfk-lh7shbzoua56f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F346208010%2F23891309294', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257325276', 'L''Oréal Professionnel Serie Expert Serioxyl Advanced - Shampoo Densificante 300ml', 'Shampoo densificante para cabelos finos. L''Oréal Professionnel Serie Expert Serioxyl Advancedhigieniza de maneira suave e proporciona sensação de maior densidade. O Shampoo Desnificante L''Oréal Professionnel Serie Expert Serioxyl Advanced possui uma fórmula desenvolvida em parceria com cabeleireiros especialistas em couro cabeludo. Sua composição é rica em ativos ultra potentes, como o Sal de Magnésio, que ajuda a purificar raízes capilares do acúmulo que pode impactar o crescimento saudável do cabelo. Como usar: Aplique uniformemente no couro cabeludo molhado e no cabelo. Com a ponta dos dedos , esfregue suavemente até obter uma leve espuma. Enxágue bem. Em caso de contato com os olhos, enxágue-os imediatamente e minuciosamente. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 158.9, 158.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8262f-mm29u5vsqaklab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58257325276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257325256', 'L''Oréal Professionnel Serie Expert Scalp Advanced Dermo-purifier - Shampoo 300ml', 'Shampoo para couro cabeludo oleoso. L''Oréal Professionnel Serie Expert Scalp Advanced Dermo-purifier proporciona 78% menos oleosidadejá na primeira aplicação graças à sua formulação inovadora, criada em parceria com especialistas em couro cabeludo. O Shampoo L''Oréal Professionnel Serie Expert Scalp Advanced Dermo-purifier higieniza de forma eficiente, elimina o acúmulo de sebo e desequilíbrios que podem criar inúmeros desconfortos. Como usar: Aplique uniformemente no couro cabeludo molhado e no cabelo.Esfregue com a ponta dos dedos até obter uma espuma suave. Enxágue bem. Em caso de contato com os olhos, enxágue-os imediatamente e minuciosamente. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 162.9, 162.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8261e-mm29tnbcnhfl07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58257325256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294807727', 'Wella Professionals Oil Reflections - Shampoo 1L', 'Shampoo para todos os tipos de cabelo. Wella Professionals Oil Reflections Luminous Reveal limpa as impurezas da superfície do fio, ajuda a proteger as cutículas capilares contra radicais livres e protege de efeitos nocivos dos minerais. O Shampoo Wella Professionals Oil Reflections Luminous Reveal possui efeito levemente condicionante, deixa os fios com luminosidade e maciez incríveis. Com ele você dá adeus à opacidade e recupera a vivacidade do cabelo! Ah, ele vem com uma fragrância inconfundível. No topo Romã, Pêssego e Flor de Baunilha; no corpo Peônia, Coco e Jasmim; no fundo Almíscar, Baunilha e Cedro. Como usar: Aplique o shampoo de textura gel transparente no couro cabeludo e enluve os fios, sem esfregá-los. Enxágue em seguida e retire completamente o produto. Repita caso sinta necessidade. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 254.9, 254.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8262b-mjy6tjn0cef7f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23294807727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799870511', 'Sonda Lambda Audi/Volkswagen A3 Bora Golf 1.6 2.0 8v 1999 A 2009 0258010006', 'Sonda Lambda Audi/Volkswagen A3 Bora Golf 1.6 2.0 8v 1999 A 2009 0258010006 ESPECIFICAÇOES TÉCNICAS: TIPO PLANAR CONECTOR 4 PINOS COMPRIMENTO 119 CM COMPATÍVEL COM OS MODELOS: Audi A3 1.6 8V 1999 A 2006 Volkswagen Bora 2.0 8V 2001 A 2009 Volkswagen Golf 1.6 8V 1999 A 2003 NUMERO ORIGINAL/SIMILAR: 0258010006 / 030906262Ds GARANTIA: 3 MESES DUVIDAS FREQUENTES: VOCÊS SÃO CONFIÁVEIS? R: SIM, BASTA OLHAR NOSSA REPUTAÇÃO E MEDALHA . PRESTAMOS UM ÓTIMO ATENDIMENTO E DESPACHAMOS OS PRODUTOS NO PRAZO. AS FOTOS DO PRODUTO SÃO REAIS? R: SIM, FOTO REAL DA PEÇA. A QUALIDADE DO PRODUTO É BOA? R: SIM, TODOS OS NOSSOS PRODUTOS SÃO NOVOS E COM GARANTIA. QUAL O PRAZO DE ENTREGA? R: VOCÊ PODE VERIFICAR O PRAZO DE ENTREGA NA TELA INICIAL ABAIXO DO PREÇO DO PRODUTO. VARIA DE REGIÃO PARA REGIÃO. DEVOLUÇÃO E TROCAS COMO FAZER? R: A DEVOLUÇÃO É GRÁTIS; VOCÊ PODE TROCAR O PRODUTO SE NÃO FICAR SATISFEITO (PRAZO DE 30 DIAS APÓS RECEBER). EM CASO DE GARANTIA COMO FAZER? R: EM CASO DE GARANTIA, ENTRAR EM CONTATO VIA CHAT PARA FAZER A TROCA DA PEÇA. POSSO RASTREAR MEU PEDIDO? R: SIM, APÓS A COMPRA, LIBERA O CÓDIGO DE RASTREAMENTO PARA VOCÊ ACOMPANHAR O PEDIDO EM TEMPO REAL ATÉ A CHEGADA. APÓS A COMPRA, PODEREI MADAR MENSAGEM PARA O VENDEDOR? R: SIM, APÓS A COMPRA CONFIRMADA, O CHAT É LIBERADO. ACESSE O CHAT NO MENU "MINHAS COMPRAS". O PRODUTO É COMPATÍVEL COM MEU VEÍCULO? R: OBSERVE QUE NA DESCRIÇÃO DISPONIBILIZAMOS A COMPATIBILIDADE DA PEÇA. SE O SEU VEÍCULO NÃO ESTIVER LISTADO, NOS FAÇA UMA PERGUNTA AQUI ABAIXO ENVIANDO MODELO E ANO QUE CONFIRMAREMOS A APLICAÇÃO. 04 de setembro de 2025', 154.49, 154.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me956wi47ojl95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1355263989%2F19799870511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211389399', 'Kit os Favoritos Coala Orquídea Negra - 4 Itens', 'Orquídea Negra & Sofisticação Olfativa Deixe-se envolver pela opulência e mistério da Orquídea Negra com o Kit "Os Favoritos", uma coleção exclusiva para transformar seu corpo e seu ambiente. Este conjunto foi criado para quem busca uma experiência de luxo e uma fragrância marcante que inspira elegância e sensualidade. Por que escolher o Kit "Os Favoritos" Orquídea Negra & Sofisticação Olfativa? Experiência Sensorial Intensa: Uma imersão completa na fragrância da orquídea negra que envolve seus sentidos e o ambiente ao seu redor. Luxo e Elegância: Cada item foi pensado para elevar seus momentos de autocuidado e a atmosfera da sua casa a um patamar de pura sofisticação. Presente Impactante: Uma escolha memorável e elegante para presentear alguém especial, ideal para celebrar datas importantes e momentos únicos. Renda-se ao encanto da Orquídea Negra e transforme seus dias e seu lar com o Kit "Os Favoritos". Uma ode à beleza, ao mistério e à elegância.', 79.19, 64.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-820lj-mopeq5eby5mt8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177903362%2F58211389399', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599198280', 'Kit 3 Limpadores Zulu Perfumes Flor de Cacto 500ml', 'Mergulhe na energia vibrante do Limpador Perfumado Zulu Perfumes Flor de Cacto, uma escolha única para quem deseja transformar a limpeza em uma experiência sensorial. Sua fragrância vibrante e única combina frescor e personalidade, perfumando o ambiente com um toque moderno e envolvente. Além de renovar suas superfícies com eficiência, ele traz um cheirinho exclusivo que deixa sua casa ainda mais acolhedora e cheia de vida. - Fórmula com álcool que promove secagem rápida; - Perfumação por até 30 horas; - Perfume intenso dos óleos essenciais Coala Como usar: para limpeza diária, diluir 100mL do limpador em 3 litros de água. Umedeça um pano com a solução e passe sobre a superfície desejada. Para remover sujeiras mais difíceis e garantir perfumação prolongada, aplique o limpador diretamente na sujeira sem diluir, usando uma esponja macia ou pano úmido. Precauções: - Mantenha fora do alcance de crianças e animais; - Evite contato com os olhos e pele; - Em caso de ingestão, não induza o vômito e procure assistência médica imediatamente, levando a embalagem ou o rótulo do produto; - Mantenha o produto em sua embalagem, protegido da luz e calor; - Não reutilize a embalagem; - Lave os objetos usados como medida com água corrente. Com uma fragrância marcante e revigorante, o Limpador Perfumado Zulu Perfumes Flor de Cacto é a união perfeita entre limpeza e sofisticação. Sua essência única traz frescor e personalidade ao ambiente, transformando cada aplicação em um momento de renovação e bem-estar.', 29.9, 29.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi5xintt0d8i31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177903362%2F23599198280', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594271404', 'Talha Manual de Alavanca 1.5 Toneladas x 1.5m', 'Talha Manual de Alavanca 1.5 Ton x 1.5m – Eficiência e Segurança!ATalha Manual de Alavanca 1.5 Ton x 1.5m da Naganoé a solução ideal paraelevação e tensionamento de cargas com precisão e segurança. Com umdesign compacto e robusto, é perfeita para trabalhos emespaços reduzidos e ambientes desafiadores, garantindooperações em qualquer ângulo com total controle e eficiência. Principais Benefícios:Capacidade para 1.5 toneladas, ideal para trabalhos pesados. Elevação de 1.5 metros, proporcionando flexibilidade operacional. Operação leve e eficiente, reduzindo o esforço do operador. Construção em aço de alta qualidade, garantindo resistência e durabilidade. Portátil e compacto, facilitando transporte e uso em locais de difícil acesso. Baixa necessidade de manutenção, otimizando custos e tempo. Aplicação ideal para:Construção Civil e Naval Usinas e Portos Manutenção Industrial Telecomunicações e Transportes Garanta mais segurança e praticidade na movimentação de cargas! Adquira agora a sua Talha Manual de Alavanca Nagano e tenha a melhor performance nas suas operações!', 372.8, 372.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd4s-m7kzzbs8j5kz08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F23594271404', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797983445', 'Máquina de Suco de Laranja Tangerina Automática Elétrica - 220v', 'A Máquina de Suco de Laranja é composta por uma estrutura de aço inoxidável, uma tampa plástica de ABS transparente e peças plásticas ABS de qualidade com detalhes em cor laranja para uso em maquinários com aplicação alimentar. Possui coletor de bagaços no lado esquerdo e direito de aço inoxidável com capacidade de até 07 litros cada. Ao colocar a fruta no cesto e ligar a máquina irá automaticamente cortar, espremer, extrair o sumo e descartar o bagaço, com corte e produção de modo preciso e seguro. É um equipmamento ideal para o preparo de sucos naturais, frescos e deliciosos, pois a estrutura é bem organizada para otimizar espaço e tempo de produção com uma operação simplificada e prática. A Máquina Espremedora de Fazer Sucos é anticorrosiva e fácil de realizar limpeza e manutenção. Os espremedores são de duas esferas uma convexa e outra côncava de polímero atóxico e a faca é constituída de aço inoxidável. Projetada em materiais de alta tecnologia da indústria de alimentação para permitir a preparação de sucos em segurança, sem contaminações, sem corantes, sem conservantes e livre de outros resíduos. Possui sistema de proteção do motor contra híper-aquecimento e sistema de segurança contra acidentes. Máquina extremamente econômica! Oferece lucratividade, otimização de tempo e trabalho pois espreme 20 frutas por minuto ao qual extrai 02 litros de puro sumo da laranja. Em 01 hora são por volta de 1200 laranjas resultando em 120 litros de sumo, sendo assim, ao adicionar água, redobra ou até triplica a produção de suco totalmente natural e fresco de laranja, tangerina e entre outros cítricos. Amplamente destinada para uso em lojas, escritórios e centro comerciais, bares, pubs, padarias, mercearias, lanchonetes, quiosques, hotéis, hostels, shoppings, restaurantes, locais de recreação e entre outros. *Equipamento destinado exclusivamente para uso Profissional / Comercial. A segurança desse produto é certificada compulsoriamente junto ao INMETRO. Frequência: 60 Hz Potência: 200 W Diametro da fruta: 40 mm ~ 80 mm Operação: 20 frutas por minuto Rendimento: 50% ~ 65% Dimensões (C x L x A): 480 X 330 X 780 mm Peso: por volta de 45 Kg (sem frutas, líquidos ou cascas de frutas)', 6032.8, 6032.8, NULL, 'Home Appliances > Kitchen Appliances > Juicers, Blenders & Soya Bean Machines', 'https://cf.shopee.com.br/file/sg-11134201-7repc-m1wsylovd3ux91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F18797983445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23820180033', 'Ração Magnus Todo Dia Adulto Raça Pequena 15 kg', 'Ração Magnus Todo Dia Cão Adulto Raças Pequenas Carne e Frango 15 kg Alimento completo para cães adultos de pequeno porte - BIO COMPLEX é um exclusivo complexo de ingredientes que promovem benefícios para o seu cão. - Partículas adequadas: para cães de pequeno porte. - Equilíbrio da flora intestinal: Prebiótico, Fibras e Extrato de Yucca, a combinação destes ingredientes auxilia na formação das - fezes mais firmes e com menos odor. - Proteína de alta qualidade: altamente digestível - Hexametafosfato de sódio: auxilia na limpeza dental ___________________________________________________________________________ DESCRIÇÃO A Magnus é uma consagrada família de produtos para cães e gatos que inclui uma grande variedade de alimentos, tanto completos (secos e úmidos) quanto petiscos, como os biscoitos e bifinhos. Saborosos e nutritivos, os alimentos das linhas Magnus atendem diferentes necessidades e agradam até os paladares mais exigentes. Assim como todos os alimentos Adimax, as linhas Magnus passam, do começo ao fim, por um rigoroso controle de qualidade: da seleção dos fornecedores e ingredientes até a entrega dos produtos e suporte pós-venda. Tudo é pensado para atender com excelência nossos clientes e parceiros. ___________________________________________________________________________ COMPOSIÇÃO Milho moído, farinha de carne e ossos de bovino, farelo de trigo, farelo de soja, óleo de aves, cloreto de sódio, parede celular de levedura, hidrolisado de fígado de aves e miúdos de suínos, linhaça, ovo em pó, polpa de beterraba, extrato de yucca, vitaminas, minerais, hexametafosfato de sódio, ácido propiônico, BHA (Butilhidroxianisol) e BHT (Butilhidroxitolueno). Eventuais substitutivos: Farelo de arroz, farinha de vísceras de aves, hidrolisado de miúdos de aves, farinha de carne e ossos de suínos. ___________________________________________________________________________ NÍVEIS DE GARANTIA Umidade (máx.) 100 g/kg 10% Proteína Bruta (mín.) 210 g/kg 21% Extrato Etéreo (mín.) 80 g/kg 8% Matéria Fibrosa (máx.) 45 g/kg 4,50% Matéria Mineral (máx.) 110 g/kg 11% Cálcio (máx.) 24 g/kg 2,40% Cálcio (mín.) 10 g/kg 1% Fósforo (mín.) 7.000 mg/kg 0,70% Sódio (Mín.) 2.000 mg/kg Enriquecimento por Kg Vitamina A 10.000 UI Vitamina D3 960 UI Vitamina E 40 UI Vitamina K3 1,00 mg Vitamina B1 5,00 mg Vitamina B2 4,80 mg Vitamina B6 5,40 mg Vitamina B12 2,80 mcg Biotina 0,1 mg Ácido Fólico 1,00 mg Ácido Pantotênico 8,00 mg Niacina 60 mg Colina 500 mg Ferro 80 mg Cobre 7,00 mg Iodo 0,4 mg Manganês 7,50 mg Zinco 80 mg Zinco Quelatado 5,00 mg Selênio 0,30 mg Selênio Complexado 0,01 mg Proteinato de manganês 1,50 mg ___________________________________________________________________________ QUANTIDADE RECOMENDADA Porte do cão Peso do cão (kg) Quantidade/dia (g) Miniatura Até 5 Até 110 Pequeno 5 – 10 95 – 180 Médio 10 – 15 160 – 250 Médio 15 – 20 220 – 310 Médio Até 25 320 – 370', 185.99, 109.99, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134201-23010-vnqeblpvjsmvdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464043565%2F23820180033', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
