INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898071423', 'Coqueteleira Blender Bottle Sportmixer Twist 20oz/590ml', 'A Blender Bottle SportMixer é multiuso, seja para sua hidratação ou seu shake, graças a sua textura você pode carregá-la para qualquer lugar com a garantia de que não vai derrubá-la. Sem baterias, sem fios, sem esforço. É supereficiente para misturar os mais grossos ingredientes com facilidade. Use-a na cozinha, no escritório, na academia, quando for viajar, em qualquer lugar! Vem com o misturador exclusivo da Blender feito em aço cirúrgico, para misturar sua bebida com maior eficiência. Características : Gancho inteligente; Sem vazamentos; Resistente e livre de odor; Livre de BPA. Medidas Aprox.: Larg. Boca : 6,5 cm Altura : 18 cm Larg. Base : 7,5 cm Conteúdo da Embalagem: 01 un. Coqueteleira Blender Bottle SportMixer Twist 20Oz/590ml Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 172.88, 172.88, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rfh4-m3ulq66kuhy8ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F23898071423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41411912064', 'Tênis Democrata Denim Block Masculino Original', 'Estilo moderno e com personalidade em design elegante. O Tênis masculino Democrata Denim Block é seu aliado para levar atitude ao visual e ir além do básico. O cabedal de couro e tecido proporciona conforto e durabilidade, enquanto a sola de micro expandido favorece a maciez e a resistência. Um tênis versátil e com identidade própria, escolha certa para fazer a diferença nas suas combinações. Use com calça jeans, sarja ou alfaiataria ou bermuda chino. Para acompanhar, escolha camisa polo ou camiseta masculina. Aproveite!', 349.9, 309.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820lp-moa24z1455old3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F41411912064', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899568986', 'Eudora Golden Feminino Eau De Parfum 75ml', 'Eudora Golden Eau de Parfum 75ml Eudora EDP sabe que uma mulher segura não tem medo de ostentar o seu brilho. Por isso, traz Eudora Golden Eau de Parfum com toda a sofisticação da perfumaria feminina para mulheres luxuosas e marcantes. Inspirado na exuberância e riqueza do ouro, o segredinho está no acorde Golden Elixir: a combinação da faceta frutal brilhante e fresca da Lichia Dourada, uma espécie extremamente rara, com a Flor de Vanilla que leva até sete anos para florescer e produzir as favas de baunilha que dão o toque gourmand especial à fragrância. Um Chypre Gourmand denso e sofisticado para potencializar o brilho único de cada mulher. Em uma embalagem luxuosa em que o dourado entra em contraste com o branco: a assinatura sofisticada do Eudora Golden oferece uma fragrância feminina marcante, poderosa e elegante. Eudora Golden, desperte seu eu luxuoso! Família Olfativa: Chypre Gourmand Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free.', 165.99, 159.99, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rffi-m3govz9509gn2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F602117686%2F18899568986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43578167342', '6 Blocos de Vidro Inowar Azul 19x19 Ondulado — Estilo, privacidade e luz para sua obra!', '**COMPRAR APENAS 1 CAIXA DE 6 UNIDADES POR VEZ, POR CONTA DO PESO*** Transforme seus ambientes 6 Tijolos de Vidro Inowar Azul Transparente 19x19cm. Fabricados em vidro ondulado incolor na cor azul, esses blocos oferecem iluminação natural, estética moderna e privacidade sem perder a leveza visual. O efeito ondulado difunde a luz, criando um ambiente sofisticado e acolhedor, ideal para quem busca design contemporâneo em projetos arquitetônicos. Perfeitos para banheiros, cozinhas, salas, áreas externas, divisórias e detalhes decorativos, os blocos de vidro são resistentes, versáteis e fáceis de aplicar. Cada peça possui medidas 19 cm x 19 cm, com 8 cm de espessura, garantindo durabilidade, estabilidade e excelente acabamento. Especificações Técnicas: • Marca: Inowar • Modelo: Azul • Cor: Transparente Azul • Tipo: Bloco de Vidro Ondulado • Dimensões: 19x19x8 cm • 6 unidades A escolha ideal para quem deseja mais iluminação, mais estilo e mais valorização no ambiente. Perfeito para obras, reformas e projetos decorativos!', 699.9, 369.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjpvjdus53b674', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1384728500%2F43578167342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
