INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55950121215', 'Caixa Organizadora 8 L Dry Cristal', 'Caixa Organizadora Dry 8L Cristal – Máxima Capacidade com Estilo e Praticidade! Transforme sua organização com mais eficiência e um toque moderno! A Caixa Organizadora Dry 8L da Coza oferece amplo espaço interno, visual limpo e alta resistência, sendo ideal para armazenar itens maiores sem abrir mão do design. Seu acabamento canelado e estrutura transparente facilitam a visualização do conteúdo, otimizando a rotina em diversos ambientes. Destaques que fazem a diferença: Design transparente e funcional: Permite ver o que está dentro sem precisar abrir, trazendo mais agilidade no dia a dia. Alças ergonômicas laterais: Facilitam o manuseio e transporte, mesmo com a caixa cheia. Material resistente e leve: Feita em PET, combina a aparência elegante do vidro com a praticidade e durabilidade do plástico. Formato amplo e versátil: Ideal para armazenar mantimentos, produtos de limpeza, utensílios e muito mais. Uso em vários ambientes: Ótima opção para geladeiras, armários, prateleiras, despensas, lavanderias e banheiros. Características técnicas: Material: PET (Polietileno Tereftalato) – resistente e 100% reciclável Dimensões: 40 cm (comprimento) x 25 cm (largura) x 13 cm (altura) Capacidade: 8 litros Cor: Cristal (transparente) Indicações de uso: Ideal para geladeiras, armários, prateleiras e organização em geral Cuidados: Não vai ao micro-ondas nem à lava-louças. Lavar com água e sabão neutro, utilizando o lado macio da esponja. Eleve sua organização com praticidade e elegância! Adquira agora a Caixa Organizadora Dry 8L Cristal e transforme seus espaços com mais funcionalidade!', 60.21, 48.99, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-82595-mg80v70vbq4v26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F55950121215', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393186667', 'Frigideira Antiaderente Cerâmico com Indução Brinox Botanika 24cm 1,35 litros Verde', 'Seja Bem-Vindo(a) à Mimorada! *Serve em todos os tipos de fogões, desde o comum à gás até os elétricos e de indução. Apresentamos a Frigideira Brinox Fundo Indução Botanika 24cm 1,35L, uma combinação perfeita de tecnologia, responsabilidade ambiental e beleza para a sua cozinha. Com o revestimento Pro Ceramic Premium antiaderente Mineral Resist, essa frigideira garante um preparo saudável dos alimentos, cozinhando com menos óleo e facilitando a limpeza. Integrando o Projeto Green Planet Brinox, a Frigideira Brinox Fundo Indução Botanika 24cm 1,35L é sustentável, sendo que 98% do alumínio utilizado na estrutura é proveniente de materiais reciclados. Com a cor Verde, essa frigideira trás sofisticação para a sua cozinha, enquanto o cabo em baquelite soft-touch com efeito amadeirado proporcionam um toque especial. *Material: Revestimento Antiaderente Cerâmico livre de substâncias tóxicas. Alumínio que esquenta por completo e mais rápido, economizando gás e otimizando tempo.', 189.99, 129.99, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/sg-11134201-7rdx9-ly3nzbar8ojge7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F22393186667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
