INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47406116132', 'Livro Os maiores astros do futebol - Cristiano Ronaldo', 'Cristiano Ronaldo é um dos maiores jogadores de todos os tempos. Depois de provar seu talento sob o comando de sir Alex Ferguson no Manchester United, ele conquistou uma reputação sólida no Real Madrid. O talento e a habilidade inigualáveis de Cristiano conquistaram o mundo do futebol. Editora: Ciranda Cultural Edição: 1, 2026 Autor: Luke Paton Ilustrador: Sophie Jones Idioma: Português Páginas: 128 Dimensões: L 13.20 x A 20.00 x E 1.00 ISBN: 9786526129159 Coleção: Os maiores astros do futebol Linha Editorial: Ciranda Cultural - Infantojuvenis Faixa Etária: + 9 anos Assuntos (tags): Literatura juvenil, Literatura infantojuvenil, Ação, Esportes, Futebol, Copa do mundo, Jogador, Biografia, Não ficção, História de vida, Superação, Competição, Craques do futebol, Ídolos do futebol, História do futebol BISAC: Literatura Juvenil / Literatura Juvenil / Esportes e Recreação / Futebol Linha de Produto: Ciranda Jovem Encadernação: Brochura Acabamento: Laminação fosca e verniz localizado Material: Papel', 24.9, 17.43, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260g-mkl9567c3aire1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F47406116132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2971228895', 'A divina comédia - Box com 3 livros', 'A Divina Comédia é um poema clássico da literatura italiana e mundial com características épica e teológica, escrito por Dante Alighieri no século XIV período renascentista e dividido em três partes: O Inferno, o Purgatório e o Paraíso. São cem cantos protagonizados pelo próprio Dante em companhia do poeta romano Virgílio , que percorreu uma jornada espiritual pelos três reinos além-túmulo. Kit com os 3 livro: O Inferno, O Purgatório e O Paraíso. Editora: Principis Edição: 1, 2021 Autor: Dante Alighieri Idioma: Português Páginas: 720 Dimensões: L 15.50 x A 22.60 x E 4.50 ISBN: 7908312104290', 89.9, 49.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/35d7d7db25a14af55f76f77f9508c60a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F2971228895', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11314007254', 'Livro - Poliana moça - Ciranda Cultural', 'O acidente sofrido por Poliana não foi capaz de tirar sua imensa alegria. Agora, adolescente, ela passa algum tempo na casa de Ruth Carew, uma senhora muito triste. Ao mesmo tempo, Poliana experimenta todos os conflitos, inquietações, emoções e dúvidas que essa nova fase da vida traz, ensinando a todos ao redor como é possível superar qualquer obstáculo com otimismo e vontade de viver. Editora: Ciranda Cultural Edição: 2, 2019 Autor: Eleanor H. Porter Idioma: Português Páginas: 240 Dimensões: L 16.00 x A 23.00 x E 1.40 ISBN: 9788538092360', 29.9, 29.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/ca58208f2b18f7e8a49efb27b114b114', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F11314007254', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4591910193', 'Livro - Histórias diversas - Ciranda Cultural', 'Que o Sítio do Picapau Amarelo é um lugar mágico, todo mundo sabe. O que quase ninguém sabe é como Emília conseguiu consertar as botas de sete léguas do Pequeno Polegar, ou como o Visconde fez para resolver uma confusão entre as violetas do jardim de Emília. Essas e outras histórias estão reunidas nesta obra, e os personagens do sítio estão prontos para viver cada uma delas Editora: Ciranda Cultural Edição: 1, 2019 Autor: Monteiro Lobato Idioma: Português Páginas: 96 Dimensões: L 15.50 x A 22.30 x E 0.80 ISBN: 9788538088851', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/d71ffd95dbd16a814a76aef94ce3e57c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F4591910193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892795455', 'Termogênico 2 Hot - 200g - Max Titanium', 'Descrição do produto 2HOT possui, dentre seus ingredientes, taurina e a cafeína, que auxilia no aumento do estado de alerta e na melhora da concentração. Além disso, conta com alto teor de vitaminas que auxiliam no metabolismo energético contribuindo para o bem-estar e no fornecimento de energia. Sobre o Produto 2HOT possui, dentre seus ingredientes, taurina e a cafeína, que auxilia no aumento do estado de alerta e na melhora da concentração. Além disso, conta com alto teor de vitaminas que auxiliam no metabolismo energético contribuindo para o bem-estar e no fornecimento de energia. Modo de Preparo: Misturar 6g (1 dosador raso) de 2HOT em 200mL (1 copo) de água gelada e agitar com a ajuda de uma colher até completa dissolução. Beber imediatamente Sugestão de uso: Ingerir uma porção pela manhã e outra antes do almoço ou conforme orientação de nutricionista ou médico."', 98.89, 98.89, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-820md-moo12tg9um1176', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1160496125%2F22892795455', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
