INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17559170618', 'Kit Reparo Maquina Vidro Elétrico Ford Fiesta Portas Dianteiras Direito Esquerdo 2002 À 2014', 'É utilizado um processo diferenciado no sistema de prensagem das travas, garantindo assim uma excelente fixação. Os cabos de aço são galvanizados, possuem a quantidade ideal de filamentos tornando-o bem flexível, facilitando a troca do reparo. Os kits Rotax passam por um rigoroso processo de testes de deformação, ruptura, desgaste, quebra e durabilidade, utilizando sempre componentes de alta qualidade técnica, mecânica e estrutural.ESPECIFICAÇÕES TÉCNICAS:Portas: DianteirasLado: Direito e EsquerdoAno: 2002 à 2014Montadora: FordAplicação: Máquina de Vidro Elétrico OriginalO kit acompanha manual de montagem.Para o funcionamento perfeito da máquina, utiliza-se todos os componentes deste kit.CONTEÚDO DA EMBALAGEM:KIT COMPLETORTX0123', 53.2, 53.2, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/0b7bbc0b2d4d53de79d28fa8d194e98d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F17559170618', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
