INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494020035', 'Colete Salva Vidas Náutico Canga Ativa 2 - Ativa', 'O colete de salvamento laranja, disponível em diferentes tamanhos (P, M, G e GG), é ideal para navegação costeira e alto mar nas águas brasileiras. Projetado de acordo com a NORMAM 05/DPC, oferece segurança e conforto, utilizando tecido de poliéster grosso e espuma de polietileno de célula fechada. Sua performance de flutuabilidade é garantida, mantendo a boca do usuário acima da água e garantindo rápida recuperação em caso de emergência. O colete é equipado com um apito laranja, fita refletiva 3M, e tirantes para ajuste ao corpo. A ergonomia é um diferencial, com dobras largas nos ombros para maior conforto durante o uso. Informações essenciais sobre classe e cuidados estão estampadas no colete, promovendo segurança e fácil identificação. É um produto brasileiro focado na durabilidade e eficiência em situações críticas. Ficha Técnica - Tamanhos: P = Até 35 Kg - Tamanhos: M = De 35 a 55 Kg - Tamanhos: G = De 55 a 110 Kg - Tamanhos: GG = Acima de 110 Kg - Cores: Laranja - Classe: CLASSE II - Uso: Para navegação costeira. Alto Mar, águas Brasileiras. - Legislação e Normas: Desenvolvido e fabricado de acordo com a NORMAM 05/DPC. - Performance Flutuabilidade: P = 50N - Performance Flutuabilidade: M = 70N - Performance Flutuabilidade: G = 136N - Performance Flutuabilidade: GG = 156N - Desvira: até 5 segundos - Altura da boca: mais de 12cm para fora d´água - Apito: Apito laranja com amarração e bolso - Refletivo: Fita refletiva 3M, Certificado SOLAS 164.018/6/1; USCG 164.018/8/0 - Tirantes: Passante na cintura para ajuste ao corpo e laço para o pescoço - Origem: Produto Brasileiro - Ergonomia: Dobra larga nos ombros para maior conforto - Informações: Estampadas no colete', 106.1, 106.1, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/e5b1cc3f67985b6c6ba72d1c2ea040fc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F23494020035', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
