INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21675549838', 'Liderança Corajosa | Bill Hybels', 'Liderança CorajosaLíderes que atuam em 360 graus não direcionam seu dom de liderança somente para o sul, às pessoas sob seus cuidados. Eles também aprendem a liderar para o norte, influenciando os que possuem autoridade sobre eles, e para leste e oeste, ao contagiar seus pares. O mais importante, porém, é que aprendem a manter a agulha da bússola centrada, liderando a si mesmos e mantendo a própria vida em harmonia. Assim, podem oferecer aos outros a melhor liderança possível. No mais surpreendente livro que já escreveu, Bill Hybels compartilha o que aprendeu sobre liderança cristã nos quase trinta anos em que lidera a Willow Creek. Liderança corajosa é um presente para você, líder de igreja local, pois, como Bill declara, a igreja local é a esperança do mundo e o futuro dela reside essencialmente nas mãos de seus líderes. Título: Liderança Corajosa Autor: Bill Hybels Páginas: 440 Formato: 23 x 16 x 1 cm Peso: 0.490 kg. ISBN: 9788573676094 Editora: Vida', 44.91, 44.91, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-5taawadmihov14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F21675549838', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
