INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298257505', 'Mangueira Radiador Inferior CELTA 1.0 8v 2001 Ate 2015 - 89310 - 8199', 'Mangueira Radiador Inferior CELTA 1.0 8v 2001 Ate 2015 Inferior Radiador TodosO liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 51.41, 51.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-m6ue7urzpe3691', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22298257505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298338385', 'Pré Filtro Combustível Citroen C4 2018 a 2025 - 1354852 - T040210', 'Pré Filtro Combustível Citroen C4 2018 a 2025 1354852 T040210 Cactus 1.6 16v Flex - Sistema Bosch - filtro externo e internoO pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 46.64, 46.64, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6p-m7bmw4b56geuef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22298338385', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292542916', 'Atuador Marcha Lenta Vw Logus 1995 a 1996 - 109932 - 1602', 'Atuador Marcha Lenta Vw Logus 1995 a 1996 109932 1602 Motor 1.6 8v Gasolina /1.8 8v álcool/Gasolina - (4 Pinos) (Ponta de Ferro) Também conhecido como válvula de controle da marcha lenta, está localizado junto ao corpo de borboleta de aceleração, controlando de forma precisa a rotação do motor, proporcionando um menor consumo de combustível e acelerações rápidas.', 125.03, 125.03, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbne-lmt48a8kdlg07b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22292542916', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597425723', 'Filtro Combustível Peugeot 406 1997 a 2002 - 202651 - FCI1630', 'Filtro Combustível Peugeot 406 1997 a 2002 202651 FCI1630 (Break/ST/Familiale/SVA) - 2.0 16v /(Break/SVA/SVE/Coupe) - 3.0 24v V6 - Gasolina O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 25.94, 25.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lmqnfr92ondm63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21597425723', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
