INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23996672775', 'Soquete Sextavado em Aço Cromo Vanádio 10 mm - Encaixe 1/2" Tramontina PRO', 'Os soquetes da Tramontina PRO são produzidos com sistema Hyper Drive que melhora o acoplamento do produto ao parafuso ou porca, reduzindo as tensões geradas no aperto e prolongando a sua vida útil. Escolha o tamanho e perfil ideal para a sua necessidade e mãos à obra. Um grande avanço na produção dos soquetes é a introdução do conceito "Hyper Drive". Este novo perfil melhora o acoplamento do soquete na porca ou parafuso, reduzindo as tensões geradas no aperto, prolongando a vida do soquete e do elemento de fixação.Soquete forjado em aço cromo vanádio e temperado. Acabamento cromado. DIN 3124. Os soquetes são submetidos a testes rigorosos de torque e de dureza para atender a norma DIN 1711-1.Afrouxar e apertar parafusos e porcas sextavados.As ferramentas são produzidas e testadas conforme normas específicas.Os soquetes da Tramontina PRO são produzidos com sistema Hyper Drive que melhora o acoplamento do produto ao parafuso ou porca, reduzindo as tensões geradas no aperto e prolongando a sua vida útil. Escolha o tamanho e perfil ideal para a sua necessidade e mãos à obra.', 22.5, 22.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7r98o-lkp85zekb9t2a0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23996672775', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
