INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698617491', 'Super Defletor Calha de Chuva Ranger 2013 a 2021 4 Portas Ecoflex', 'Super Defletor Calha de Chuva Ranger 2013 a 2021 4 Portas Ecoflex A Ecoflex possui uma vasta linha de calhas defletores automotivas para os mais diversos modelos. Utiliza matéria-prima de primeira, 100% acrílico, com tecnologia . e instalação simples. Os produtos comercializados pela Ecoflex têm como objetivo trazer conforto e segurança em seu automóvel nos dias de chuva. Com a calha de chuva a água da chuva não entrará no interior do veículo e evita que os vidros embacem. Compatibilidade: • Ranger 2013 a 2021 4 Portas Especificações: • 100% Acrílica; • Proteção e Design; • Contra chuva e sol; • Fixada por Fita Dupla Face .; • Não deixa os vidros embaçarem. Conteúdo da Embalagem: • 4 Calhas Defletores de Chuva • 1 Primer (anti-aderente) Garantia: • 5 Anos (defeito de fabricação) Se tiver alguma dúvida a equipe Renovaccio estará pronta para lhe atender.', 157.67, 157.67, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7qvg7-lhz8m1x9j5t515', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013208711%2F20698617491', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
