INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794744114', 'Freio Á Disco Hidráulico gts Completo + Par de Passador trocador Gts 7v / 8v para bike bicicleta', 'Freio a Disco Hidráulico GTS GHD-100 + Alavanca Rapid Fire 8V – Desempenho e Segurança para sua Bike Sistema completo para frenagens precisas e trocas de marcha eficientes Diferenciais do Kit - Freios hidráulicos GTS de alta performance, garantindo frenagens seguras e progressivas - Acompanha óleo mineral pré-instalado, proporcionando maior eficiência no uso - Alavanca Rapid Fire 8V (compatível também com 7V), oferecendo trocas rápidas e suaves - Montagem e manutenção facilitadas, ideal para quem busca praticidade e durabilidade - Acompanha adaptadores para discos de 160mm e compatibilidade com pastilhas Shimano M395/M445/M315 Especificações Técnicas Alavanca Rapid Fire GTS 8V - Fabricante: GTS - Compatível com transmissões de 8V (também pode ser usada em 7V) - Cor: Preta - Material: Nylon e aço - Peso aproximado: 285g - Acompanha 1 par de passadores e 2 cabos de câmbio Freio a Disco Hidráulico GTS GHD-100 - Marca: GTS - Modelo: GHD-100 - Sistema hidráulico, utiliza óleo mineral - Acompanha óleo (necessário sangria antes do uso) - Possui regulagem de curso do manete - Mangueira: Dianteiro 85cm / Traseiro 155cm - Acompanha 2 adaptadores de freio 160mm - Compatível com pastilhas Shimano M395/M445/M315 (quadrada) - Peso aproximado: 746g (com adaptadores) Conteúdo da Embalagem - 1 par de alavancas Rapid Fire GTS 8V - 2 cabos de câmbio - 1 par de freios a disco hidráulicos GTS GHD-100 - 2 discos (rotor) de 160mm - 2 adaptadores IS Mount Atenção - O freio já acompanha óleo, mas é recomendado realizar a sangria antes do uso - Não acompanha pastilhas - Produto original GTS, acompanha nota fiscal Atualize sua bike com um sistema de freios hidráulicos e trocas de marcha precisas', 154.9, 154.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-81zwc-mid2a91nkvlv22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22794744114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28138230308', 'Carrinho para Carga 250kg com Pneu Câmara 3,25/8 EV-CC250 EVALD', 'Carrinho para Carga 250kg com Pneu Câmara 3,25/8 EV-CC250 EVALD Transporte pesado com segurança e desempenho é o que você encontra no Carrinho para Carga EV-CC250 da EVALD. Desenvolvido para suportar até 250 kg, esse modelo com rodas de pneu com câmara é a solução ideal para quem trabalha em ambientes industriais, depósitos, armazéns ou mesmo em serviços de logística e distribuição. Com estrutura metálica reforçada e pintura eletrostática a pó, o carrinho oferece resistência superior e longa durabilidade, mesmo em condições exigentes. Além de robusto, é funcional: sua construção inteligente e as rodas com pneus câmara garantem excelente desempenho em pisos variados, como cimento, asfalto, calçadas irregulares e até terrenos mais acidentados. Se você busca eficiência no transporte manual de cargas, esse é o equipamento certo para otimizar seu tempo e proteger sua integridade física. Benefícios Alta capacidade de carga: Projetado para suportar até 250 kg, o modelo EV-CC250 é ideal para movimentar volumes pesados sem esforço, contribuindo diretamente para o aumento da produtividade no trabalho. Rodagem com pneu câmara: As rodas com câmara 3,25/8 proporcionam excelente aderência e absorção de impactos, favorecendo o uso em superfícies irregulares com maior estabilidade. Durabilidade garantida: Sua estrutura é construída em metal resistente com acabamento em pintura eletrostática azul, que protege contra corrosões e desgastes causados por uso intenso ou condições climáticas adversas. Ergonomia e segurança: A altura de 130 cm oferece boa ergonomia para o operador, reduzindo o esforço físico e evitando sobrecarga na coluna. A manobrabilidade eficiente reduz o risco de acidentes, principalmente em ambientes com grande movimentação. Versatilidade de aplicações: Pode ser utilizado em supermercados, centros de distribuição, empresas de mudanças, obras civis, almoxarifados e até em pequenas empresas ou uso doméstico para movimentar cargas mais pesadas com conforto. Características Técnicas Capacidade de carga: 250 kg Altura total: 130 cm Largura: 55 cm Comprimento: 26 cm Peso líquido: 10,70 kg Tipo de roda: com pneu câmara 3,25/8 Pintura: eletrostática a pó Componentes: chassi e rodas Código EVALD: 00778 Público-alvo Este carrinho de carga é indicado especialmente para profissionais de logística, almoxarifes, trabalhadores da construção civil, operadores de armazéns e empreendedores que atuam com movimentação de produtos pesados. Também pode ser uma solução eficiente para agricultores, comerciantes ou para quem precisa de um equipamento confiável e durável no dia a dia. Mais sobre a linha EVALD A linha EVALD traduz essa qualidade em produtos robustos, com design funcional e voltados à realidade do trabalho pesado. Cada carrinho é produzido com rigor técnico e foco no desempenho e segurança, resultando em equipamentos confiáveis para as mais diversas aplicações. Se você precisa de uma solução prática e durável para movimentação de cargas em diversos ambientes, este carrinho é a escolha certa para manter seu fluxo de trabalho ágil, seguro e com o mínimo esforço físico. * Imagens meramente ilustrativas.', 348.26, 348.26, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdx4-mbnuzu01xcv923', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F28138230308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998530539', 'Par Pneus Bicicleta Kenda Kontact Colorido Aro 20 X 1.95 Bmx Bike Cross', 'Pneu para rodas de bicicletas com aros 20", com uma espessura de 1.95. O Pneu Kenda Kontact é uma ótima opção para sua bike pois além de resistente, ele tem uma alta durabilidade e aderência a qualquer tipo de solo. Marca: Kenda Modelo: Kontact Cor: Vermelho, Azul ou Amarelo Peso aproximado: 640g Aro: 20" Material: Borracha com Arame Medida: 20 x 1.95 (50 - 406) Modalidade: BMX Pressão Máxima: 40psi - 65psi', 152.34, 152.34, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rauf-ma7h4r9p3z5v9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23998530539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694236877', 'Câmara de Ar Paco – Compatível com Aros 16, 20, 24, 26, 27, 29, para Bicicleta', 'Câmara de Ar Paco para Bicicletas aros 16, 20, 24 ,26, 26 ceci, 27, 29 DESCRIÇÃO: Marca: Paco Material: Borracha / Butílica Válvula: 35mm Schrader (grossa) ou Válvula: 48mm Presta ( Fina) Modalidade: MTB, Urbano, Passeio Câmara desenvolvida com borracha butílica, muito mais durável e resistente. Performance e qualidade, são itens indispensáveis para sua bike, e com esta câmara, você terá tudo isso e muito mais..', 17.09, 17.09, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-mcdon6ej8dcpf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23694236877', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
