INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198815361', 'Tamanco Dakota de Salto Bloco Feminina Y9151', 'Produto marca Dakota. Descubra o Tamanco Dakota de Salto Bloco, a escolha perfeita para a mulher moderna que busca conforto, estilo e versatilidade em um só calçado. Com seu salto bloco alto de 6,5 cm, você ganha a elevação ideal sem abrir mão da estabilidade, garantindo um caminhar seguro e elegante em qualquer ocasião. o bico de contorno quadrado confere um toque de modernidade e sofisticação, alinhado às últimas tendências da moda, enquanto o visual monocolor assegura uma peça atemporal e fácil de combinar. Este tamanco não é apenas um item de moda; é um investimento no seu bem-estar. a peça metalizada sobre a tira de dedo adiciona um detalhe exclusivo que eleva o design, proporcionando um charme extra e um visual que transita facilmente do dia a dia ao lazer. Imagine-se desfrutando de um almoço com amigas ou de um evento especial, sentindo-se confiante e pode. o material sintético de alta qualidade e o peso otimizado de 0,623 kg garantem a durabilidade e a leveza que seus pés merecem. Garanta já o seu Tamanco Dakota e transforme seu guarda-roupa! Ideal para quem busca um calçado prático e elegante, ele se tornará seu companheiro inseparável para todas as ocasiões. Não perca a oportunidade de ter um item que combina moda, conforto e versatilidade incomparáveis. Peso: 0,623 kg Altura do salto: 6,5 cm', 189.9, 169.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-md37y6wlohk643', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F22198815361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
