INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498953779', 'Esquadro Magnético Capacidade 30Kg EM-9030 Soldador Super Tork', 'Esquadro Magnético para Solda EM-9030 Super Tork O esquadro magnético 30kg EM-9030 contribui com o trabalho do operador de solda, corte plasma ou montagem de estruturas metálicas, pois é considerado a terceira mão do soldador! Ele permite o correto posicionamento das peças de aço antes de iniciar o processo de soldagem, deixando as mãos do operador livre para ponteamento, além de oferecer precisão em variados ângulos, é ideal para serralherias, fabrica de moveis de metal, soldagem, montagem, estruturas, grades e ponteamento de solda rápido e preciso, devido a seu poder de segurar peças. Maior precisão na soldagem. Uso indicado para serralheria. Utilizado em soldagem, montagem, estruturas e grades. Ponteamento de solda rápido e preciso. Menor mão de obra. Diminui o risco de acidentes. Informações Técnicas: Altura: 102mm Largura: 155mm Espessura: 17mm Modelo: EM-9030 Marca: Super Tork Aplicação: 45°graus, 90°graus e 135°graus Capacidade: 30Kg Garantia: 3 Meses', 35.88, 28.1, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbk9-llb8fjufbu0c26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F20498953779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694176165', 'Garrafa Térmica Grande Magic Pump 1,8 Litros Cor Preta Decorada Cafe Termolar', 'A Garrafa Térmica Magic Pump é a parceira ideal para o seu dia a dia. Seu exclusivo sistema de bomba de pressão, proporciona um maior fluxo e estabilidade ao bombear. Fabricada em material injetado, apresenta maior resistência auto brilho. Podendo ser utilizada nos mais variados ambientes. Acabamento: Lisa Capacidade: 1,8 Litros Conservação Térmico Quente: 12 Horas Conservação Térmico Frio: 24 Horas Isolamento Térmico: Ampola de Vidro Livre de BPA: Sim Material Atóxico: Sim Material Externo: Plástico Sistema de Servir: Bomba de Pressão. Dimensões Aproximadas: Altura: 37,2cm Largura: 13,5cm Comprimento: 15,6cm Garantia: Os componentes plásticos são garantidos por 90 dias contra defeitos de fabricação. Não incluem na garantia problemas por uso indevido do produto ou quebras.', 89.99, 84.2, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7ra2m-mbfks91tyic6f4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F22694176165', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
