INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897977095', 'Gel de Limpeza L''Oréal Paris Glycolic Bright Anti-Marcas 150g', 'Gel de Limpeza L''Oréal Paris Glycolic-Bright Anti Marcas Após anos de pesquisa, L''Oréal Paris apresenta sua mais potente fórmula para reduzir intensamente e rapidamente as marcas da pele. Com 5x ações', 45.79, 45.79, NULL, 'Beauty > Beauty Tools > Facial Care Tools', 'https://cf.shopee.com.br/file/sg-11134201-820m8-mnw44epos45kab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22897977095', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697579777', 'Kit 2 Esmalte Risqué Diamond Gel Chá Branco Natural 9,5ml', 'O Esmalte Risqué Diamond Gel Chá Branco tem possui alto brilho e durabilidade. O pincel contém 800 cerdas o que aumenta a cobertura e precisão na aplicação do esmalte. Sua fórmula hipoalergênica é livre de substâncias que causam alergia. Para garantir o efeito gel, após a aplicação do esmalte com cor (Passo 1), passe o Top Coat Fixador Diamond Gel Risqué (Passo 2), que foi criado especialmente para proporcionar a durabilidade e alto brilho. Você bonita por mais tempo! Conheça toda a linha Diamond Gel: são 20 cores exclusivas.', 29.23, 29.23, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-825at-mqmd5g2z239eaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23697579777', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193139678', 'Pillow Top Solteiro Buddemeyer Vision Fill100% Algodão Branco', 'CARACTERÍSTICA DO PRODUTO: Maior conforto - Acetinado - Alta resistência - Não alérgico - Alta durabilidade - Lavável à máquina Tecido 100% algodão - Cetim 233 fios - Enchimento 100% poliéster Qualidade e design Buddemeyer CONTEÚDO DA EMBALAGEM: Contém: 1 pillow top 100x200x7cm COMPOSIÇÃO: Tecido da frente em 100% algodão cetim 233 fios com acabamento especial. Enchimento em 100% poliéster microfibra extra macia TIPO DE MATERIAL: Tecido da frente em 100% algodão cetim 233 fios; enchimento em 100% poliéster DESCRIÇÃO: Pillow Top solteiro VISION FILL. Um produto que proporciona muito mais conforto e aconchego para o seu momento de descanso, possui toque acetinado e apresenta alta resiliência e durabilidade; possui gramatura de 1000 g/m². Podem ir à máquina sempre que for necessário, oferecendo a higienização perfeita. Produto não alérgico. Produzidos em 100% algodão cetim 233 fios com acabamento especial, tem seu enchimento em 100% poliéster microfibra extra macia. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lavar antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 40°C em processo suave. O melhor sabão para manter as características do produto é o de coco ou neutro, não colocar diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Não passar. Não lavar a seco.', 760.76, 608.59, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/sg-11134201-7rffs-m9kw5actfqgwab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F23193139678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
