INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697579719', 'Kit 2 Sabonete Asepxia Enxofre Ação Antioleosidade 80g', 'SABONETE ASEPXIA ENXOFRE Pele muito oleosa. Enriquecido com Enxofre. Controla a oleosidade. Limpa sem ressecar a pele. Combate e ajuda a prevenir cravos e espinhas. O novo Asepxia Sabonete Antiacne Enxofre limpa profundamente os poros e reduz o excesso de oleosidade da sua pele, combatendo cravos e espinhas com a força do enxofre, um ingrediente de origem natural com ação antimicrobiana. Sabemos que você está sempre mudando, e por isso mudamos com você! Evoluímos toda a linha Asepxia com a nova fórmula avançada Hidro-Force, o equilíbrio perfeito entre tecnologia e natureza. Sua combinação única de ácidos salicílico, glicólico e ingredientes de origem natural combate cravos e espinhas enquanto equilibra a oleosidade da sua pele, deixando-a mais saudável e bonita todos os dias. Fórmula multibenefícios, enriquecida com enxofre e máxima concentração de ácido salicílico, que: Ajuda a prevenir espinhas. Reduz a irritação. Reduz o excesso de oleosidade. Desobstrui os poros. Modo de usar: Aplique com uma leve massagem no rosto úmido, de manhã e à noite, insistindo nas áreas com cravos e espinhas. Enxágue logo em seguida.', 19.98, 19.98, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-82584-mqmx547p1tds78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23697579719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494204357', 'Kit 3 Bebida Láctea Emana Protein com 23g de Proteína Sabor Caramel Coffee Zero Lactose 250ml', 'Emana Protein Caramel Coffee - Bebida Láctea Zero Lactose Desperte seus sentidos com a Emana Protein Caramel Coffee! Esta deliciosa bebida láctea foi cuidadosamente elaborada para atender às suas necessidades nutricionais, oferecendo impressionantes 23g de proteínas por porção de 250ml. Ideal para quem tem restrições à lactose, nossa formulação é 100% livre de lactose, garantindo uma experiência saborosa e leve. O sabor rico do café combinado com o toque doce do caramelo cria uma indulgência que não só satisfaz seu paladar, mas também fornece a energia necessária para o seu dia a dia. Perfeita para o café da manhã, um lanche pós-treino ou um refresco durante o dia, a Emana Protein é a escolha ideal para quem busca um estilo de vida ativo e saudável. Experimente agora e descubra como um lanche nutritivo pode ser delicioso! Não deixe de levar a Emana Protein Caramel Coffee com você e crie momentos de prazer e bem-estar todos os dias. Ingredientes : Leite desnatado concentrado, proteína de soro do leite concentrada, colágeno hidrolisado, polidextrose, café solúvel, enzima lactase, vitamina D, estabilizantes celulose microcristalina, hidrogenofosfato de di-potássio, hidrogenofosfato de di-sódio, fosfato trissódico, algas marinhas euchema processadas, corante caramelo I, edulcorante glicosídeos de esteviol (stevia) e aromatizantes. Alérgicos: Contém Glúten* : Não Contém Aromatizante* : Sintético Idêntico ao Natural Contém Lactose* : Não Contém Contém Glicose : Contém Contém Leite : Contém Contém Leite - Derivados : Contém', 49.87, 49.87, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-825as-mqmx3zlrc5xpf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23494204357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
