INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499600940', 'Kit 12 Desempenadeiras Plastica Lisa 17x30cm Com Espuma Roma', 'O Kit com 12 Desempenadeiras de Plástico com Espuma 17x30cm Roma é a escolha ideal para quem busca um acabamento perfeito em projetos de construção e acabamento. Com base de plástico resistente, espuma que proporciona uma aplicação mais suave e uniforme, e cabo plástico ergonômico, essas desempenadeiras são ideais para aplicação de rebocos, massa corrida e outros revestimentos. O Kit com 12 é ideal para garantir um acabamento de alta qualidade e sem falhas, proporcionando praticidade e eficiência para os profissionais da construção e acabamento. Vantagens: Aplicação uniforme: A camada de espuma facilita a distribuição de materiais, garantindo um acabamento mais suave e sem marcas. Alta durabilidade: Base de plástico resistente e material de espuma de alta qualidade para maior vida útil. Conforto no manuseio: Cabo plástico ergonômico que proporciona um bom controle e conforto durante o uso. Versatilidade: Ideal para reboco, aplicação de massa corrida, gesso e outros revestimentos em superfícies lisas. Kit econômico: 12 unidades, perfeito para equipes de trabalho ou reposição. Dados Técnicos: Marca: Roma Dimensões: 17x30cm Material da Base: Plástico resistente Material da Espuma: Espuma de alta densidade Material do Cabo: Plástico ergonômico Quantidade: 12 unidades Aplicação: Reboco, massa corrida, gesso e outros revestimentos em superfícies diversas Garantia: Garantia de 3 meses oferecida pelo fabricante', 249.9, 133.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5y92960s9cgb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F19499600940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
