INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298186184', 'Short Venum Training Urban Azul', 'Bermuda Venum Training Urban O Short Venum Training Urban é a escolha definitiva para quem busca desempenho e conforto máximo nos treinos. Projetada com materiais de alta qualidade e design moderno, essa bermuda é ideal para atividades intensas como musculação, artes marciais, corridas e outros exercícios que exigem total liberdade de movimento. O modelo conta com um elástico na cintura que oferece ajuste firme e confortável, permitindo que você se mova com confiança e segurança. Os bolsos laterais proporcionam praticidade, permitindo levar itens essenciais sem abrir mão do estilo e do conforto. A presença de elastano no tecido confere à bermuda uma flexibilidade única, acompanhando cada movimento sem restrições. A logomarca Venum, termosoldada, adiciona um toque de sofisticação e durabilidade ao design, resistindo ao uso intenso e às lavagens frequentes. Leve e de secagem ultrarrápida, esta bermuda é perfeita para quem busca evoluir em sua atividade física favorita, com uma peça que oferece alta resistência e performance. Com o Short Venum Training Urban, você estará pronto para elevar seu desempenho a um novo patamar, contando com a combinação perfeita entre estilo, conforto e funcionalidade! CARACTERÍSTICAS TÉCNICAS • SKU: BR-VENUM-1112-004 • Peso: 200 Gramas • Composição: 94% Poliéster / 6% Elastano • Cor: Azul • Shorts: Boardshorts, Compressão , Fightshorts, MMA, Muay Thai, Shorts, Training, Vale tudo • Esporte: Boxe, Jiu Jitsu, Muay Thai, MMA, Treino, Karate • Fabricante: Venum Brasil • Gênero: Masculino • Tipo de artigo: Bermuda de água, Bermuda Muay Thai, Bermudas • User level: Beginner, Intermediate, Advanced', 199.9, 199.9, NULL, 'Men Clothes > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-7rfhu-m9z4xejoc3kmee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1054067345%2F19298186184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199168763', 'Jibbitz™ Spider-Man 1 Único', 'Os maravilhosos Jibbitz™Charmssão acessórios que você colocanos seus Crocs.Eles são fáceis de colocareretirar, para que você possa mudar seusestiloa qualquer momento.Adicione os encantos dos Jibbitz™ Charms aos seus Crocsparamostrar que seu estilo e criatividade são únicos!Depersonagens conhecidos aemojispopulares. Tem algo adizer?Diga! Se amaalienígenas e unicórnios?Mostre!Fácil de colocar e ser removido,combina com qualquer look,companhia perfeita com detalhes bem visíveis. Não é um brinquedo. Não se destina a crianças menores de 3 anos de idade. As imagens doproduto podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 24.99, 24.99, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-821fs-mgw9po0xsu149d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F22199168763', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999136276', 'Camiseta Juvenil Menino Pizza Club Beats Branco', 'Peça-chave para composições despojadas, a Camiseta Elian Beats é a escolha perfeita para os teens que curtem uma vibe divertida. Feita em meia malha, ela possui mangas curtas e estampa localizada na parte frontal. O destaque é a sua maxi estampa nas costas, que traz o tema "Pizza Club", garantindo um toque descontraído ao visual. Ideal para usar com bermudas ou calças, aposte nesse item leve e estiloso para aproveitar momentos com os amigos com muito conforto e originalidade.Detalhes da peça: • Feita em meia malha • Possui mangas curtas • Possui estampa com o tema "Pizza Club" • Ideal para aproveitar momentos com os amigos', 64.9, 32.45, NULL, 'Baby & Kids Fashion > Boy Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-8259w-mr1toqbnur5x7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F22999136276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693677654', 'Filtro Combustível Jac Motors T6 2014 a 2016 - 1353652 - FCI1288', 'Filtro Combustível Jac Motors T6 2014 a 2016 1353652 FCI1288 (Jet) - 2.0 16V Flex - Mecânico (Alumínio) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 56.25, 56.25, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-823p6-moyag80ntlajdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23693677654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293747215', 'Mangueira Radiador Superior GM SPIN 1.8 8v 2012 Ate 2016 - 89319 - 8702', 'Mangueira Radiador Superior GM SPIN 1.8 8v 2012 Ate 2016 (Superior)O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 34.15, 34.15, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6z-m6u5wh15motdf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23293747215', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
