INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207132057', 'Conjunto Cachorrinhos Infantil Menina Elian Laranja', 'O Conjunto Elian é composto por blusa em cotton leve e vestido em moletom felpado. A blusa possui mangas longas com elástico nos punhos e estampa lisa, enquanto o vestido conta com alças e bolsos laterais, garantindo praticidade ao dia a dia. Além disso, sua estampa divertida de cachorrinhos traz um toque lúdico e encantador ao visual. Ideal para passeios em família ou dias de diversão, é a combinação perfeita entre estilo e conforto. Aposte neste look cheio de fofura!Detalhes da peça: • Conjunto composto por blusa e vestido • Feito em cotton leve e moletom felpado • Blusa com mangas longas • Vestido com alças • Possui estampa de cachorrinhos • Possui bolsos laterais • Ideal para passeios e dias divertidos', 139.9, 97.93, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-82589-mr1tqsknu7et13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58207132057', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994820160', 'Vestido Estampado Menina Marisol', 'O vestido da Marisol é confeccionado em microfibra leve com elastano, oferecendo conforto, leveza e liberdade de movimento. Todo estampado, apresenta um visual moderno e alegre, perfeito para os dias quentes. Com decote quadrado e alças finas, o modelo valoriza o visual com delicadeza e estilo, proporcionando um caimento leve e feminino ideal para diversas ocasiões.', 151.9, 75.95, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mju9ahu3bqwx1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F22994820160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
