INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203026021', 'Pistola De Pintura Airless Spray 3600psi Alta Pressão Com Ponta De Pulverização 517', 'Pistola de Pulverização Airless com Bico 517 – Uso Profissional Indicada para aplicações de pintura airless em diversos tipos de projetos, esta pistola é compatível com praticamente todas as máquinas airless do mercado. Trabalha com alta pressão, garantindo pulverização uniforme, acabamento liso e excelente rendimento de tinta. O conector giratório oferece maior mobilidade durante o uso, facilitando trabalhos contínuos com mais precisão e conforto. Fabricada com materiais resistentes, proporciona durabilidade, fácil manutenção e desempenho confiável para uso profissional em pinturas residenciais, industriais e automotivas. Itens Inclusos: ✅ 1 Pistola de pintura Airless ✅ 1 Bico reversível 517 (amarelo) ✅ 1 Protetor de bico universal (vermelho) Especificações Técnicas: Compatibilidade: Máquinas de pulverização airless Pressão máxima de trabalho: 3600 PSI / 248 bar Gatilho: 4 dedos Conexão: Giratória Sistema de filtragem interno: Sim Material: Alumínio, ferro e plástico Cor: Prata Aplicações: Pulverização de tintas, primers, vernizes, stains e outros revestimentos Indicação de uso: Paredes, estruturas, móveis, portões e superfícies em geral Por que escolher este produto? Produto novo e de alta eficiência Compatibilidade universal com máquinas airless Bico 517 para excelente padrão de pulverização Construção robusta e fácil manutenção Pronta entrega e envio rápido Compra 100% segura', 139.9, 139.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-82612-mja8o09834zp84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F58203026021', NULL, NULL, '2026-07-28T02:11:31.70845